def request_entity_too_large(e):
    flash('Upload terlalu besar. Maksimal 20 MB untuk bukti pembayaran.', 'error')
    return redirect(request.referrer or url_for('dashboard'))

def get_conn():
    conn = sqlite3.connect(DB_NAME)
    conn.row_factory = sqlite3.Row
    conn.execute('PRAGMA foreign_keys = ON')
    return conn

def q_all(sql, params=None):
    conn = get_conn()
    rows = conn.execute(sql, params or []).fetchall()
    conn.close()
    return rows

def q_one(sql, params=None):
    conn = get_conn()
    row = conn.execute(sql, params or []).fetchone()
    conn.close()
    return row

def exec_sql(sql, params=None, many=False):
    conn = get_conn()
    cur = conn.cursor()
    if many:
        cur.executemany(sql, params)
    else:
        cur.execute(sql, params or [])
    conn.commit()
    rid = cur.lastrowid
    conn.close()
    return rid

def hash_password(text):
    return generate_password_hash(text, method='pbkdf2:sha256', salt_length=16)

def verify_password(stored, password):
    stored = stored or ''
    if len(stored) == 64 and all(c in '0123456789abcdef' for c in stored.lower()):
        return hashlib.sha256(password.encode()).hexdigest() == stored
    try: return check_password_hash(stored, password)
    except Exception: return False

def now_str():
    return datetime.now().strftime('%Y-%m-%d %H:%M:%S')

def today_str():
    return str(date.today())

def month_key(date_str):
    return str(date_str)[:7]

def gen_code(prefix):
    return f"{prefix}-{datetime.now().strftime('%Y%m%d%H%M%S')}"

def get_branch_id():
    """Return authoritative branch for the logged-in user; None means central/PUSAT."""
    uid = session.get('user_id')
    if uid:
        row = q_one('SELECT branch_id FROM users WHERE id=? AND active=1', [uid])
        branch_id = row['branch_id'] if row else None
        session['branch_id'] = branch_id
        return int(branch_id) if branch_id else None
    return None

def branch_sales_scope(alias='s'):
    """SQL scope for transaction pages. Admin/bendahara may see all; branch roles see only their branch."""
    user = current_user()
    branch_id = get_branch_id()
    if user and user['role'] in ('admin', 'bendahara', 'supervisor'):
        return '', []
    if branch_id:
        return f' AND {alias}.branch_id=?', [branch_id]
    return f' AND {alias}.branch_id IS NULL', []

def resolve_operational_branch(user=None):
    # Resolve branch without treating an operational account as PUSAT.
    # Recovery uses only one unambiguous branch from the user transaction history.
    user=user or current_user()
    bid=get_branch_id()
    if bid:
        return int(bid), ''
    if not user or user['role'] not in ('branch_admin','branch_cashier','kasir'):
        return None, ''
    candidates=q_all('''SELECT DISTINCT branch_id FROM (
        SELECT branch_id FROM sales WHERE cashier_id=? AND branch_id IS NOT NULL
        UNION ALL SELECT stock_branch_id branch_id FROM quick_cashier_queue WHERE created_by=? AND stock_branch_id IS NOT NULL
    ) ORDER BY branch_id''',[user['id'],user['id']])
    ids=[int(x['branch_id']) for x in candidates if x['branch_id']]
    if len(ids)==1:
        bid=ids[0]
        exec_sql('UPDATE users SET branch_id=? WHERE id=? AND branch_id IS NULL',[bid,user['id']])
        session['branch_id']=bid
        log_action('BRANCH_RECOVERED','users',user['id'],f'Cabang dipulihkan dari transaksi pengguna: {bid}')
        return bid,'Cabang akun dipulihkan otomatis dari riwayat transaksi yang konsisten.'
    return None,'Akun belum memiliki cabang. Halaman tetap dibuka dalam mode aman tanpa data PUSAT.'

def require_operational_branch(user=None):
    # Compatibility wrapper: never redirects. Caller decides safe empty-state behavior.
    bid,_=resolve_operational_branch(user)
    return bid

def sale_visible_to_current_user(sale):
    user=current_user(); bid=get_branch_id()
    if not sale: return False
    if user['role'] in ('admin','bendahara','supervisor','manager'): return True
    return bool(bid and sale['branch_id'] and int(sale['branch_id'])==int(bid))


def is_branch_role(user=None):
    user = user or current_user()
    return bool(user and user['role'] in ('branch_admin','branch_cashier','kasir'))

def branch_stock_summary(branch_id):
    if branch_id:
        return q_one('''SELECT COUNT(*) product_count,
                        COALESCE(SUM(CASE WHEN COALESCE(pbs.stock,0)<=COALESCE(pbs.min_stock,p.min_stock,0) THEN 1 ELSE 0 END),0) low_count,
                        COALESCE(SUM(COALESCE(pbs.stock,0)*COALESCE(p.buy_price,0)),0) stock_value
                        FROM products p LEFT JOIN product_branch_stock pbs ON pbs.product_id=p.id AND pbs.branch_id=? WHERE p.active=1''',[branch_id])
    return q_one('''SELECT COUNT(*) product_count,COALESCE(SUM(CASE WHEN COALESCE(stock,0)<=COALESCE(min_stock,0) THEN 1 ELSE 0 END),0) low_count,
                    COALESCE(SUM(COALESCE(stock,0)*COALESCE(buy_price,0)),0) stock_value FROM products WHERE active=1''')


def get_branch_name(branch_id=None):
    """Get branch name from id or return 'PUSAT'."""
    if not branch_id:
        return 'PUSAT'
    row = q_one('SELECT name FROM koperasi_branches WHERE id=?', [branch_id])
    return row['name'] if row else 'PUSAT'

def get_product_stock(product_id, branch_id=None):
    """Get stock for a product in a specific branch. If branch_id is None, return PUSAT stock."""
    if not branch_id:
        row = q_one('SELECT stock FROM products WHERE id=?', [product_id])
        return float(row['stock']) if row else 0
    row = q_one('SELECT stock FROM product_branch_stock WHERE product_id=? AND branch_id=?', [product_id, branch_id])
    return float(row['stock']) if row else 0

def update_branch_stock(product_id, qty, branch_id=None, operation='add'):
    """Add or subtract stock for a product in a branch.
    If branch_id is None, operate on PUSAT (products.stock).
    operation: 'add' or 'subtract'
    """
    if not branch_id:
        # PUSAT — use products table
        if operation == 'add':
            exec_sql('UPDATE products SET stock = COALESCE(stock,0) + ? WHERE id=?', [qty, product_id])
        else:
            current = get_product_stock(product_id, None)
            if current < qty:
                raise ValueError(f'Stok pusat tidak cukup. Tersedia {current}, diminta {qty}')
            exec_sql('UPDATE products SET stock = COALESCE(stock,0) - ? WHERE id=?', [qty, product_id])
    else:
        # Cabang — use product_branch_stock
        if operation == 'add':
            exec_sql('INSERT INTO product_branch_stock(product_id, branch_id, stock) VALUES (?, ?, ?) ON CONFLICT(product_id, branch_id) DO UPDATE SET stock = COALESCE(stock,0) + ?',
                     [product_id, branch_id, qty, qty])
        else:
            current = get_product_stock(product_id, branch_id)
            if current < qty:
                raise ValueError(f'Stok cabang tidak cukup. Tersedia {current}, diminta {qty}')
            exec_sql('UPDATE product_branch_stock SET stock = COALESCE(stock,0) - ? WHERE product_id=? AND branch_id=?',
                     [qty, product_id, branch_id])

def ensure_product_branch_stock(product_id, branch_id):
    """Ensure product_branch_stock row exists, create with 0 if not."""
    if not branch_id:
        return
    row = q_one('SELECT id FROM product_branch_stock WHERE product_id=? AND branch_id=?', [product_id, branch_id])
    if not row:
        exec_sql('INSERT OR IGNORE INTO product_branch_stock(product_id, branch_id, stock, min_stock) VALUES (?, ?, 0, 0)',
                 [product_id, branch_id])

def rupiah(x):
    try:
        return f"Rp {float(x):,.0f}".replace(',', '.')
    except Exception:
        return 'Rp 0'

def to_excel(data_dict, filename):
    """Export dict of lists to Excel file."""
    output = BytesIO()
    with pd.ExcelWriter(output, engine='openpyxl') as writer:
        for sheet_name, rows in data_dict.items():
            df = pd.DataFrame(rows)
            df.to_excel(writer, sheet_name=sheet_name, index=False)
    output.seek(0)
    return send_file(output, as_attachment=True, download_name=filename, mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')

