# =========================
@app.route('/shu/report', methods=['GET','POST'])
@login_required
@role_required('admin', 'bendahara')
def shu_report():
    year = int(request.values.get('year', datetime.now().year))
    period = ensure_shu_period(year)
    if request.method == 'POST':
        action = request.form.get('action','')
        if action == 'save_period':
            start_date = request.form.get('start_date') or f'{year}-01-01'
            end_date = request.form.get('end_date') or f'{year}-12-31'
            net, revenue, expense = shu_net_profit(start_date, end_date)
            distributable = parse_float(request.form.get('distributable_profit',0))
            reserve_percent = parse_float(request.form.get('reserve_percent',40))
            sw = parse_float(request.form.get('savings_weight',50)); bw=parse_float(request.form.get('shopping_weight',30)); lw=parse_float(request.form.get('loan_weight',20))
            note = request.form.get('note','').strip()
            status = request.form.get('status','DRAFT')
            exec_sql('''INSERT INTO shu_periods(year,start_date,end_date,net_profit_snapshot,distributable_profit,reserve_percent,savings_weight,shopping_weight,loan_weight,status,note,created_by,updated_by,updated_at)
                        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                        ON CONFLICT(year) DO UPDATE SET start_date=excluded.start_date,end_date=excluded.end_date,net_profit_snapshot=excluded.net_profit_snapshot,distributable_profit=excluded.distributable_profit,reserve_percent=excluded.reserve_percent,savings_weight=excluded.savings_weight,shopping_weight=excluded.shopping_weight,loan_weight=excluded.loan_weight,status=excluded.status,note=excluded.note,updated_by=excluded.updated_by,updated_at=excluded.updated_at''',
                     [year,start_date,end_date,net,distributable,reserve_percent,sw,bw,lw,status,note,session.get('user_id'),session.get('user_id'),now_str()])
            flash('Setting periode SHU berhasil disimpan.', 'success')
        elif action == 'member_adjust':
            member_id = int(request.form.get('member_id') or 0)
            manual_amount = parse_float(request.form.get('manual_amount',0))
            note = request.form.get('adjust_note','').strip()
            if member_id:
                exec_sql('''INSERT INTO shu_member_adjustments(year,member_id,manual_amount,note,created_by)
                            VALUES(?,?,?,?,?) ON CONFLICT(year,member_id) DO UPDATE SET manual_amount=excluded.manual_amount,note=excluded.note,created_by=excluded.created_by,created_at=CURRENT_TIMESTAMP''',
                         [year,member_id,manual_amount,note,session.get('user_id')])
                flash('Adjust SHU member berhasil disimpan.', 'success')
        elif action == 'opening_balance':
            balance_date = request.form.get('balance_date') or today_str()
            account_id = int(request.form.get('account_id') or 0)
            direction = request.form.get('direction','DEBIT')
            amount = parse_float(request.form.get('amount',0))
            note = request.form.get('ob_note','Saldo awal').strip()
            if account_id and amount > 0:
                account = q_one('SELECT account_code,account_name FROM accounts WHERE id=?',[account_id])
                desc = f'Saldo awal {account["account_code"]} {account["account_name"]} - {note}' if account else f'Saldo awal - {note}'
                debit = amount if direction == 'DEBIT' else 0
                credit = amount if direction == 'CREDIT' else 0
                entry_no = gen_code('OB')
                exec_sql('''INSERT INTO journal_entries(entry_no,entry_date,description,account_id,debit,credit,ref_type,ref_id,created_by)
                            VALUES(?,?,?,?,?,?,?,?,?)''', [entry_no,balance_date,desc,account_id,debit,credit,'opening_balance',0,session.get('user_id')])
                exec_sql('INSERT INTO opening_balances(balance_date,account_id,direction,amount,note,journal_ref,created_by) VALUES(?,?,?,?,?,?,?)',
                         [balance_date,account_id,direction,amount,note,entry_no,session.get('user_id')])
                flash('Saldo awal berhasil dicatat ke jurnal.', 'success')
        return redirect(url_for('shu_report', year=year))

    period = ensure_shu_period(year)
    start_date, end_date = period['start_date'], period['end_date']
    net_profit, revenue, expense = shu_net_profit(start_date,end_date)
    members = q_all('SELECT * FROM members ORDER BY member_code')
    rows=[]; total_shu=0
    for m in members:
        d=calculate_shu_detail(m['id'], year); total_shu += d['total']; rows.append({'member':m,'d':d})
    accounts = q_all('SELECT id,account_code,account_name,category FROM accounts ORDER BY account_code')
    opening = q_all('''SELECT ob.*,a.account_code,a.account_name FROM opening_balances ob LEFT JOIN accounts a ON a.id=ob.account_id ORDER BY ob.id DESC LIMIT 10''')
    years = range(datetime.now().year-3, datetime.now().year+2)
    body = render_template_string('''
    <div class="shu-adv-page">
      <section class="command-hero"><div class="command-copy"><div class="command-kicker">ADVANCED SHU CONTROL</div><h2>SHU Tahunan & Saldo Awal</h2><p>Atur periode Januari-Desember atau custom, tentukan laba yang dibagi, bobot pembagian, adjust per anggota, dan input saldo awal keuangan.</p></div></section>
      <div class="grid">
        <div class="col-8"><div class="card"><div class="kartu"><h2>Setting Periode SHU {{year}}</h2><form method="GET" style="width:130px"><select name="year" onchange="this.form.submit()">{% for y in years %}<option value="{{y}}" {% if y==year %}selected{% endif %}>{{y}}</option>{% endfor %}</select></form></div>
          <form method="POST" class="shu-config-grid"><input type="hidden" name="action" value="save_period"><input type="hidden" name="year" value="{{year}}">
            <div class="form-group"><label>Mulai Periode</label><input type="date" name="start_date" value="{{period.start_date}}"></div>
            <div class="form-group"><label>Akhir Periode</label><input type="date" name="end_date" value="{{period.end_date}}"></div>
            <div class="form-group"><label>Laba yang Mau Dibagi</label><input type="number" step="0.01" name="distributable_profit" value="{{period.distributable_profit or 0}}"></div>
            <div class="form-group"><label>Cadangan %</label><input type="number" step="0.01" name="reserve_percent" value="{{period.reserve_percent or 40}}"></div>
            <div class="form-group"><label>Bobot Simpanan</label><input type="number" step="0.01" name="savings_weight" value="{{period.savings_weight or 50}}"></div>
            <div class="form-group"><label>Bobot Belanja</label><input type="number" step="0.01" name="shopping_weight" value="{{period.shopping_weight or 30}}"></div>
            <div class="form-group"><label>Bobot Angsuran</label><input type="number" step="0.01" name="loan_weight" value="{{period.loan_weight or 20}}"></div>
            <div class="form-group"><label>Status</label><select name="status"><option value="DRAFT" {% if period.status=='DRAFT' %}selected{% endif %}>DRAFT</option><option value="LOCKED" {% if period.status=='LOCKED' %}selected{% endif %}>LOCKED</option></select></div>
            <div class="form-group wide"><label>Catatan</label><textarea name="note">{{period.note or ''}}</textarea></div><button class="btn-success">Simpan Setting SHU</button>
          </form></div></div>
        <div class="col-4"><div class="card"><h2>Saldo Awal Keuangan</h2><form method="POST"><input type="hidden" name="action" value="opening_balance"><input type="hidden" name="year" value="{{year}}"><div class="form-group"><label>Tanggal</label><input type="date" name="balance_date" value="{{period.start_date}}"></div><div class="form-group"><label>Akun</label><select name="account_id">{% for a in accounts %}<option value="{{a.id}}">{{a.account_code}} - {{a.account_name}}</option>{% endfor %}</select></div><div class="form-group"><label>Posisi</label><select name="direction"><option value="DEBIT">Debit</option><option value="CREDIT">Kredit</option></select></div><div class="form-group"><label>Nominal</label><input type="number" step="0.01" name="amount"></div><div class="form-group"><label>Catatan</label><input name="ob_note" value="Saldo awal penggunaan sistem"></div><button class="btn-warn">Catat Saldo Awal</button></form></div></div>
      </div>
      <div class="metrics"><div class="metric"><div class="label">Pendapatan Periode</div><div class="value">{{rupiah(revenue)}}</div></div><div class="metric"><div class="label">Beban Periode</div><div class="value">{{rupiah(expense)}}</div></div><div class="metric"><div class="label">Laba Bersih</div><div class="value">{{rupiah(net_profit)}}</div></div><div class="metric"><div class="label">SHU Dibagi</div><div class="value">{{rupiah(period.distributable_profit or 0)}}</div></div><div class="metric"><div class="label">Total Alokasi Member</div><div class="value">{{rupiah(total_shu)}}</div></div></div>
      <div class="card"><div class="kartu"><h2>Simulasi dan Adjust Member</h2><a class="btn btn-warn" data-confirm="Distribusikan SHU {{year}} sekarang?" href="{{url_for('distribute_shu', year=year)}}">Distribusikan SHU</a></div><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Nama</th><th>Simpanan</th><th>Belanja</th><th>Angsuran</th><th>SHU Simpanan</th><th>SHU Belanja</th><th>SHU Angsuran</th><th>Manual</th><th>Total</th><th>Adjust</th></tr></thead><tbody>{% for r in rows %}<tr><td>{{r.member.member_code}}</td><td>{{r.member.name}}</td><td>{{rupiah(r.d.savings)}}</td><td>{{rupiah(r.d.shopping)}}</td><td>{{rupiah(r.d.loan_pay)}}</td><td>{{rupiah(r.d.shu_savings)}}</td><td>{{rupiah(r.d.shu_shopping)}}</td><td>{{rupiah(r.d.shu_loan)}}</td><td>{{rupiah(r.d.manual)}}</td><td><b>{{rupiah(r.d.total)}}</b></td><td><form method="POST" class="shu-mini-form"><input type="hidden" name="action" value="member_adjust"><input type="hidden" name="year" value="{{year}}"><input type="hidden" name="member_id" value="{{r.member.id}}"><input name="manual_amount" type="number" step="0.01" value="{{r.d.manual}}"><input name="adjust_note" placeholder="note" value="{{r.d.adjust_note}}"><button class="btn-sm">OK</button></form></td></tr>{% else %}<tr><td colspan="11" class="muted text-center">Belum ada member.</td></tr>{% endfor %}</tbody></table></div></div>
      <div class="card"><h2>Riwayat Saldo Awal Terakhir</h2><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Akun</th><th>Posisi</th><th>Nominal</th><th>Ref</th><th>Note</th></tr></thead><tbody>{% for o in opening %}<tr><td>{{o.balance_date}}</td><td>{{o.account_code}} - {{o.account_name}}</td><td>{{o.direction}}</td><td>{{rupiah(o.amount)}}</td><td>{{o.journal_ref}}</td><td>{{o.note}}</td></tr>{% else %}<tr><td colspan="6" class="muted text-center">Belum ada saldo awal.</td></tr>{% endfor %}</tbody></table></div></div>
    </div>
    ''', year=year, years=years, period=period, rows=rows, accounts=accounts, opening=opening, revenue=revenue, expense=expense, net_profit=net_profit, total_shu=total_shu, rupiah=rupiah)
    return render_page('Laporan SHU', body)

@app.route('/shu/distribute/<int:year>', methods=['GET'])
@login_required
@role_required('admin')
def distribute_shu(year):
    period = ensure_shu_period(year)
    if period['status'] == 'DISTRIBUTED':
        flash(f'SHU tahun {year} sudah pernah didistribusikan.', 'warning')
        return redirect(url_for('shu_report', year=year))
    members = q_all('SELECT * FROM members ORDER BY member_code')
    total = 0
    for m in members:
        d = calculate_shu_detail(m['id'], year)
        shu = d['total']
        if shu > 0:
            exec_sql('''INSERT OR REPLACE INTO shu_distribution_details(year,member_id,savings_point,shopping_point,loan_point,shu_savings,shu_shopping,shu_loan,manual_amount,total_shu,distributed_at)
                        VALUES(?,?,?,?,?,?,?,?,?,?,?)''', [year,m['id'],d['savings'],d['shopping'],d['loan_pay'],d['shu_savings'],d['shu_shopping'],d['shu_loan'],d['manual'],shu,now_str()])
            exec_sql('UPDATE members SET shu_balance = COALESCE(shu_balance, 0) + ? WHERE id = ?', [shu, m['id']])
            total += shu
    if total > 0:
        post_journal(f"{year}-12-31", f'Distribusi SHU Tahun {year}', [
            {'account_id': get_account_id('2101'), 'debit': total, 'credit': 0},
            {'account_id': get_account_id('2001'), 'debit': 0, 'credit': total}
        ], 'shu_distribution', year, session.get('user_id'))
        exec_sql('UPDATE shu_periods SET status="DISTRIBUTED", distributed_by=?, distributed_at=? WHERE year=?', [session.get('user_id'),now_str(),year])
        log_action('SHU_DISTRIBUTED', 'members', year, f'SHU {year} Rp {total}')
        flash(f'SHU tahun {year} didistribusikan: {rupiah(total)}', 'success')
    else:
        flash('Tidak ada SHU yang dapat didistribusikan.', 'warning')
    return redirect(url_for('shu_report', year=year))

