# Member Card PDF
# =========================
@app.route('/member/card-pdf')
@login_required
def member_card_pdf():
    user = current_user()
    member_id = request.args.get('member_id', '')
    if user['role'] == 'admin' and member_id:
        member = q_one('SELECT * FROM members WHERE id=?', [member_id])
    else:
        member = q_one('SELECT * FROM members WHERE member_code = ?', [f'EMP-{user["employee_number"]}'])
    if not member:
        flash('Member tidak ditemukan.', 'error')
        return redirect(url_for('dashboard'))

    from reportlab.lib import colors
    from reportlab.graphics.barcode import qr
    from reportlab.graphics import renderPDF
    from reportlab.graphics.shapes import Drawing

    # CR80 card size: 85.6mm x 54mm, standar kartu ID/ATM.
    card_w, card_h = 85.6 * mm, 54 * mm
    buf = BytesIO()
    c = canvas.Canvas(buf, pagesize=(card_w, card_h))

    # Background card
    c.setFillColor(colors.HexColor('#17263a'))
    c.roundRect(0, 0, card_w, card_h, 4.5*mm, fill=1, stroke=0)
    c.setFillColor(colors.HexColor('#23364f'))
    c.circle(card_w-12*mm, card_h+3*mm, 23*mm, fill=1, stroke=0)
    c.setFillColor(colors.HexColor('#2e4565'))
    c.circle(5*mm, -4*mm, 18*mm, fill=1, stroke=0)

    # Text identity
    c.setFillColor(colors.HexColor('#9fb5cf'))
    c.setFont('Helvetica-Bold', 5.8)
    c.drawString(7*mm, card_h-10*mm, 'KOPERASI ENTERPRISE')
    c.setFillColor(colors.white)
    c.setFont('Helvetica-Bold', 12)
    c.drawString(7*mm, card_h-17*mm, str(member['name'])[:24].upper())
    c.setFillColor(colors.HexColor('#a8c4e6'))
    c.setFont('Helvetica', 7)
    c.drawString(7*mm, card_h-23*mm, str(member['member_code']))

    # QR box
    qr_size = 22 * mm
    qx, qy = card_w - qr_size - 7*mm, card_h - qr_size - 9*mm
    c.setFillColor(colors.white)
    c.roundRect(qx-1.8*mm, qy-1.8*mm, qr_size+3.6*mm, qr_size+3.6*mm, 2*mm, fill=1, stroke=0)
    qr_code = qr.QrCodeWidget(f"KOPERASI:{member['member_code']}:{member['name']}")
    bounds = qr_code.getBounds()
    wq, hq = bounds[2] - bounds[0], bounds[3] - bounds[1]
    d = Drawing(qr_size, qr_size, transform=[qr_size/wq, 0, 0, qr_size/hq, 0, 0])
    d.add(qr_code)
    renderPDF.draw(d, c, qx, qy)

    # Info chips
    c.setFillColor(colors.Color(1,1,1,alpha=.09))
    c.roundRect(7*mm, 8*mm, 21*mm, 11*mm, 2.4*mm, fill=1, stroke=0)
    c.roundRect(31*mm, 8*mm, 21*mm, 11*mm, 2.4*mm, fill=1, stroke=0)
    c.roundRect(55*mm, 8*mm, 23*mm, 11*mm, 2.4*mm, fill=1, stroke=0)
    c.setFillColor(colors.HexColor('#a8b3c2'))
    c.setFont('Helvetica', 4.8)
    c.drawCentredString(17.5*mm, 15.2*mm, 'STATUS')
    c.drawCentredString(41.5*mm, 15.2*mm, 'BERGABUNG')
    c.drawCentredString(66.5*mm, 15.2*mm, 'KODE')
    c.setFillColor(colors.HexColor('#34d399'))
    c.setFont('Helvetica-Bold', 6.4)
    c.drawCentredString(17.5*mm, 10.8*mm, str(member['status'])[:12])
    c.setFillColor(colors.HexColor('#60a5fa'))
    c.drawCentredString(41.5*mm, 10.8*mm, str(member['join_date'] or '-')[:10])
    c.setFillColor(colors.white)
    c.drawCentredString(66.5*mm, 10.8*mm, str(member['member_code'])[:14])

    c.setFillColor(colors.HexColor('#8aa0bc'))
    c.setFont('Helvetica', 4.4)
    c.drawString(7*mm, 4.5*mm, f'Printed {now_str()[:16]}')
    c.showPage()
    c.save()
    buf.seek(0)
    return send_file(buf, as_attachment=True, download_name=f'kartu_{member["member_code"]}.pdf', mimetype='application/pdf')

@app.route('/member/digital-card')
@login_required
def member_digital_card():
    user = current_user()
    member_id = request.args.get('member_id', '')
    if user['role'] == 'admin' and member_id:
        member = q_one('SELECT * FROM members WHERE id=?', [member_id])
    else:
        member = q_one('SELECT * FROM members WHERE member_code = ?', [f'EMP-{user["employee_number"]}'])
    if not member:
        flash('Member tidak ditemukan.', 'error')
        return redirect(url_for('dashboard'))
    saldo_wallet = q_one('SELECT COALESCE(SUM(CASE WHEN tipe="MASUK" THEN nominal ELSE -nominal END), 0) as saldo FROM saldo_history WHERE member_id = ?', [member['id']])['saldo']
    total_belanja = q_one('SELECT COALESCE(SUM(total), 0) as x FROM sales WHERE member_id = ? AND status="Posted"', [member['id']])['x']
