@app.route('/wallet/scan-qr',methods=['GET','POST'])
@login_required
@role_required('user')
def wallet_qr_scanner():
    member=current_wallet_member()
    if not member:
        flash('Akun anggota belum terhubung dengan wallet.','error'); return redirect(url_for('dashboard'))
    if request.method=='POST':
        photo=request.files.get('qr_photo')
        if not photo or not photo.filename:
            flash('Ambil atau pilih foto QR terlebih dahulu.','error'); return redirect(url_for('wallet_qr_scanner'))
        if cv2 is None or np is None:
            flash('Decoder QR server belum tersedia. Gunakan Kamera iPhone langsung.','error'); return redirect(url_for('wallet_qr_scanner'))
        raw=photo.read(8*1024*1024)
        try:
            image=cv2.imdecode(np.frombuffer(raw,dtype=np.uint8),cv2.IMREAD_COLOR)
            value,points,_=cv2.QRCodeDetector().detectAndDecode(image)
        except Exception:
            value=''
        if value:
            try:
                from urllib.parse import urlparse
                parsed=urlparse(value); target=parsed.path + (('?' + parsed.query) if parsed.query else '')
            except Exception: target=''
            if target.startswith('/pay/branch/') or target.startswith('/pay/intent/'):
                return redirect(target)
        flash('QR tidak terbaca atau bukan QR pembayaran koperasi. Foto ulang lebih dekat dan terang.','error')
        return redirect(url_for('wallet_qr_scanner'))
    body=render_template_string(r'''<div class="wallet-scanner"><header class="scanner-hero"><div class="scanner-grid"></div><span>KOPERASI WALLET CAMERA</span><h2>Scan untuk Bayar</h2><p>Arahkan kamera ke QR statis cabang. Nominal aktif dari kasir akan muncul otomatis setelah QR terbaca.</p></header><section class="scanner-stage"><video id="qrCamera" playsinline muted></video><div class="scanner-overlay"><i></i><i></i><i></i><i></i><span></span></div><div class="scanner-beam"></div><div id="scannerStatus" class="scanner-status"><i></i><span>Menyiapkan kamera...</span></div></section><section class="scanner-tools"><form method="post" enctype="multipart/form-data" class="ios-qr-capture"><label for="iosQrPhoto"><i>⌗</i><b>Scan dengan Kamera iPhone</b><small>Ambil foto QR lalu diproses otomatis</small></label><input id="iosQrPhoto" type="file" name="qr_photo" accept="image/*" capture="environment" required><button type="submit" class="btn-success ios-process-btn">Proses Foto QR</button><div class="ios-file-name" id="iosFileName">Belum ada foto dipilih</div></form><button type="button" id="startScan" class="btn-success">Kamera Live</button><button type="button" id="switchCamera" class="btn-ghost">Ganti Kamera</button><label class="scanner-manual">Atau tempel tautan QR<input id="manualQrUrl" type="url" placeholder="http://server:5000/pay/branch/..."><button type="button" id="openManual">Buka Pembayaran</button></label><p>Kamera browser membutuhkan HTTPS, kecuali saat memakai localhost. Jika kamera ditolak, izinkan akses kamera pada pengaturan browser.</p></section></div><script>(function(){var video=document.getElementById('qrCamera'),status=document.getElementById('scannerStatus'),stream=null,facing='environment',running=false,detector=null;function setStatus(t,ok){status.querySelector('span').textContent=t;status.classList.toggle('ok',!!ok)}function valid(url){try{var u=new URL(url,location.origin);return u.origin===location.origin&&u.pathname.indexOf('/pay/branch/')===0}catch(e){return false}}function go(url){if(!valid(url)){setStatus('QR bukan QR pembayaran koperasi',false);return}setStatus('QR terbaca. Membuka pembayaran...',true);stop();location.href=new URL(url,location.origin).href}async function scanLoop(){if(!running||!detector)return;try{var codes=await detector.detect(video);if(codes&&codes.length){go(codes[0].rawValue);return}}catch(e){}requestAnimationFrame(scanLoop)}async function start(){stop();setStatus('Meminta izin kamera...',false);try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:facing}},audio:false});video.srcObject=stream;await video.play();running=true;if('BarcodeDetector' in window){detector=new BarcodeDetector({formats:['qr_code']});setStatus('Kamera aktif. Arahkan ke QR cabang.',true);scanLoop()}else{setStatus('Browser belum mendukung pembaca QR otomatis. Gunakan Chrome terbaru atau tempel tautan QR.',false)}}catch(e){setStatus('Kamera tidak dapat dibuka: '+(e.message||e.name),false)}}function stop(){running=false;if(stream){stream.getTracks().forEach(function(t){t.stop()});stream=null}}document.getElementById('startScan').onclick=start;document.getElementById('switchCamera').onclick=function(){facing=facing==='environment'?'user':'environment';start()};document.getElementById('openManual').onclick=function(){go(document.getElementById('manualQrUrl').value)};var fp=document.getElementById('iosQrPhoto');if(fp){fp.addEventListener('change',function(){document.getElementById('iosFileName').textContent=this.files&&this.files[0]?this.files[0].name:'Belum ada foto dipilih'})}window.addEventListener('pagehide',stop);if(!('BarcodeDetector' in window)){setStatus('Safari iPhone: gunakan tombol Scan dengan Kamera iPhone di bawah.',false)}else if(navigator.mediaDevices&&navigator.mediaDevices.getUserMedia){start()}else setStatus('Perangkat tidak mendukung akses kamera browser.',false)})();</script>''')
    return render_page('Scan QR Pembayaran',body)


@app.route('/cashier/qr-dynamic',methods=['GET','POST'])
@login_required
@role_required('admin','kasir','branch_admin','branch_cashier')
def cashier_qr_dynamic():
    ensure_branch_qr_payment_schema(); bid=get_branch_id()
    if not bid:
        flash('Terminal belum mempunyai cabang aktif.','error'); return redirect(url_for('dashboard'))
    intent=None
    if request.method=='POST':
        amount=parse_float(request.form.get('amount'),0); note=(request.form.get('note') or '').strip()[:200]
        if amount<1000:
            flash('Nominal minimal Rp1.000.','error')
        else:
            code='QRD-'+datetime.now().strftime('%Y%m%d%H%M%S')+'-'+os.urandom(3).hex().upper()
            expires=(datetime.now()+timedelta(minutes=15)).strftime('%Y-%m-%d %H:%M:%S')
            iid=exec_sql('''INSERT INTO branch_qr_payment_intents(payment_code,branch_id,amount,status,note,operator_user_id,cashier_session_id,created_at,expires_at,qr_mode) VALUES(?,?,?,'WAITING',?,?,?,?,?,'DYNAMIC')''',[code,bid,amount,note,cashier_operator_id(),cashier_operator_session_id(),now_str(),expires])
            qr_payment_event(iid,bid,'DYNAMIC_CREATED',f'Nominal {amount}')
            return redirect(url_for('cashier_qr_dynamic',intent=iid))
    iid=request.args.get('intent',type=int)
    if iid: intent=q_one("SELECT * FROM branch_qr_payment_intents WHERE id=? AND branch_id=? AND qr_mode='DYNAMIC'",[iid,bid])
    recent=q_all("SELECT * FROM branch_qr_payment_intents WHERE branch_id=? AND qr_mode='DYNAMIC' ORDER BY id DESC LIMIT 10",[bid])
    body=render_template_string(r'''<div class="branch-qr-suite"><header class="branch-qr-hero dynamic"><div class="branch-qr-lines"></div><div><span>ONE-TIME AMOUNT QR</span><h2>Generate QR Nominal</h2><p>Buat QR khusus untuk satu nominal. QR ini berbeda tiap transaksi dan tidak terpengaruh tagihan QR statis cabang.</p></div><div class="branch-qr-live"><i></i> SECURE INTENT</div></header><section class="dynamic-qr-layout"><article class="branch-qr-terminal"><div class="branch-qr-title"><div><span>MANUAL AMOUNT</span><h3>Buat Tagihan Baru</h3></div></div><form method="post" class="qr-amount-form"><label>Nominal pembayaran<input type="number" name="amount" min="1000" step="1000" placeholder="Rp 20.000" required autofocus></label><label>Catatan transaksi<input name="note" maxlength="200" placeholder="Contoh: Belanja koperasi"></label><button class="btn-success">Generate QR Sekarang</button></form></article>{% if intent %}<article class="dynamic-qr-result" id="dynamicQR" data-id="{{intent.id}}"><div class="branch-qr-title"><div><span>QR TRANSAKSI</span><h3>{{intent.payment_code}}</h3></div><span class="badge badge-warn" id="dynamicStatus">{{intent.status}}</span></div><img src="{{url_for('dynamic_qr_image',payment_code=intent.payment_code)}}"><b>{{rupiah(intent.amount)}}</b><small>Berlaku sampai {{intent.expires_at}}</small><div id="dynamicPaidResult"></div></article>{% endif %}</section><section class="branch-qr-history"><header><div><span>GENERATED HISTORY</span><h3>QR Nominal Terbaru</h3></div></header><div>{% for r in recent %}<article><i class="{{r.status|lower}}"></i><div><b>{{r.payment_code}}</b><small>{{r.created_at}} · {{r.note or '-'}}</small></div><strong>{{rupiah(r.amount)}}</strong><span class="badge {{'badge-success' if r.status=='PAID' else 'badge-warn' if r.status=='WAITING' else 'badge-gray'}}">{{r.status}}</span></article>{% endfor %}</div></section></div>{% if intent %}<script>(function(){var id={{intent.id}};function poll(){fetch('{{url_for("api_dynamic_qr_status",intent_id=intent.id)}}',{cache:'no-store'}).then(function(r){return r.json()}).then(function(d){if(!d.ok)return;document.getElementById('dynamicStatus').textContent=d.status;if(d.status==='PAID'){document.getElementById('dynamicPaidResult').innerHTML='<div class="qr-paid-pop"><i>✓</i><b>Pembayaran Berhasil</b><strong>'+d.member_name+'</strong></div>';}})}poll();setInterval(poll,750)})();</script>{% endif %}''',intent=intent,recent=recent,rupiah=rupiah)
    return render_page('Generate QR Nominal',cashier_operator_banner()+body)

