@app.route('/quick-cashier', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'kasir', 'branch_admin', 'branch_cashier')
def quick_cashier():
    if request.method == 'POST':
        total = parse_float(request.form.get('total', 0) or 0)
        paid = parse_float(request.form.get('paid', 0) or 0)
        payment_method = request.form.get('payment_method', 'tunai')
        member_id = request.form.get('member_id') or None
        customer_name = request.form.get('customer_name', '').strip()
        note = request.form.get('note', '').strip()
        invoice = gen_code('INV')
        if total <= 0:
            flash('Total belanja harus lebih dari 0.', 'error')
            return redirect(url_for('quick_cashier'))
        change_amount = 0
        if payment_method == 'tunai':
            if paid < total:
                flash(f'Nominal bayar kurang. Total {rupiah(total)}', 'error')
                return redirect(url_for('quick_cashier'))
            change_amount = paid - total
        elif payment_method == 'wallet':
            if not member_id:
                flash('Bayar wallet wajib pilih member.', 'error')
                return redirect(url_for('quick_cashier'))
            member_saldo = q_one('SELECT COALESCE(SUM(CASE WHEN tipe="MASUK" THEN nominal ELSE -nominal END), 0) as saldo FROM saldo_history WHERE member_id=?', [member_id])['saldo']
            if member_saldo < total:
                flash(f'Saldo wallet tidak cukup. Saldo: {rupiah(member_saldo)}', 'error')
                return redirect(url_for('quick_cashier'))
            saldo_sebelum = member_saldo
            saldo_setelah = saldo_sebelum - total
            exec_sql('INSERT INTO saldo_history(member_id, tipe, nominal, saldo_sebelum, saldo_setelah, keterangan, reference_id, created_by) VALUES (?, "KELUAR", ?, ?, ?, "Pembayaran quick cashier", ?, ?)',
                [member_id, total, saldo_sebelum, saldo_setelah, 0, session.get('user_id')])
            paid = total
        else:
            paid = total
        # Simpan ke antrian verifikasi (PENDING) — stok belum dikurangi
        cashier_branch_id = get_branch_id()
        qid = exec_sql('INSERT INTO quick_cashier_queue(invoice_no,trx_date,total,payment_method,member_id,customer_name,note,status,created_by,stock_branch_id,cashier_session_id) VALUES(?,?,?,?,?,?,?,"PENDING",?,?,?)',
            [invoice,today_str(),total,payment_method,member_id,customer_name,note,cashier_operator_id(),cashier_branch_id,cashier_operator_session_id()])
        log_action('QUICK_CASHIER_PENDING', 'quick_cashier_queue', qid, f'Total {total} metode {payment_method} — menunggu verifikasi')
        flash(f'✅ Transaksi antri verifikasi! Invoice: {invoice} — {rupiah(total)}. Status: PENDING. Admin akan verifikasi untuk kurangi stok.', 'success')
        return redirect(url_for('quick_cashier'))
    members_rows = q_all("SELECT id, member_code, name FROM members WHERE status='Aktif' ORDER BY name ASC")
    cashier_branch_name = get_branch_name(get_branch_id())
    body = render_template_string('''
    <div class="sales-suite quick-suite">
      <header class="sales-hero"><div><span>POINT OF SALE</span><h2>Kasir Cepat</h2><p>Catat pembayaran untuk lokasi <b>{{cashier_branch_name}}</b>. Transaksi terkunci ke persediaan lokasi kasir sebelum stok diverifikasi.</p></div><div class="sales-hero-chip"><small>Mode transaksi</small><b>Input nominal cepat</b></div></header>
      <div class="grid sales-main-grid">
        <div class="col-6">
            <div class="card" style="text-align:center;">
                <h2>⚡ Quick Cashier</h2>
                <div class="muted small">Input total belanja langsung — tanpa scan barang 1 per 1. Stok dikurangi nanti.</div>
                <hr>
                <form method="post" id="quickForm">
                    <div class="form-group" style="text-align:left;">
                        <label>Member (opsional)</label>
                        <select name="member_id">
                            <option value="">🏷️ Umum</option>
                            {% for m in members_rows %}
                            <option value="{{ m['id'] }}">{{ m['member_code'] }} — {{ m['name'] }}</option>
                            {% endfor %}
                        </select>
                    </div>
                    <div class="form-group" style="text-align:left;">
                        <label>Nama Pelanggan (opsional)</label>
                        <input name="customer_name" placeholder="Nama pelanggan">
                    </div>
                    <div style="display:flex;gap:16px;align-items:center;justify-content:center;margin:24px 0;">
                        <div style="font-size:14px;color:var(--text-muted);">Total Belanja</div>
                        <div style="font-size:48px;font-weight:800;color:#059669;" id="totalDisplay">Rp 0</div>
                    </div>
                    <input type="hidden" name="total" id="totalInput" value="0">
                    <div class="keypad" style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;max-width:320px;margin:0 auto;">
                        <button type="button" class="btn btn-ghost" onclick="press('1')" style="font-size:24px;padding:16px;">1</button>
                        <button type="button" class="btn btn-ghost" onclick="press('2')" style="font-size:24px;padding:16px;">2</button>
                        <button type="button" class="btn btn-ghost" onclick="press('3')" style="font-size:24px;padding:16px;">3</button>
                        <button type="button" class="btn btn-ghost" onclick="press('4')" style="font-size:24px;padding:16px;">4</button>
                        <button type="button" class="btn btn-ghost" onclick="press('5')" style="font-size:24px;padding:16px;">5</button>
                        <button type="button" class="btn btn-ghost" onclick="press('6')" style="font-size:24px;padding:16px;">6</button>
                        <button type="button" class="btn btn-ghost" onclick="press('7')" style="font-size:24px;padding:16px;">7</button>
                        <button type="button" class="btn btn-ghost" onclick="press('8')" style="font-size:24px;padding:16px;">8</button>
                        <button type="button" class="btn btn-ghost" onclick="press('9')" style="font-size:24px;padding:16px;">9</button>
                        <button type="button" class="btn btn-ghost" onclick="press('00')" style="font-size:24px;padding:16px;">00</button>
                        <button type="button" class="btn btn-ghost" onclick="press('0')" style="font-size:24px;padding:16px;">0</button>
                        <button type="button" class="btn btn-ghost" onclick="pressDel()" style="font-size:24px;padding:16px;">⌫</button>
                    </div>
                    <hr>
                    <div class="form-group" style="text-align:left;">
                        <label>Pilih Metode Pembayaran</label>
                        <div style="display:flex;gap:12px;flex-wrap:wrap;">
                            <label class="btn btn-ghost" style="flex:1;cursor:pointer;padding:12px;">
                                <input type="radio" name="payment_method" value="tunai" checked onchange="toggleMethod()"> 💰 Tunai
                            </label>
                            <label class="btn btn-ghost" style="flex:1;cursor:pointer;padding:12px;">
                                <input type="radio" name="payment_method" value="wallet" onchange="toggleMethod()"> 💳 Wallet
                            </label>
                        </div>
                    </div>
                    <div class="form-group" id="paidSection" style="text-align:left;">
                        <label>💰 Uang Dibayar</label>
                        <div class="login-input-wrap">
                            <span class="login-input-icon">💵</span>
                            <input type="number" id="paidInput" name="paid" min="0" placeholder="Jumlah uang" style="font-size:20px;font-weight:700;padding:14px 14px 14px 42px;">
                        </div>
                        <div style="margin-top:8px;display:flex;gap:8px;flex-wrap:wrap;">
                            <button type="button" class="btn btn-sm btn-ghost" onclick="setPaid(parseInt(document.getElementById('totalInput').value)||0)">Uang Pas</button>
                            <button type="button" class="btn btn-sm btn-ghost" onclick="setPaid(Math.ceil((parseInt(document.getElementById('totalInput').value)||0)/1000)*1000+5000)">+5rb</button>
                            <button type="button" class="btn btn-sm btn-ghost" onclick="setPaid(Math.ceil((parseInt(document.getElementById('totalInput').value)||0)/10000)*10000)">+10rb</button>
                            <button type="button" class="btn btn-sm btn-ghost" onclick="setPaid(Math.ceil((parseInt(document.getElementById('totalInput').value)||0)/50000)*50000)">+50rb</button>
                            <div style="margin-top:8px;display:flex;gap:8px;flex-wrap:wrap;border-top:1px solid var(--border);padding-top:8px;">
                                <span class="small muted">Simpanan nominal:</span>
                                <button type="button" class="btn btn-sm btn-ghost" onclick="setPaid(50000)">50rb</button>
                                <button type="button" class="btn btn-sm btn-ghost" onclick="setPaid(100000)">100rb</button>
                                <button type="button" class="btn btn-sm btn-ghost" onclick="setPaid(200000)">200rb</button>
                                <button type="button" class="btn btn-sm btn-ghost" onclick="saveCustom()">💾 Simpan nominal</button>
                                <input type="number" id="customSaveAmount" placeholder="Nominal" style="width:100px;font-size:12px;padding:6px 10px;">
                                <button type="button" class="btn btn-sm btn-ghost" id="savedBtn" style="display:none;" onclick="setPaid(parseInt(this.dataset.val)||0)">💾 <span id="savedLabel"></span></button>
                            </div>
                        </div>
                    </div>
                    <div class="form-group" style="text-align:left;">
                        <label>Catatan</label>
                        <textarea name="note" style="min-height:40px;" placeholder="Catatan (opsional)"></textarea>
                    </div>
                    <button type="submit" class="btn-success" style="font-size:18px;padding:16px;">💾 Simpan Transaksi</button>
                </form>
            </div>
        </div>
        <div class="col-6">
            <div class="card" id="paymentInfo">
                <h2>💰 Ringkasan</h2>
                <div style="padding:20px;text-align:center;">
                    <div class="muted small">Total Belanja</div>
                    <div style="font-size:42px;font-weight:800;color:#059669;" id="ringkasanTotal">Rp 0</div>
                    <hr>
                    <div class="muted small">Uang Dibayar</div>
                    <div style="font-size:32px;font-weight:700;color:#2563eb;" id="ringkasanBayar">Rp 0</div>
                    <hr>
                    <div class="muted small">Kembalian</div>
                    <div style="font-size:36px;font-weight:800;" id="ringkasanKembali">Rp 0</div>
                </div>
            </div>
            <div class="card">
                <h2>📌 Panduan</h2>
                <ol style="font-size:13px;line-height:2;">
                    <li><strong>Input total</strong> belanja menggunakan keypad</li>
                    <li>Pilih <strong>metode bayar</strong> (Tunai / Wallet)</li>
                    <li>Masukkan <strong>uang dibayar</strong> (atau tekan "Uang Pas")</li>
                    <li>Klik <strong>Simpan Transaksi</strong></li>
                    <li>Setelah antrian selesai, lakukan <strong>Adjustment Stok</strong> untuk mengurangi barang</li>
                </ol>
            </div>
        </div>
      </div>
    </div>
    <script>
    function press(n){ var inp=document.getElementById('totalInput'); var v=inp.value.replace(/[^0-9]/g,''); v=v+n; inp.value=v.replace(/^0+/,'')||'0'; updateDisplay(); }
    function pressDel(){ var inp=document.getElementById('totalInput'); var v=inp.value.replace(/[^0-9]/g,''); v=v.slice(0,-1)||'0'; inp.value=v; updateDisplay(); }
    function updateDisplay(){
        var v=parseInt(document.getElementById('totalInput').value)||0;
        document.getElementById('totalDisplay').textContent='Rp '+v.toLocaleString('id-ID');
        document.getElementById('ringkasanTotal').textContent='Rp '+v.toLocaleString('id-ID');
        hitungKembalian();
    }
    function setPaid(v){ document.getElementById('paidInput').value=v; hitungKembalian(); }
    function hitungKembalian(){
        var total=parseInt(document.getElementById('totalInput').value)||0;
        var paid=parseFloat(document.getElementById('paidInput').value)||0;
        if(paid>0){document.getElementById('ringkasanBayar').textContent='Rp '+paid.toLocaleString('id-ID');}
        var kembali=paid-total; if(kembali<0)kembali=0;
        document.getElementById('ringkasanKembali').textContent='Rp '+kembali.toLocaleString('id-ID');
        document.getElementById('ringkasanKembali').style.color=kembali>=0?'#059669':'#ef4444';
    }
    function toggleMethod(){
        var pw=document.querySelector('input[name="payment_method"]:checked').value;
        document.getElementById('paidSection').style.display=pw==='wallet'?'none':'block';
        if(pw==='wallet'){document.getElementById('paidInput').value=document.getElementById('totalInput').value;hitungKembalian();}
    }
    document.getElementById('paidInput').addEventListener('input',hitungKembalian);
    </script>
    ''', members_rows=members_rows, total=0, rupiah=rupiah, cashier_branch_name=cashier_branch_name)
    return render_page('Kasir Cepat', cashier_operator_banner()+body)

# =========================
# Quick Cashier Queue — Verifikasi Admin untuk Kurangi Stok
# =========================
CSS_DESIGN += r"""
.qcq-shell{display:grid;gap:14px}.qcq-hero{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;padding:26px 28px;border-radius:14px;background:linear-gradient(125deg,#101828,#213b59);color:#fff;box-shadow:0 12px 30px rgba(16,24,40,.14)}.qcq-hero span{color:#f4a184;font-size:9px;font-weight:900;letter-spacing:.16em}.qcq-hero h2{margin:5px 0;color:#fff;font-size:26px}.qcq-hero p{color:#c5cfdb;font-size:11px}.qcq-hero .btn{background:#fff!important;color:#1c2c40!important}.qcq-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.qcq-kpis>div{padding:16px 18px;border:1px solid #d0d5dd;border-top:3px solid #2457d6;border-radius:10px;background:#fff}.qcq-kpis>div:nth-child(1){border-top-color:#e35d34}.qcq-kpis>div:nth-child(3){border-top-color:#087e6a}.qcq-kpis>div:nth-child(4){border-top-color:#b42335}.qcq-kpis span,.qcq-kpis b{display:block}.qcq-kpis span{color:#667085;font-size:8px;font-weight:850;text-transform:uppercase}.qcq-kpis b{margin-top:7px;font-size:20px}.qcq-filters{display:grid;grid-template-columns:minmax(260px,1fr) 190px 150px auto;gap:8px;padding:12px;border:1px solid #d0d5dd;border-radius:10px;background:#fff}.qcq-shell .card{border-radius:11px!important}.qcq-shell .card h3{font-size:15px!important}.qcq-shell .table-wrap{border-radius:9px!important}.qcq-shell td strong{color:#101828}.qcq-pager{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:13px 2px 0}.qcq-pager>span{color:#667085;font-size:9px}.qcq-pager>div{display:flex;align-items:center;gap:5px}.qcq-page{display:grid;place-items:center;min-width:32px;height:32px;border:1px solid #d0d5dd;border-radius:7px;background:#fff;color:#344054;font-size:10px;font-weight:800}.qcq-page.active{border-color:#2457d6;background:#2457d6;color:#fff}.qcq-pager .disabled{pointer-events:none;opacity:.4}
@media(max-width:900px){.qcq-kpis{grid-template-columns:repeat(2,1fr)}.qcq-filters{grid-template-columns:1fr 1fr}.qcq-filters input{grid-column:1/-1}}
@media(max-width:768px){.qcq-shell{padding:0 12px}.qcq-hero{align-items:flex-start;flex-direction:column;padding:20px;border-radius:20px}.qcq-hero h2{font-size:22px}.qcq-kpis{padding:0!important}.qcq-filters{grid-template-columns:1fr}.qcq-filters input{grid-column:auto}.qcq-shell .grid{gap:0!important}.qcq-shell .card{margin-left:0!important;margin-right:0!important}.qcq-pager{align-items:stretch;flex-direction:column}.qcq-pager>div{overflow-x:auto;padding-bottom:3px}}
"""

@app.route('/quick-cashier/queue', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'branch_admin')
def quick_cashier_queue():
    if request.method == 'POST':
        qid = int(request.form.get('qid'))
        action = request.form.get('action')
        queue = q_one('SELECT * FROM quick_cashier_queue WHERE id = ? AND status = "PENDING"', [qid])
        if queue and current_user()['role']=='branch_admin':
            current_bid=get_branch_id()
            if (queue['stock_branch_id'] or None)!=(current_bid or None): queue=None
        if not queue:
            flash('Antrian tidak ditemukan, berbeda cabang, atau sudah diproses.', 'error')
            return redirect(url_for('quick_cashier_queue'))
        
        if action == 'reject':
            # Jika bayar wallet, refund saldo
            if queue['payment_method'] == 'wallet' and queue['member_id']:
                member_saldo = q_one('SELECT COALESCE(SUM(CASE WHEN tipe="MASUK" THEN nominal ELSE -nominal END), 0) as saldo FROM saldo_history WHERE member_id=?', [queue['member_id']])['saldo']
                new_saldo = member_saldo + queue['total']
                exec_sql('INSERT INTO saldo_history(member_id, tipe, nominal, saldo_sebelum, saldo_setelah, keterangan, reference_id, created_by) VALUES (?, "MASUK", ?, ?, ?, "Refund quick cashier ditolak", ?, ?)',
                    [queue['member_id'], queue['total'], member_saldo, new_saldo, qid, session.get('user_id')])
                flash(f'💰 Saldo wallet dikembalikan Rp {queue["total"]}', 'success')
            
            exec_sql('UPDATE quick_cashier_queue SET status = "REJECTED", verified_by = ?, verified_at = ? WHERE id = ?',
                [session.get('user_id'), now_str(), qid])
            log_action('QUICK_CASHIER_REJECTED', 'quick_cashier_queue', qid, f'Ditolak: {queue["invoice_no"]}')
            flash(f'❌ Transaksi {queue["invoice_no"]} ditolak.', 'warning')
        
        return redirect(url_for('quick_cashier_queue'))
    
    # Pagination terpisah untuk tabel pending dan riwayat.
    queue_user=current_user(); queue_branch_id=get_branch_id()
    queue_scope=''; queue_scope_params=[]
    if queue_user['role']=='branch_admin':
        if queue_branch_id: queue_scope=' AND q.stock_branch_id=?'; queue_scope_params=[queue_branch_id]
        else: queue_scope=' AND q.stock_branch_id IS NULL'
    p_page = max(1, request.args.get('p_page', 1, type=int))
    h_page = max(1, request.args.get('h_page', 1, type=int))
    per_page = request.args.get('per_page', 10, type=int)
    per_page = per_page if per_page in (10, 20, 50) else 10
    keyword = (request.args.get('q') or '').strip()
    status_filter = (request.args.get('status') or '').strip().upper()
    pending_sql = 'SELECT q.*, u.full_name creator_name, m.member_code, m.name member_name FROM quick_cashier_queue q LEFT JOIN users u ON u.id=q.created_by LEFT JOIN members m ON m.id=q.member_id WHERE q.status="PENDING"'
    pending_params = list(queue_scope_params)
    pending_sql += queue_scope
    if keyword:
        pending_sql += ' AND (q.invoice_no LIKE ? OR COALESCE(m.name,"") LIKE ? OR COALESCE(u.full_name,"") LIKE ?)'
        pending_params += [f'%{keyword}%'] * 3
    pending_sql += ' ORDER BY q.id ASC'
    pending = paginate_query(pending_sql, pending_params, p_page, per_page)
    history_sql = 'SELECT q.*, u.full_name creator_name, vu.full_name verifier_name, m.name member_name FROM quick_cashier_queue q LEFT JOIN users u ON u.id=q.created_by LEFT JOIN users vu ON vu.id=q.verified_by LEFT JOIN members m ON m.id=q.member_id WHERE q.status<>"PENDING"'
    history_params = list(queue_scope_params)
    history_sql += queue_scope
    if keyword:
        history_sql += ' AND (q.invoice_no LIKE ? OR COALESCE(m.name,"") LIKE ? OR COALESCE(u.full_name,"") LIKE ? OR COALESCE(vu.full_name,"") LIKE ?)'
        history_params += [f'%{keyword}%'] * 4
    if status_filter in ('VERIFIED','REJECTED'):
        history_sql += ' AND q.status=?'; history_params.append(status_filter)
    history_sql += ' ORDER BY q.id DESC'
    verified = paginate_query(history_sql, history_params, h_page, per_page)
    if queue_user['role']=='branch_admin':
        if queue_branch_id:
            stats=q_one("""SELECT SUM(status='PENDING') pending_count,SUM(status='VERIFIED') verified_count,SUM(status='REJECTED') rejected_count,COALESCE(SUM(CASE WHEN status='PENDING' THEN total ELSE 0 END),0) pending_value FROM quick_cashier_queue WHERE stock_branch_id=?""",[queue_branch_id])
        else:
            stats=q_one("""SELECT SUM(status='PENDING') pending_count,SUM(status='VERIFIED') verified_count,SUM(status='REJECTED') rejected_count,COALESCE(SUM(CASE WHEN status='PENDING' THEN total ELSE 0 END),0) pending_value FROM quick_cashier_queue WHERE stock_branch_id IS NULL""")
    else:
        stats=q_one("""SELECT SUM(status='PENDING') pending_count,SUM(status='VERIFIED') verified_count,SUM(status='REJECTED') rejected_count,COALESCE(SUM(CASE WHEN status='PENDING' THEN total ELSE 0 END),0) pending_value FROM quick_cashier_queue""")
    
    body = render_template_string('''
    <div class="qcq-shell">
    <header class="qcq-hero"><div><span>QUICK CASHIER CONTROL</span><h2>Antrian Verifikasi</h2><p>Periksa transaksi, input barang, dan selesaikan pengurangan stok secara terkontrol.</p></div><a class="btn btn-ghost" href="{{url_for('quick_cashier')}}">Buka Quick Cashier</a></header>
    <div class="qcq-kpis"><div><span>Menunggu</span><b>{{stats.pending_count or 0}}</b></div><div><span>Nilai Antrian</span><b>{{rupiah(stats.pending_value)}}</b></div><div><span>Terverifikasi</span><b>{{stats.verified_count or 0}}</b></div><div><span>Ditolak</span><b>{{stats.rejected_count or 0}}</b></div></div>
    <form method="get" class="qcq-filters"><input name="q" value="{{keyword}}" placeholder="Cari invoice, member, kasir"><select name="status"><option value="">Semua status riwayat</option><option value="VERIFIED" {{'selected' if status_filter=='VERIFIED' else ''}}>Terverifikasi</option><option value="REJECTED" {{'selected' if status_filter=='REJECTED' else ''}}>Ditolak</option></select><select name="per_page"><option value="10" {{'selected' if per_page==10 else ''}}>10 per halaman</option><option value="20" {{'selected' if per_page==20 else ''}}>20 per halaman</option><option value="50" {{'selected' if per_page==50 else ''}}>50 per halaman</option></select><button class="btn btn-ghost">Terapkan</button></form>
    <div class="grid">
        <div class="col-12">
            <div class="card" style="border-left:4px solid #f59e0b;">
                <h3>⏳ Menunggu Verifikasi ({{ pending.total }})</h3>
                <div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Tanggal</th><th>Total</th><th>Metode</th><th>Member</th><th>Kasir</th><th>Aksi</th></tr></thead>
                <tbody>
                {% for q in pending.rows %}
                <tr>
                    <td><strong>{{ q.invoice_no }}</strong></td>
                    <td>{{ q.trx_date }}</td>
                    <td style="font-weight:700;color:#2563eb;">{{ rupiah(q.total) }}</td>
                    <td><span class="badge {{ 'badge-success' if q.payment_method == 'tunai' else 'badge-info' }}">{{ q.payment_method }}</span></td>
                    <td>{{ q.member_name or 'Umum' }}</td>
                    <td>{{ q.creator_name or '-' }}</td>
                    <td>
                        <div style="display:flex;gap:6px;flex-wrap:wrap;">
                            <a href="/quick-cashier/verify/{{ q.id }}" class="btn btn-sm btn-success">✅ Input Barang & Verifikasi</a>
                            <form method="POST" style="display:inline;">
                                <input type="hidden" name="qid" value="{{ q.id }}">
                                <button name="action" value="reject" class="btn-sm btn-danger" data-confirm="Yakin tolak transaksi ini?">❌ Tolak</button>
                            </form>
                        </div>
                    </td>
                </tr>
                {% else %}
                <tr><td colspan="7" class="muted text-center">✅ Tidak ada antrian pending. Semua sudah diproses.</td></tr>
                {% endfor %}
                </tbody></table></div>
                {% if pending.total_pages > 1 %}<div class="qcq-pager"><span>Halaman {{pending.page}} / {{pending.total_pages}}</span><div><a class="btn btn-sm btn-ghost {{'disabled' if pending.page<=1 else ''}}" href="{{url_for('quick_cashier_queue',p_page=pending.page-1,h_page=verified.page,q=keyword,status=status_filter,per_page=per_page)}}">Sebelumnya</a>{% for n in range(1,pending.total_pages+1) %}{% if n==1 or n==pending.total_pages or (n>=pending.page-2 and n<=pending.page+2) %}<a class="qcq-page {{'active' if n==pending.page else ''}}" href="{{url_for('quick_cashier_queue',p_page=n,h_page=verified.page,q=keyword,status=status_filter,per_page=per_page)}}">{{n}}</a>{% endif %}{% endfor %}<a class="btn btn-sm btn-ghost {{'disabled' if pending.page>=pending.total_pages else ''}}" href="{{url_for('quick_cashier_queue',p_page=pending.page+1,h_page=verified.page,q=keyword,status=status_filter,per_page=per_page)}}">Berikutnya</a></div></div>{% endif %}
            </div>
        </div>
        <div class="col-12">
            <div class="card">
                <h3>📜 Riwayat Verifikasi</h3>
                <div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Total</th><th>Status</th><th>Verifikator</th><th>Terverifikasi</th></tr></thead>
                <tbody>
                {% for q in verified.rows %}
                <tr>
                    <td>{{ q.invoice_no }}</td>
                    <td>{{ rupiah(q.total) }}</td>
                    <td><span class="badge {{ 'badge-success' if q.status == 'VERIFIED' else 'badge-danger' }}">{{ q.status }}</span></td>
                    <td>{{ q.verifier_name or '-' }}</td>
                    <td>{{ q.verified_at or '-' }}</td>
                </tr>
                {% else %}
                <tr><td colspan="5" class="muted text-center">Belum ada riwayat.</td></tr>
                {% endfor %}
                </tbody></table></div>
                {% if verified.total_pages > 1 %}<div class="qcq-pager"><span>Halaman {{verified.page}} / {{verified.total_pages}}</span><div><a class="btn btn-sm btn-ghost {{'disabled' if verified.page<=1 else ''}}" href="{{url_for('quick_cashier_queue',p_page=pending.page,h_page=verified.page-1,q=keyword,status=status_filter,per_page=per_page)}}">Sebelumnya</a>{% for n in range(1,verified.total_pages+1) %}{% if n==1 or n==verified.total_pages or (n>=verified.page-2 and n<=verified.page+2) %}<a class="qcq-page {{'active' if n==verified.page else ''}}" href="{{url_for('quick_cashier_queue',p_page=pending.page,h_page=n,q=keyword,status=status_filter,per_page=per_page)}}">{{n}}</a>{% endif %}{% endfor %}<a class="btn btn-sm btn-ghost {{'disabled' if verified.page>=verified.total_pages else ''}}" href="{{url_for('quick_cashier_queue',p_page=pending.page,h_page=verified.page+1,q=keyword,status=status_filter,per_page=per_page)}}">Berikutnya</a></div></div>{% endif %}
            </div>
        </div>
    </div></div>
    ''', pending=pending, verified=verified, stats=stats, keyword=keyword, status_filter=status_filter, per_page=per_page, rupiah=rupiah)
    return render_page('Verifikasi Quick Cashier', body)

def _qc_locations():
    try:
        rows = q_all('SELECT id, branch_code, name, COALESCE(is_active,1) is_active FROM koperasi_branches WHERE COALESCE(is_active,1)=1 ORDER BY CASE WHEN branch_code="PUSAT" THEN 0 ELSE 1 END, name')
    except Exception:
        rows = q_all('SELECT id, branch_code, name FROM koperasi_branches ORDER BY CASE WHEN branch_code="PUSAT" THEN 0 ELSE 1 END, name')
    return rows or []

def _qc_branch_id_from_value(v):
    try: bid=int(v or 0)
    except Exception: bid=0
    if bid<=0: return None
    return bid if q_one('SELECT id FROM koperasi_branches WHERE id=?',[bid]) else None

def _qc_selected_branch(queue, form_value=None):
    bid=_qc_branch_id_from_value(form_value)
    if bid: return bid
    try:
        if queue and 'stock_branch_id' in queue.keys() and queue['stock_branch_id']:
            return int(queue['stock_branch_id'])
    except Exception: pass
    return None

def _qc_is_pusat_branch(branch_id):
    r=q_one('SELECT branch_code FROM koperasi_branches WHERE id=?',[branch_id]) if branch_id else None
    return bool(r and r['branch_code']=='PUSAT')

def _qc_ensure_location_stock_rows(branch_id):
    if not branch_id: return
    if _qc_is_pusat_branch(branch_id):
        exec_sql('''INSERT OR IGNORE INTO product_branch_stock(product_id, branch_id, stock, min_stock)
                    SELECT id, ?, COALESCE(stock,0), COALESCE(min_stock,0) FROM products WHERE active=1''',[branch_id])
        exec_sql('''UPDATE product_branch_stock
                    SET stock=(SELECT COALESCE(p.stock,0) FROM products p WHERE p.id=product_branch_stock.product_id),
                        min_stock=(SELECT COALESCE(p.min_stock,0) FROM products p WHERE p.id=product_branch_stock.product_id)
                    WHERE branch_id=?''',[branch_id])
    else:
        exec_sql('''INSERT OR IGNORE INTO product_branch_stock(product_id, branch_id, stock, min_stock)
                    SELECT id, ?, 0, COALESCE(min_stock,0) FROM products WHERE active=1''',[branch_id])

def _qc_product_rows(branch_id, q=''):
    if not branch_id: return []
    _qc_ensure_location_stock_rows(branch_id)
    params=[branch_id]
    where='WHERE p.active=1'
    if q:
        qq='%'+str(q).lower().strip()+'%'
        where+=' AND (LOWER(p.product_name) LIKE ? OR LOWER(p.barcode) LIKE ? OR CAST(p.id AS TEXT)=?)'
        params += [qq,qq,str(q).strip()]
    return q_all(f'''SELECT p.id,p.barcode,p.product_name,p.sell_price,COALESCE(pbs.stock,0) stock,COALESCE(pbs.min_stock,p.min_stock,0) min_stock
                     FROM products p LEFT JOIN product_branch_stock pbs ON pbs.product_id=p.id AND pbs.branch_id=?
                     {where}
                     ORDER BY CASE WHEN COALESCE(pbs.stock,0)>0 THEN 0 ELSE 1 END, p.product_name ASC LIMIT 80''', params)

def _qc_find_product(branch_id, text='', product_id=0):
    if not branch_id: return None
    _qc_ensure_location_stock_rows(branch_id)
    try: product_id=int(product_id or 0)
    except Exception: product_id=0
    if product_id>0:
        return q_one('''SELECT p.id,p.barcode,p.product_name,p.sell_price,COALESCE(pbs.stock,0) stock
                        FROM products p LEFT JOIN product_branch_stock pbs ON pbs.product_id=p.id AND pbs.branch_id=?
                        WHERE p.id=? AND p.active=1''',[branch_id,product_id])
    text=(text or '').strip(); first=text.split('|')[0].strip()
    if first.isdigit():
        r=q_one('''SELECT p.id,p.barcode,p.product_name,p.sell_price,COALESCE(pbs.stock,0) stock
                   FROM products p LEFT JOIN product_branch_stock pbs ON pbs.product_id=p.id AND pbs.branch_id=?
                   WHERE p.id=? AND p.active=1''',[branch_id,int(first)])
        if r: return r
    if not text: return None
    return q_one('''SELECT p.id,p.barcode,p.product_name,p.sell_price,COALESCE(pbs.stock,0) stock
                    FROM products p LEFT JOIN product_branch_stock pbs ON pbs.product_id=p.id AND pbs.branch_id=?
                    WHERE p.active=1 AND (p.barcode=? OR LOWER(p.product_name) LIKE ?)
                    ORDER BY CASE WHEN p.barcode=? THEN 0 ELSE 1 END, p.product_name LIMIT 1''',[branch_id,text,'%'+text.lower()+'%',text])

def _qc_stock_for_conn(conn, product_id, branch_id):
    r=conn.execute('SELECT COALESCE(stock,0) stock FROM product_branch_stock WHERE product_id=? AND branch_id=?',[product_id,branch_id]).fetchone()
    return float(r['stock'] or 0) if r else 0.0

