@app.route('/loans', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'bendahara', 'user', 'branch_admin')
def loans():
    user = current_user()
    is_staff = user['role'] in ('admin', 'bendahara', 'branch_admin')
    my_member = q_one('SELECT * FROM members WHERE member_code=?', [f'EMP-{user["employee_number"]}']) if user['role'] == 'user' else None

    if request.method == 'POST':
        if not is_staff:
            flash('Pengajuan anggota hanya dapat dibuat dari menu Ajukan Pinjaman.', 'warning')
            return redirect(url_for('apply_loan'))
        action = request.form.get('action', '')
        loan_id = int(request.form.get('loan_id') or 0)
        loan = q_one('SELECT * FROM loans WHERE id=?', [loan_id]) if loan_id else None
        if not loan:
            flash('Data pinjaman tidak ditemukan.', 'error')
            return redirect(url_for('loans'))
        if action == 'approve_loan':
            schedules = q_one('SELECT COUNT(*) AS n FROM loan_schedules WHERE loan_id=?', [loan_id])['n'] or 0
            if loan['status'] != 'CALCULATED' or schedules < 1:
                flash('Pinjaman hanya dapat disetujui setelah kalkulasi final dan jadwal angsuran tersedia.', 'error')
                return redirect(url_for('loan_detail', loan_id=loan_id))
            exec_sql('UPDATE loans SET status="Berjalan", current_stage="ACTIVE", progress_percent=80, approved_by=?, approved_at=? WHERE id=?', [user['id'], now_str(), loan_id])
            exec_sql("UPDATE approval_requests SET status='Approved', approved_by=?, approved_at=? WHERE ref_table='loans' AND ref_id=? AND status='Pending'", [user['id'], now_str(), loan_id])
            add_timeline(loan_id, 'APPROVED', 'Pengajuan disetujui; pinjaman resmi berjalan.', user['id'])
            log_action('LOAN_APPROVED', 'loans', loan_id, loan['loan_no'])
            notify_member(loan['member_id'], 'Pinjaman Disetujui', f'Pengajuan {loan["loan_no"]} telah disetujui dan mulai berjalan.')
            flash('Pinjaman berhasil disetujui dan diaktifkan.', 'success')
        elif action == 'reject_loan':
            reason = request.form.get('reject_reason', '').strip()
            if loan['status'] not in ('SUBMITTED', 'CALCULATED'):
                flash('Status pinjaman ini tidak dapat ditolak.', 'error')
            elif len(reason) < 10:
                flash('Alasan penolakan wajib jelas, minimal 10 karakter.', 'error')
            else:
                exec_sql('UPDATE loans SET status="Ditolak", current_stage="REJECTED", progress_percent=100, admin_note=? WHERE id=?', [reason, loan_id])
                exec_sql("UPDATE approval_requests SET status='Rejected', reason=?, approved_by=?, approved_at=? WHERE ref_table='loans' AND ref_id=? AND status='Pending'", [reason, user['id'], now_str(), loan_id])
                add_timeline(loan_id, 'REJECTED', reason, user['id'])
                log_action('LOAN_REJECTED', 'loans', loan_id, reason)
                notify_member(loan['member_id'], 'Pengajuan Pinjaman Ditolak', f'{loan["loan_no"]}: {reason}')
                flash('Pengajuan ditolak dan alasan telah dikirim kepada anggota.', 'warning')
        return redirect(url_for('loans'))

    if is_staff:
        loans_rows = q_all('''SELECT l.*,m.member_code,m.name,lt.name loan_type_name,
            COALESCE((SELECT SUM(amount) FROM loan_payments p WHERE p.loan_id=l.id AND p.status="VERIFIED"),0) paid
            FROM loans l LEFT JOIN members m ON m.id=l.member_id LEFT JOIN loan_types lt ON lt.id=l.loan_type_id
            ORDER BY CASE l.status WHEN "SUBMITTED" THEN 0 WHEN "CALCULATED" THEN 1 WHEN "Berjalan" THEN 2 WHEN "Ditolak" THEN 3 ELSE 4 END,l.id DESC''')
    else:
        loans_rows = q_all('''SELECT l.*,m.member_code,m.name,lt.name loan_type_name,
            COALESCE((SELECT SUM(amount) FROM loan_payments p WHERE p.loan_id=l.id AND p.status="VERIFIED"),0) paid
            FROM loans l LEFT JOIN members m ON m.id=l.member_id LEFT JOIN loan_types lt ON lt.id=l.loan_type_id
            WHERE l.member_id=? ORDER BY l.id DESC''', [my_member['id']]) if my_member else []
    data=[]
    for r in loans_rows:
        d=dict(r); d['remaining']=max(0,float(d.get('total_receivable') or 0)-float(d.get('paid') or 0)); d['meta']=loan_status_meta(d.get('status')); data.append(d)
    counts={k:sum(1 for x in data if x['status']==k) for k in ('SUBMITTED','CALCULATED','Berjalan','Lunas','Ditolak')}
    total_outstanding=sum(x['remaining'] for x in data if x['status']=='Berjalan')

    body=render_template_string('''
    <div class="loan-hero"><div><span class="loan-eyebrow">PUSAT KREDIT KOPERASI</span><h2>{{ 'Meja Analisis Kredit' if is_staff else 'Pinjaman Saya' }}</h2><p>{{ 'Periksa kelengkapan, kalkulasi, putuskan, lalu pantau pembayaran dalam alur yang tertib.' if is_staff else 'Pantau pengajuan, keputusan, kontrak, jadwal, dan pembayaran dari satu halaman.' }}</p></div><div class="loan-hero-actions">{% if not is_staff %}<a class="btn btn-success" href="{{url_for('apply_loan')}}">＋ Ajukan Kredit</a>{% endif %}</div></div>
    <div class="loan-steps"><div class="done"><b>1</b><span>Pengajuan</span></div><div><b>2</b><span>Pemeriksaan</span></div><div><b>3</b><span>Kalkulasi</span></div><div><b>4</b><span>Keputusan</span></div><div><b>5</b><span>Angsuran</span></div></div>
    <div class="metrics"><div class="metric"><div class="label">Menunggu Pemeriksaan</div><div class="value">{{counts.SUBMITTED}}</div></div><div class="metric"><div class="label">Menunggu Keputusan</div><div class="value">{{counts.CALCULATED}}</div></div><div class="metric"><div class="label">Pinjaman Aktif</div><div class="value">{{counts.Berjalan}}</div></div><div class="metric"><div class="label">Sisa Berjalan</div><div class="value">{{rupiah(total_outstanding)}}</div></div></div>
    <div class="card"><div class="kartu"><div><h2>{{ 'Antrean & Portofolio Kredit' if is_staff else 'Riwayat Pengajuan Kredit' }}</h2><div class="muted small">Klik Detail untuk melihat prosedur, timeline, dan jadwal secara lengkap.</div></div>{% if is_staff %}<a class="btn btn-sm btn-ghost" href="{{url_for('loan_admin_check')}}">Pemeriksaan Sistem</a>{% endif %}</div>
    <div class="loan-list">{% for r in rows %}<article class="loan-item"><div class="loan-item-main"><div class="loan-number">{{r.loan_no}}</div><h3>{{r.name if is_staff else (r.loan_type_name or 'Pinjaman Koperasi')}}</h3><div class="muted small">{{r.member_code}} · {{r.loan_type_name or 'Jenis belum ditentukan'}} · {{r.loan_date}}</div></div><div class="loan-amount"><small>Pokok</small><strong>{{rupiah(r.principal)}}</strong><span>Sisa {{rupiah(r.remaining)}}</span></div><div class="loan-state"><span class="badge {{r.meta[1]}}">{{r.meta[0]}}</span><div class="progress-bar"><div class="progress-fill" style="width:{{r.meta[2]}}%"></div></div></div><div class="loan-actions"><a href="{{url_for('loan_detail',loan_id=r.id)}}" class="btn btn-sm btn-ghost">Detail</a>{% if is_staff and r.status=='SUBMITTED' %}<a href="{{url_for('calculate_loan',loan_id=r.id)}}" class="btn btn-sm btn-warn">Analisis</a>{% endif %}{% if is_staff and r.status=='CALCULATED' %}<form method="post" style="display:inline"><input type="hidden" name="action" value="approve_loan"><input type="hidden" name="loan_id" value="{{r.id}}"><button class="btn btn-sm btn-success" data-confirm="Setujui hasil kalkulasi dan aktifkan pinjaman?">Setujui</button></form>{% endif %}{% if is_staff and r.status in ('SUBMITTED','CALCULATED') %}<details class="loan-reject"><summary>Tolak</summary><form method="post"><input type="hidden" name="action" value="reject_loan"><input type="hidden" name="loan_id" value="{{r.id}}"><input name="reject_reason" minlength="10" placeholder="Alasan penolakan" required><button class="btn btn-sm btn-danger">Konfirmasi</button></form></details>{% endif %}{% if not is_staff and r.status=='Berjalan' %}<a href="{{url_for('pay_loan_installment',loan_id=r.id)}}" class="btn btn-sm btn-success">Bayar</a>{% endif %}</div></article>{% else %}<div class="loan-empty"><div>◇</div><h3>Belum ada pengajuan</h3><p>Mulai dari simulasi agar nominal dan tenor sesuai kemampuan.</p>{% if not is_staff %}<a class="btn" href="{{url_for('apply_loan')}}">Ajukan Kredit</a>{% endif %}</div>{% endfor %}</div></div>
    ''', rows=data, counts=counts, total_outstanding=total_outstanding, is_staff=is_staff, rupiah=rupiah)
    return render_page('Kredit & Pinjaman', body)

@app.route('/loans/admin-check')
@login_required
@role_required('admin', 'bendahara', 'supervisor')
def loan_admin_check():
    db_path = str(Path(DB_NAME).resolve())
    rows = q_all("SELECT l.id,l.loan_no,l.status,l.loan_date,l.principal,m.name,m.member_code FROM loans l LEFT JOIN members m ON m.id=l.member_id ORDER BY l.id DESC LIMIT 100")
