@app.route('/loans/detail/<int:loan_id>', methods=['GET', 'POST'])
@login_required
def loan_detail(loan_id):
    user = current_user()
    is_admin = user['role'] in ['admin', 'bendahara', 'branch_admin']
    loan = q_one('SELECT l.*, m.member_code, m.name, lt.name as loan_type_name FROM loans l LEFT JOIN members m ON m.id=l.member_id LEFT JOIN loan_types lt ON lt.id=l.loan_type_id WHERE l.id = ?', [loan_id])
    if not loan:
        flash('Pinjaman tidak ditemukan', 'error')
        return redirect(url_for('loans'))
    if not is_admin:
        member = q_one('SELECT id FROM members WHERE member_code = ?', [f'EMP-{user["employee_number"]}'])
        if not member or loan['member_id'] != member['id']:
            flash('Akses ditolak.', 'error')
            return redirect(url_for('loans'))
    documents = q_all('SELECT * FROM loan_documents WHERE loan_id = ? ORDER BY id ASC', [loan_id])
    timeline = q_all('SELECT t.*, u.full_name FROM loan_timeline t LEFT JOIN users u ON u.id = t.created_by WHERE loan_id = ? ORDER BY id ASC', [loan_id])
    body = render_template_string('<div class="card"><div class="kartu"><div><h2>#{{ loan.loan_no }}</h2><div class="muted small">{{ loan.member_code }} — {{ loan.name }}</div></div><div class="badge badge-info">{{ loan.status }}</div></div><div class="grid"><div class="col-6"><h3>Ringkasan Kredit</h3><table><tr><td>Pokok</td><td>{{ rupiah(loan.principal) }}</td></tr><tr><td>Fee</td><td>{{ rupiah(loan.service_fee) }}</td></tr><tr><td>Total Tagihan</td><td>{{ rupiah(loan.total_receivable) }}</td></tr><tr><td>Angsuran/bln</td><td>{{ rupiah(loan.monthly_installment) }}</td></tr><tr><td>Tenor</td><td>{{ loan.tenor_month }} bulan</td></tr><tr><td>Bunga</td><td>{{ loan.interest_rate }}%/bln</td></tr></table></div><div class="col-6"><h3>Riwayat Proses</h3><div class="timeline">{% for t in timeline %}<div class="timeline-item"><div class="timeline-dot"></div><div><strong>{{ t.status }}</strong><div class="muted small">{{ t.full_name }} • {{ t.created_at }}</div>{% if t.note %}<div class="small">{{ t.note }}</div>{% endif %}</div></div>{% else %}<div class="muted">Belum ada timeline.</div>{% endfor %}</div></div></div></div>', loan=loan, documents=documents, timeline=timeline, rupiah=rupiah)
    return render_page(f'Detail #{loan["loan_no"]}', '<div class="credit-page credit-detail-page">'+body+'</div>')

@app.route('/loans/calculate/<int:loan_id>', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'bendahara', 'branch_admin')
def calculate_loan(loan_id):
    loan = q_one('SELECT l.*, m.name, m.member_code, lt.name as loan_type_name, lt.metode_bunga FROM loans l LEFT JOIN members m ON m.id=l.member_id LEFT JOIN loan_types lt ON lt.id=l.loan_type_id WHERE l.id = ?', [loan_id])
    if not loan:
        flash('Pengajuan pinjaman tidak ditemukan', 'error')
        return redirect(url_for('loans'))
    if request.method == 'POST':
        principal = parse_float(request.form.get('principal', loan['principal']))
        service_fee = parse_float(request.form.get('service_fee', loan['service_fee']))
        interest_rate = parse_float(request.form.get('interest_rate', loan['interest_rate']))
        tenor_month = int(request.form.get('tenor_month', loan['tenor_month']))
        admin_note = request.form.get('admin_note', '').strip()
        if principal <= 0 or tenor_month < 1:
            flash('Pokok dan tenor harus valid.', 'error')
            return redirect(url_for('calculate_loan', loan_id=loan_id))
        terms = compute_loan_terms(principal, service_fee, interest_rate, tenor_month, loan['metode_bunga'] or 'FLAT')
        total_receivable = terms['total_receivable']
        monthly_installment = terms['monthly_installment']
        exec_sql('UPDATE loans SET principal = ?, service_fee = ?, interest_rate = ?, tenor_month = ?, total_receivable = ?, monthly_installment = ?, admin_note = ?, status = "CALCULATED", calculated_by = ?, calculated_at = ? WHERE id = ?', [
            principal, service_fee, interest_rate, tenor_month, total_receivable, monthly_installment, admin_note, session['user_id'], now_str(), loan_id
        ])
        exec_sql('DELETE FROM loan_schedules WHERE loan_id = ?', [loan_id])
        schedules = []
        loan_date_parsed = datetime.strptime(loan['loan_date'], '%Y-%m-%d') if loan['loan_date'] else datetime.now()
        for i in range(1, tenor_month + 1):
            due_month = loan_date_parsed.month + i
            due_year = loan_date_parsed.year + (due_month - 1) // 12
            due_month = ((due_month - 1) % 12) + 1
            due_date = f"{due_year}-{due_month:02d}-25"
            schedules.append((loan_id, i, due_date, monthly_installment, principal/tenor_month, monthly_installment - principal/tenor_month))
        exec_sql('INSERT INTO loan_schedules(loan_id, installment_number, due_date, amount, principal_amount, interest_amount) VALUES (?, ?, ?, ?, ?, ?)', schedules, many=True)
        exec_sql('UPDATE loans SET current_stage="DECISION", progress_percent=55 WHERE id=?', [loan_id])
        add_timeline(loan_id, 'CALCULATED', 'Kalkulasi final dan jadwal angsuran telah dibuat.')
        flash('Kalkulasi final berhasil. Lanjutkan ke pemeriksaan detail sebelum keputusan.', 'success')
        return redirect(url_for('loans'))
    schedules = q_all('SELECT * FROM loan_schedules WHERE loan_id = ? ORDER BY installment_number', [loan_id])
    body = render_template_string('<div class="card"><h2>Analisis dan Kalkulasi  #{{ loan.loan_no }}</h2><div class="badge badge-info">{{ loan.member_code }} — {{ loan.name }}</div><hr><div class="grid"><div class="col-6"><form method="POST"><div class="form-group"><label>Pokok</label><input type="number" name="principal" value="{{ loan.principal }}"></div><div class="form-group"><label>Fee</label><input type="number" name="service_fee" value="{{ loan.service_fee }}"></div><div class="form-group"><label>Bunga %</label><input type="number" name="interest_rate" value="{{ loan.interest_rate }}"></div><div class="form-group"><label>Tenor</label><input type="number" name="tenor_month" value="{{ loan.tenor_month }}"></div><div class="form-group"><label>Catatan</label><textarea name="admin_note">{{ loan.admin_note }}</textarea></div><button type="submit">✅ Hitung</button></form></div><div class="col-6"><div class="metric"><div class="label">Angsuran/Bulan</div><div class="value" style="color:#2563eb;">{{ rupiah(loan.monthly_installment) }}</div></div></div></div>{% if schedules %}<hr><h3>Jadwal Angsuran</h3><div class="table-wrap"><table><thead><tr><th>Ke</th><th>Jatuh Tempo</th><th>Pokok</th><th>Bunga</th><th>Total</th></tr></thead><tbody>{% for s in schedules %}<tr><td>{{ s.installment_number }}</td><td>{{ s.due_date }}</td><td>{{ rupiah(s.principal_amount) }}</td><td>{{ rupiah(s.interest_amount) }}</td><td>{{ rupiah(s.amount) }}</td></tr>{% endfor %}</tbody></table></div>{% endif %}</div>', loan=loan, schedules=schedules, rupiah=rupiah)
    return render_page('Analisis Kredit', '<div class="credit-page credit-analysis-page">'+body+'</div>')

@app.route('/loans/contract-pdf/<int:loan_id>')
@login_required
@role_required('admin', 'bendahara', 'user')
def loan_contract_pdf(loan_id):
    loan = q_one('SELECT l.*, m.member_code, m.name FROM loans l LEFT JOIN members m ON m.id=l.member_id WHERE l.id = ?', [loan_id])
    if not loan:
        flash('Pinjaman tidak ditemukan', 'error')
        return redirect(url_for('loans'))
    user = current_user()
    if user['role'] == 'user':
        member = q_one('SELECT id FROM members WHERE member_code = ?', [f'EMP-{user["employee_number"]}'])
        if not member or loan['member_id'] != member['id']:
            flash('Akses ditolak.', 'error')
            return redirect(url_for('loans'))
    buf = BytesIO(); c = canvas.Canvas(buf, pagesize=A4); w,h = A4; y = h - 15*mm
    c.setFont('Helvetica-Bold', 16); c.drawString(15*mm, y, APP_TITLE); y -= 8*mm
    c.setFont('Helvetica-Bold', 14); c.drawString(15*mm, y, 'KONTRAK PINJAMAN'); y -= 10*mm
    c.setFont('Helvetica', 10)
    for l in [f'No: {loan["loan_no"]}', f'Tanggal: {loan["loan_date"]}', '', 'Peminjam:', f'{loan["name"]} ({loan["member_code"]})', '', 'Pinjaman:', f'Pokok: {rupiah(loan["principal"])}', f'Fee: {rupiah(loan["service_fee"])}', f'Total: {rupiah(loan["total_receivable"])}', f'Tenor: {loan["tenor_month"]} bulan', f'Angsuran: {rupiah(loan["monthly_installment"])}/bulan']:
        c.drawString(15*mm, y, l); y -= 5*mm
    y -= 10*mm; c.drawString(15*mm, y, 'Dengan ini peminjam setuju membayar angsuran tepat waktu.'); c.showPage(); c.save()
    buf.seek(0)
    return send_file(buf, as_attachment=True, download_name=f'kontrak_{loan["loan_no"]}.pdf', mimetype='application/pdf')

