@app.route('/purchase-orders', methods=['GET', 'POST'])
@login_required
@role_required('admin')
def purchase_orders():
    if request.method == 'POST':
        action = request.form.get('action')
        if action == 'create_po':
            supplier_id = int(request.form.get('supplier_id') or 0)
            po_date = request.form.get('po_date', today_str())
            note = request.form.get('note', '').strip()
            product_ids = request.form.getlist('product_id[]') or request.form.getlist('product_id')
            qtys = request.form.getlist('qty[]') or request.form.getlist('qty')
            prices = request.form.getlist('price[]') or request.form.getlist('price')
            if supplier_id <= 0:
                flash('Pilih supplier.', 'error')
                return redirect(url_for('purchase_orders'))
            clean_items = []
            for idx, pid_raw in enumerate(product_ids):
                pid = int(pid_raw or 0)
                qty = parse_float(qtys[idx] if idx < len(qtys) else 0)
                price = parse_float(prices[idx] if idx < len(prices) else 0)
                if pid > 0 and qty > 0:
                    if price <= 0:
                        flash('Harga beli setiap item PO wajib lebih dari 0.', 'error')
                        return redirect(url_for('purchase_orders'))
                    clean_items.append((pid, qty, price, qty * price))
            po_no = gen_code('PO')
            po_id = exec_sql('INSERT INTO purchase_orders(po_no, po_date, supplier_id, note, created_by) VALUES (?, ?, ?, ?, ?)', [po_no, po_date, supplier_id, note, session.get('user_id')])
            if clean_items:
                exec_sql('INSERT INTO purchase_items(po_id, product_id, qty, price, subtotal, supplier_status, confirmed_qty, supplier_price, supplier_price_diff, supplier_subtotal) VALUES (?, ?, ?, ?, ?, "PENDING", 0, ?, 0, 0)', [(po_id, pid, qty, price, subtotal, price) for pid, qty, price, subtotal in clean_items], many=True)
                total = sum(x[3] for x in clean_items)
                exec_sql('UPDATE purchase_orders SET total = ?, supplier_total = ?, status="SENT" WHERE id=?', [total, total, po_id])
                flash(f'PO {po_no} berhasil dibuat, otomatis dikirim ke supplier dengan {len(clean_items)} item.', 'success')
            else:
                flash(f'PO {po_no} berhasil dibuat. Tambahkan item barang di detail PO.', 'success')
            return redirect(url_for('purchase_orders', po_id=po_id))
        elif action == 'send_supplier':
            po_id = int(request.form.get('po_id') or 0)
            po = q_one('SELECT * FROM purchase_orders WHERE id=? AND status IN ("DRAFT","CONFIRMED","PARTIAL")', [po_id])
            cnt = q_one('SELECT COUNT(*) n FROM purchase_items WHERE po_id=?', [po_id])['n'] if po else 0
            if not po or cnt <= 0:
                flash('PO harus DRAFT dan punya item sebelum dikirim ke supplier.', 'error')
            else:
                exec_sql('UPDATE purchase_orders SET status="SENT" WHERE id=?', [po_id])
                exec_sql('UPDATE purchase_items SET supplier_status="PENDING", confirmed_qty=0, supplier_note=NULL, supplier_price=price, supplier_price_diff=0, supplier_subtotal=0 WHERE po_id=?', [po_id])
                exec_sql('UPDATE purchase_orders SET supplier_total=COALESCE((SELECT SUM(subtotal) FROM purchase_items WHERE po_id=?),0), has_price_change=0 WHERE id=?', [po_id, po_id])
                flash('PO berhasil dikirim ke portal supplier.', 'success')
            return redirect(url_for('purchase_orders', po_id=po_id))
        elif action == 'add_item':
            po_id = int(request.form.get('po_id'))
            product_id = int(request.form.get('product_id') or 0)
            qty = parse_float(request.form.get('qty', 0))
            price = parse_float(request.form.get('price', 0))
            if product_id <= 0 or qty <= 0:
                flash('Pilih barang dan qty > 0.', 'error')
            else:
                subtotal = qty * price
                exec_sql('INSERT INTO purchase_items(po_id, product_id, qty, price, subtotal, supplier_status, confirmed_qty, supplier_price, supplier_price_diff, supplier_subtotal) VALUES (?, ?, ?, ?, ?, "PENDING", 0, ?, 0, 0)', [po_id, product_id, qty, price, subtotal, price])
                exec_sql('UPDATE purchase_orders SET total = COALESCE((SELECT SUM(subtotal) FROM purchase_items WHERE po_id=?), 0), supplier_total = COALESCE((SELECT SUM(CASE WHEN supplier_subtotal>0 THEN supplier_subtotal ELSE subtotal END) FROM purchase_items WHERE po_id=?), 0) WHERE id=?', [po_id, po_id, po_id])
                flash('Item ditambahkan.', 'success')
            return redirect(url_for('purchase_orders', po_id=po_id))
        elif action == 'delete_item':
            po_id = int(request.form.get('po_id') or 0)
            item_id = int(request.form.get('item_id') or 0)
            po = q_one('SELECT * FROM purchase_orders WHERE id=? AND status IN ("DRAFT","CONFIRMED","PARTIAL")', [po_id])
            if not po:
                flash('Item tidak bisa dihapus karena PO sudah diterima / tidak ditemukan.', 'error')
            else:
                exec_sql('DELETE FROM purchase_items WHERE id=? AND po_id=?', [item_id, po_id])
                exec_sql('UPDATE purchase_orders SET total = COALESCE((SELECT SUM(subtotal) FROM purchase_items WHERE po_id=?), 0) WHERE id=?', [po_id, po_id])
                flash('Item PO dihapus.', 'success')
            return redirect(url_for('purchase_orders', po_id=po_id))
        elif action == 'receive':
            po_id = int(request.form.get('po_id'))
            po = q_one('SELECT * FROM purchase_orders WHERE id=? AND status="DRAFT"', [po_id])
            if not po:
                flash('PO tidak ditemukan atau sudah diterima.', 'error')
                return redirect(url_for('purchase_orders'))
            items = q_all('SELECT * FROM purchase_items WHERE po_id=?', [po_id])
            if not items:
                flash('PO belum memiliki item barang.', 'error')
                return redirect(url_for('purchase_orders', po_id=po_id))
            bid = get_branch_id()
            for it in items:
                qty_receive = float(it['confirmed_qty'] or 0) if po['status'] in ('CONFIRMED','PARTIAL') else float(it['qty'] or 0)
                if (it['supplier_status'] or '').upper() == 'REJECTED':
                    continue
                unit_price_receive = float(it['supplier_price'] or it['price'] or 0) if po['status'] in ('CONFIRMED','PARTIAL') else float(it['price'] or 0)
                if qty_receive <= 0 or unit_price_receive <= 0:
                    flash('PO memiliki item dengan qty/harga tidak valid atau belum dikonfirmasi supplier.', 'error')
                    return redirect(url_for('purchase_orders', po_id=po_id))
            for it in items:
                if (it['supplier_status'] or '').upper() == 'REJECTED':
                    continue
                qty_receive = float(it['confirmed_qty'] or 0) if po['status'] in ('CONFIRMED','PARTIAL') else float(it['qty'] or 0)
                unit_price_receive = float(it['supplier_price'] or it['price'] or 0) if po['status'] in ('CONFIRMED','PARTIAL') else float(it['price'] or 0)
                add_stock_with_fifo(it['product_id'], qty_receive, unit_price_receive, po_id=po_id, branch_id=bid, entry_date=po['po_date'], movement_type='Pembelian', note=f'PO {po["po_no"]}')
            exec_sql('UPDATE purchase_orders SET status="RECEIVED", received_at=? WHERE id=?', [now_str(), po_id])
            log_action('RECEIVE', 'purchase_orders', po_id, f'PO {po["po_no"]} diterima')
            flash(f'PO {po["po_no"]} diterima, stok bertambah.', 'success')
            return redirect(url_for('purchase_orders'))
    suppliers_rows = q_all("SELECT id, supplier_code, name FROM suppliers WHERE is_active=1 ORDER BY name ASC")
    products_rows = q_all("SELECT id, barcode, product_name, category, unit, buy_price FROM products WHERE active=1 ORDER BY product_name ASC")
    po_id = request.args.get('po_id', '')
    po_edit = q_one('SELECT po.*, s.name as supplier_name FROM purchase_orders po LEFT JOIN suppliers s ON s.id=po.supplier_id WHERE po.id=?', [po_id]) if po_id else None
    po_items = q_all('SELECT pi.*, p.barcode, p.product_name FROM purchase_items pi LEFT JOIN products p ON p.id=pi.product_id WHERE pi.po_id=?', [po_id]) if po_id else []
    rows = q_all('SELECT po.*, s.name as supplier_name FROM purchase_orders po LEFT JOIN suppliers s ON s.id=po.supplier_id ORDER BY po.id DESC LIMIT 100')
    body = render_template_string('''
    <div class="grid">
        <div class="col-4"><div class="card"><h2>📋 Buat PO</h2>
            <form method="post"><input type="hidden" name="action" value="create_po">
                <div class="form-group"><label>Supplier</label><select name="supplier_id">{% for s in suppliers_rows %}<option value="{{ s['id'] }}">{{ s['supplier_code'] }} — {{ s['name'] }}</option>{% endfor %}</select></div>
                <div class="form-group"><label>Tanggal</label><input type="date" name="po_date" value="{{ today }}"></div>
                <div class="form-group"><label>Barang yang diorder dalam 1 PO</label>
                  <div class="table-wrap"><table id="poBulkTable"><thead><tr><th>Barang</th><th>Qty</th><th>Harga Beli</th><th></th></tr></thead><tbody>
                    <tr class="po-row"><td><select name="product_id[]" onchange="fillPoPrice(this, this.closest('tr').querySelector('[name=\"price[]\"]'))"><option value="0">-- pilih barang --</option>{% for p in products_rows %}<option value="{{ p.id }}" data-price="{{ p.buy_price or 0 }}">{{ p.barcode }} — {{ p.product_name }} ({{ p.category or 'Umum' }})</option>{% endfor %}</select></td><td><input type="number" name="qty[]" step="0.001" min="0" placeholder="Qty"></td><td><input type="number" name="price[]" step="0.01" min="0" placeholder="Harga"></td><td><button type="button" class="btn-sm btn-ghost" onclick="removePoRow(this)">Hapus</button></td></tr>
                  </tbody></table></div><button type="button" class="btn btn-sm btn-ghost" onclick="addPoRow()" style="margin-top:8px;">+ Tambah Baris Barang</button></div>
                <div class="form-group"><label>Catatan</label><textarea name="note" style="min-height:50px;"></textarea></div>
                <button type="submit">📤 Buat PO + Order Barang</button>
            </form>
        </div></div>
        <div class="col-8"><div class="card"><h2>Daftar Purchase Order</h2>
            <div class="table-wrap"><table><thead><tr><th>PO</th><th>Tanggal</th><th>Supplier</th><th>Total</th><th>Status</th><th>Aksi</th></tr></thead>
            <tbody>{% for r in rows %}<tr><td>{{ r['po_no'] }}</td><td>{{ r['po_date'] }}</td><td>{{ r['supplier_name'] or '-' }}</td><td>{{ rupiah(r['total']) }}</td><td><span class="badge {{ 'badge-warn' if r['status']=='DRAFT' else 'badge-success' }}">{{ r['status'] }}</span></td><td><a href="{{ url_for('purchase_orders', po_id=r['id']) }}" class="btn btn-sm btn-ghost">Detail</a></td></tr>{% else %}<tr><td colspan="6" class="muted text-center">Belum ada PO.</td></tr>{% endfor %}</tbody></table></div>
        </div></div>
    </div>
    {% if po_edit %}
    <div class="card"><div class="kartu"><div><h2>📄 {{ po_edit['po_no'] }} — {{ po_edit['supplier_name'] }}</h2><div class="muted small">{{ po_edit['note'] or '-' }} | Status: <span class="badge {{ 'badge-warn' if po_edit['status']=='DRAFT' else 'badge-success' }}">{{ po_edit['status'] }}</span></div></div>
    <div style="text-align:right;">Total PO: <strong>{{ rupiah(po_edit['total']) }}</strong><br>Total Supplier: <strong style="color:#2563eb;">{{ rupiah(po_edit['supplier_total'] or po_edit['total']) }}</strong>{% if po_edit['has_price_change'] %}<br><span class="badge badge-danger">Ada perubahan harga</span>{% endif %}</div></div>
    <div class="alert alert-info" style="margin-top:8px;">Info Supplier: ETA <b>{{ po_edit['supplier_eta'] or '-' }}</b> | Ref/Invoice <b>{{ po_edit['supplier_reference'] or '-' }}</b> | Catatan <b>{{ po_edit['supplier_delivery_note'] or '-' }}</b></div>
    {% if po_edit['status'] == 'DRAFT' %}
    <form method="post" style="display:flex;gap:8px;flex-wrap:wrap;align-items:end;"><input type="hidden" name="action" value="add_item"><input type="hidden" name="po_id" value="{{ po_edit['id'] }}">
        <div><label class="small muted">Barang</label><select name="product_id" onchange="fillPoPrice(this, 'poDetailPrice')" style="width:260px;">{% for p in products_rows %}<option value="{{ p['id'] }}" data-price="{{ p['buy_price'] or 0 }}">{{ p['barcode'] }} — {{ p['product_name'] }} ({{ p['category'] or 'Umum' }})</option>{% endfor %}</select></div>
        <div><label class="small muted">Qty</label><input type="number" name="qty" step="0.01" min="0.01" style="width:80px;"></div>
        <div><label class="small muted">Harga Beli</label><input type="number" name="price" id="poDetailPrice" step="0.01" min="0" style="width:120px;"></div>
        <button class="btn-sm" type="submit">Tambah Barang Order</button>
    </form>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px;"><form method="post"><input type="hidden" name="action" value="send_supplier"><input type="hidden" name="po_id" value="{{ po_edit['id'] }}"><button class="btn-ghost" type="submit" data-confirm="Kirim PO ini ke portal supplier?">Kirim ke Supplier</button></form><form method="post"><input type="hidden" name="action" value="receive"><input type="hidden" name="po_id" value="{{ po_edit['id'] }}"><button class="btn-success" type="submit" data-confirm="Terima PO ini? Stok akan bertambah.">Terima Barang</button></form></div>
    {% endif %}
    <div class="table-wrap" style="margin-top:12px;"><table><thead><tr><th>Barang</th><th>Qty Pesan</th><th>Qty OK Supplier</th><th>Harga PO</th><th>Harga Supplier</th><th>Selisih</th><th>Status Supplier</th><th>Catatan Supplier</th><th>Total Supplier</th><th>Aksi</th></tr></thead>
    <tbody>{% for i in po_items %}<tr><td>{{ i['barcode'] }} — {{ i['product_name'] }}</td><td>{{ i['qty'] }}</td><td>{{ i['confirmed_qty'] or '-' }}</td><td>{{ rupiah(i['price']) }}</td><td><b>{{ rupiah(i['supplier_price'] or i['price']) }}</b></td><td style="font-weight:700;color:{{ '#ef4444' if (i['supplier_price_diff'] or 0) > 0 else '#10b981' if (i['supplier_price_diff'] or 0) < 0 else '#64748b' }}">{{ rupiah(i['supplier_price_diff'] or 0) }}</td><td><span class="badge {{ 'badge-success' if i['supplier_status']=='ACCEPTED' else ('badge-danger' if i['supplier_status']=='REJECTED' else 'badge-warn') }}">{{ i['supplier_status'] or 'PENDING' }}</span></td><td>{{ i['supplier_note'] or '-' }}</td><td>{{ rupiah(i['supplier_subtotal'] or i['subtotal']) }}</td><td>{% if po_edit['status']=='DRAFT' %}<form method="post" style="display:inline;"><input type="hidden" name="action" value="delete_item"><input type="hidden" name="po_id" value="{{ po_edit['id'] }}"><input type="hidden" name="item_id" value="{{ i['id'] }}"><button class="btn-sm btn-danger" data-confirm="Hapus item PO ini?">Hapus</button></form>{% endif %}</td></tr>{% else %}<tr><td colspan="10" class="muted text-center">Belum ada item.</td></tr>{% endfor %}</tbody></table></div>
    </div>
    {% endif %}
    <script>
    function fillPoPrice(sel,target){var opt=sel.options[sel.selectedIndex];var price=opt?(opt.getAttribute('data-price')||''):'';var input=(typeof target==='string')?document.getElementById(target):target;if(input&&(!input.value||Number(input.value)===0))input.value=price;}
    function addPoRow(){var tbody=document.querySelector('#poBulkTable tbody');if(!tbody)return;var first=tbody.querySelector('tr');var clone=first.cloneNode(true);clone.querySelectorAll('input').forEach(function(i){i.value=''});clone.querySelectorAll('select').forEach(function(s){s.selectedIndex=0});tbody.appendChild(clone);}
    function removePoRow(btn){var rows=document.querySelectorAll('#poBulkTable tbody tr');if(rows.length>1)btn.closest('tr').remove();}
    </script>
    ''', suppliers_rows=suppliers_rows, products_rows=products_rows, rows=rows, po_edit=po_edit, po_items=po_items, today=today_str(), rupiah=rupiah)
    return render_page('Purchase Order', body)

