@app.route('/purchase-order-history')
@login_required
@role_required('admin', 'supplier')
def purchase_order_history():
    user = current_user()
    role = user['role']
    supplier_user_id = user['supplier_id'] if 'supplier_id' in user.keys() else None
    q = request.args.get('q', '').strip()
    status = request.args.get('status', '').strip()
    start_date = request.args.get('start', '').strip()
    end_date = request.args.get('end', '').strip()
    supplier_filter = request.args.get('supplier_id', '').strip()
    po_id = request.args.get('po_id', '').strip()

    where = ['1=1']
    params = []
    if role == 'supplier':
        where.append('po.supplier_id=?')
        params.append(supplier_user_id or 0)
    elif supplier_filter:
        where.append('po.supplier_id=?')
        params.append(int(supplier_filter))
    if status:
        where.append('po.status=?')
        params.append(status)
    if start_date:
        where.append('po.po_date>=?')
        params.append(start_date)
    if end_date:
        where.append('po.po_date<=?')
        params.append(end_date)
    if q:
        where.append('(po.po_no LIKE ? OR s.name LIKE ? OR po.note LIKE ? OR po.supplier_reference LIKE ?)')
        params += [f'%{q}%', f'%{q}%', f'%{q}%', f'%{q}%']
    where_sql = ' AND '.join(where)

    rows = q_all(f'''
        SELECT po.*, s.name AS supplier_name, s.supplier_code,
               u.full_name AS created_name, u.username AS created_username,
               COALESCE((SELECT COUNT(*) FROM purchase_items pi WHERE pi.po_id=po.id),0) AS item_count,
               COALESCE((SELECT COUNT(*) FROM purchase_items pi WHERE pi.po_id=po.id AND ABS(COALESCE(pi.supplier_price_diff,0))>=0.01),0) AS price_change_items,
               COALESCE((SELECT COUNT(*) FROM supplier_po_feedback f WHERE f.po_id=po.id),0) AS feedback_count
        FROM purchase_orders po
        LEFT JOIN suppliers s ON s.id=po.supplier_id
        LEFT JOIN users u ON u.id=po.created_by
        WHERE {where_sql}
        ORDER BY po.id DESC
        LIMIT 300
    ''', params)

    total_po = len(rows)
    total_value = sum(float(r['supplier_total'] or r['total'] or 0) for r in rows)
    changed_count = sum(1 for r in rows if int(r['has_price_change'] or 0) == 1 or int(r['price_change_items'] or 0) > 0)
    open_count = sum(1 for r in rows if r['status'] in ('DRAFT','SENT','PARTIAL','CONFIRMED'))
    suppliers_rows = q_all('SELECT id, supplier_code, name FROM suppliers WHERE is_active=1 ORDER BY name') if role == 'admin' else []

    po_edit = None; items = []; feedbacks = []; audits = []; stocks = []
    if po_id:
        detail_sql = 'SELECT po.*, s.name AS supplier_name, s.supplier_code, u.full_name AS created_name, u.username AS created_username FROM purchase_orders po LEFT JOIN suppliers s ON s.id=po.supplier_id LEFT JOIN users u ON u.id=po.created_by WHERE po.id=?'
        detail_params = [int(po_id)]
        if role == 'supplier':
            detail_sql += ' AND po.supplier_id=?'
            detail_params.append(supplier_user_id or 0)
        po_edit = q_one(detail_sql, detail_params)
        if po_edit:
            items = q_all('''
                SELECT pi.*, p.barcode, p.product_name, p.category, p.unit
                FROM purchase_items pi
                LEFT JOIN products p ON p.id=pi.product_id
                WHERE pi.po_id=? ORDER BY pi.id ASC
            ''', [po_edit['id']])
            feedbacks = q_all('SELECT f.*, u.full_name, u.username FROM supplier_po_feedback f LEFT JOIN users u ON u.id=f.created_by WHERE f.po_id=? ORDER BY f.id DESC', [po_edit['id']])
            audits = q_all('SELECT * FROM audit_logs WHERE entity="purchase_orders" AND entity_id=? ORDER BY id DESC LIMIT 100', [str(po_edit['id'])])
            stocks = q_all('SELECT * FROM stock_history WHERE reference_type="purchase_orders" AND reference_id=? ORDER BY id DESC LIMIT 100', [po_edit['id']])

    body = render_template_string("""
    <div class="po-audit-page">
      <section class="po-audit-hero">
        <div class="po-audit-hero__copy">
          <span class="po-eyebrow">PURCHASE ORDER AUDIT</span>
          <h2>History Purchase Order</h2>
          <p>Panel audit untuk melihat alur order dari dibuat, dikirim ke supplier, feedback harga/qty, sampai penerimaan stok.</p>
        </div>
        <form method="get" class="po-audit-filter">
          <label><span>Cari</span><input name="q" value="{{ q }}" placeholder="PO / supplier / ref..."></label>
          <label><span>Status</span><select name="status"><option value="">Semua</option>{% for st in ['DRAFT','SENT','PARTIAL','CONFIRMED','REJECTED','RECEIVED'] %}<option value="{{ st }}" {% if status==st %}selected{% endif %}>{{ st }}</option>{% endfor %}</select></label>
          {% if role == 'admin' %}<label><span>Supplier</span><select name="supplier_id"><option value="">Semua Supplier</option>{% for s in suppliers_rows %}<option value="{{ s.id }}" {% if supplier_filter|string==s.id|string %}selected{% endif %}>{{ s.supplier_code }} - {{ s.name }}</option>{% endfor %}</select></label>{% endif %}
          <label><span>Dari</span><input type="date" name="start" value="{{ start_date }}"></label>
          <label><span>Sampai</span><input type="date" name="end" value="{{ end_date }}"></label>
          <div class="po-filter-actions"><button type="submit">Filter</button><a href="{{ url_for('purchase_order_history') }}" class="btn btn-ghost">Reset</a></div>
        </form>
      </section>

      <section class="po-audit-kpis">
        <article><span>Total PO</span><b>{{ total_po }}</b><small>berdasarkan filter aktif</small></article>
        <article><span>PO Aktif</span><b>{{ open_count }}</b><small>DRAFT / SENT / PARTIAL / CONFIRMED</small></article>
        <article class="danger"><span>Perubahan Harga</span><b>{{ changed_count }}</b><small>perlu review admin</small></article>
        <article><span>Nilai Supplier</span><b>{{ rupiah(total_value) }}</b><small>supplier_total / total PO</small></article>
      </section>

      <section class="po-audit-layout">
        <div class="po-audit-list card">
          <div class="po-card-head"><div><span>ORDER LIST</span><h3>Daftar Order</h3></div><small>{{ rows|length }} data ditampilkan</small></div>
          <div class="po-order-list">
            {% for r in rows %}
            {% set diff = (r.supplier_total or r.total or 0) - (r.total or 0) %}
            <article class="po-order-card {{ 'is-active' if po_edit and po_edit.id == r.id else '' }}">
              <div class="po-order-main">
                <a class="po-number" href="{{ url_for('purchase_order_history', po_id=r.id, q=q, status=status, start=start_date, end=end_date, supplier_id=supplier_filter) }}">{{ r.po_no }}</a>
                <span class="po-supplier">{{ r.supplier_name or '-' }} · {{ r.supplier_code or '-' }}</span>
                <small>{{ r.po_date or r.created_at[:10] }}{% if r.supplier_reference %} · Ref {{ r.supplier_reference }}{% endif %}</small>
              </div>
              <div class="po-order-status">
                <span class="badge {{ 'badge-success' if r.status in ['CONFIRMED','RECEIVED'] else 'badge-danger' if r.status=='REJECTED' else 'badge-warn' }}">{{ r.status }}</span>
                {% if r.has_price_change or r.price_change_items %}<span class="badge badge-danger">Harga berubah</span>{% endif %}
              </div>
              <div class="po-order-money">
                <small>Total PO</small><b>{{ rupiah(r.total or 0) }}</b>
                <small>Total Supplier</small><strong>{{ rupiah(r.supplier_total or r.total or 0) }}</strong>
              </div>
              <div class="po-order-meta">
                <span>Item <b>{{ r.item_count }}</b></span>
                <span>Feedback <b>{{ r.feedback_count }}</b></span>
                <span class="{{ 'neg' if diff>0 else 'pos' if diff<0 else '' }}">Selisih <b>{{ rupiah(diff) }}</b></span>
              </div>
            </article>
            {% else %}
            <div class="po-empty"><b>Belum ada history order</b><small>Ubah filter atau buat PO terlebih dahulu.</small></div>
            {% endfor %}
          </div>
        </div>

        <div class="po-audit-detail card">
          {% if po_edit %}
          <div class="po-detail-top">
            <div><span>DETAIL AUDIT</span><h3>{{ po_edit.po_no }}</h3><p>Supplier: {{ po_edit.supplier_name or '-' }} · Dibuat oleh: {{ po_edit.created_name or po_edit.created_username or '-' }}</p></div>
            <span class="badge badge-info">{{ po_edit.status }}</span>
          </div>
          <div class="po-info-grid">
            <div><small>ETA</small><b>{{ po_edit.supplier_eta or '-' }}</b></div>
            <div><small>Ref / Invoice</small><b>{{ po_edit.supplier_reference or '-' }}</b></div>
            <div><small>Catatan Kirim</small><b>{{ po_edit.supplier_delivery_note or '-' }}</b></div>
            <div><small>Perubahan Harga</small><b>{{ 'Ya' if po_edit.has_price_change else 'Tidak' }}</b></div>
          </div>

          <section class="po-detail-section">
            <h4>Item & Harga Supplier</h4>
            <div class="po-items-list">
              {% for i in items %}
              <article>
                <div class="po-item-name"><b>{{ i.barcode }} - {{ i.product_name }}</b><small>{{ i.category or '-' }} · {{ i.unit or '-' }}</small></div>
                <div><small>Qty PO</small><b>{{ i.qty }}</b></div>
                <div><small>Qty OK</small><b>{{ i.confirmed_qty or '-' }}</b></div>
                <div><small>Harga PO</small><b>{{ rupiah(i.price or 0) }}</b></div>
                <div><small>Harga Supplier</small><b>{{ rupiah(i.supplier_price or i.price or 0) }}</b></div>
                <div class="{{ 'neg' if (i.supplier_price_diff or 0)>0 else 'pos' if (i.supplier_price_diff or 0)<0 else '' }}"><small>Selisih</small><b>{{ rupiah(i.supplier_price_diff or 0) }}</b></div>
                <div><span class="badge {{ 'badge-success' if i.supplier_status=='ACCEPTED' else 'badge-danger' if i.supplier_status=='REJECTED' else 'badge-warn' }}">{{ i.supplier_status or 'PENDING' }}</span></div>
                <p>{{ i.supplier_note or '-' }}</p>
              </article>
              {% else %}<div class="po-empty"><b>Tidak ada item</b></div>{% endfor %}
            </div>
          </section>

          <section class="po-detail-section">
            <h4>Feedback Supplier</h4>
            <div class="po-timeline">
              {% for f in feedbacks %}<article><i></i><div><small>{{ f.created_at }} · {{ f.full_name or f.username or '-' }}</small><p>{{ f.message }}</p></div></article>{% else %}<div class="po-empty small"><b>Belum ada feedback umum</b></div>{% endfor %}
            </div>
          </section>

          <section class="po-detail-section">
            <h4>Audit Log PO</h4>
            <div class="po-compact-table"><table><thead><tr><th>Waktu</th><th>User</th><th>Aksi</th><th>Detail</th></tr></thead><tbody>{% for a in audits %}<tr><td>{{ a.log_time }}</td><td>{{ a.username }}</td><td>{{ a.action }}</td><td>{{ a.detail }}</td></tr>{% else %}<tr><td colspan="4">Tidak ada audit log.</td></tr>{% endfor %}</tbody></table></div>
          </section>

          <section class="po-detail-section">
            <h4>Riwayat Stok dari PO</h4>
            <div class="po-compact-table"><table><thead><tr><th>Waktu</th><th>Barang</th><th>Qty</th><th>Tipe</th><th>Catatan</th></tr></thead><tbody>{% for st in stocks %}<tr><td>{{ st.created_at }}</td><td>{{ st.product_name }}</td><td>{{ st.qty }}</td><td>{{ st.movement_type }}</td><td>{{ st.note or '-' }}</td></tr>{% else %}<tr><td colspan="5">Belum ada penerimaan stok.</td></tr>{% endfor %}</tbody></table></div>
          </section>
          {% else %}
          <div class="po-detail-empty"><i>H</i><h3>Pilih PO</h3><p>Klik nomor PO di daftar order untuk melihat detail audit lengkap.</p></div>
          {% endif %}
        </div>
      </section>
    </div>
    """, rows=rows, po_edit=po_edit, items=items, feedbacks=feedbacks, audits=audits, stocks=stocks, suppliers_rows=suppliers_rows, q=q, status=status, start_date=start_date, end_date=end_date, supplier_filter=supplier_filter, role=role, total_po=total_po, changed_count=changed_count, open_count=open_count, total_value=total_value, rupiah=rupiah)
    return render_page('History Order Audit', body)

def barcode_svg(code):
    if not code: return ''
    pattern = []
    for ch in code:
        bh = bin(ord(ch))[2:].zfill(8)
        pattern.extend([1 if b == '1' else 0 for b in bh])
        pattern.append(0)
    w = len(pattern) * 3
    parts = [f'<svg xmlns="http://www.w3.org/2000/svg" width="{w+20}" height="80" viewBox="0 0 {w+20} 80"><rect width="{w+20}" height="80" fill="white"/>']
    x = 10
    for bit in pattern:
        if bit == 1:
            parts.append(f'<rect x="{x}" y="5" width="2" height="55" fill="black"/>')
        x += 3
    parts.append(f'<text x="{w//2+10}" y="72" text-anchor="middle" font-size="12" font-family="monospace">{code}</text></svg>')
    return ''.join(parts)

@app.route('/barcode/<barcode>')
@login_required
@role_required('admin', 'kasir', 'branch_admin', 'branch_cashier')
def barcode_image(barcode):
    return barcode_svg(barcode), 200, {'Content-Type': 'image/svg+xml'}

@app.route('/products/barcode-labels')
@login_required
@role_required('admin', 'kasir', 'branch_admin', 'branch_cashier')
def product_barcode_labels():
    single = request.args.get('barcode', '').strip()
    if single:
        rows = q_all("SELECT barcode, product_name, sell_price FROM products WHERE active=1 AND barcode=? AND barcode IS NOT NULL AND barcode != '' ORDER BY product_name ASC", [single])
    else:
        rows = q_all("SELECT barcode, product_name, sell_price FROM products WHERE active=1 AND barcode IS NOT NULL AND barcode != '' ORDER BY product_name ASC")
    html_parts = ['''<!doctype html><html><head><meta charset="utf-8"><title>Label Barcode</title><style>body{font-family:Arial,sans-serif;padding:20px;}.lg{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px;}.lb{border:1px solid #ddd;border-radius:8px;padding:12px;text-align:center;}.lb h4{margin:4px 0;font-size:13px;}.lb .pr{font-size:14px;font-weight:700;color:#2563eb;margin-bottom:6px;}@media print{.np{display:none!important;}}</style></head><body><div class="np" style="margin-bottom:16px;"><a href="'''+url_for('products')+'''" class="btn btn-ghost">← Kembali</a> <button class="btn" onclick="window.print()">🖨️ Cetak</button></div><div class="lg">''']
    for r in rows:
        html_parts.append(f'<div class="lb"><h4>{r["product_name"]}</h4><div class="pr">{rupiah(r["sell_price"])}</div>{barcode_svg(r["barcode"])}</div>')
    html_parts.append('</div></body></html>')
    return ''.join(html_parts)

# =========================
