@app.route('/categories', methods=['GET', 'POST'])
@login_required
@role_required('admin')
def categories():
    if request.method == 'POST':
        action = request.form.get('action')
        if action == 'create':
            name = request.form.get('name', '').strip()
            desc = request.form.get('description', '').strip()
            if not name:
                flash('Nama kategori wajib diisi.', 'error')
            else:
                try:
                    exec_sql('INSERT INTO categories(name, description) VALUES (?, ?)', [name, desc])
                    flash('Kategori ditambahkan.', 'success')
                except sqlite3.IntegrityError:
                    flash('Kategori sudah ada.', 'error')
            return redirect(url_for('categories'))
        elif action == 'toggle':
            cid = int(request.form.get('cat_id'))
            c = q_one('SELECT is_active FROM categories WHERE id=?', [cid])
            exec_sql('UPDATE categories SET is_active=? WHERE id=?', [0 if c['is_active'] else 1, cid])
            flash('Status kategori diubah.', 'success')
            return redirect(url_for('categories'))
    cats = q_all('SELECT c.*, (SELECT COUNT(*) FROM products p WHERE p.category=c.name) AS product_count FROM categories c ORDER BY c.id DESC')
    body = render_template_string('''<div class="grid"><div class="col-4"><div class="card"><h2>🏷️ Tambah Kategori</h2><form method="post"><input type="hidden" name="action" value="create"><div class="form-group"><label>Nama</label><input name="name" required placeholder="Nama kategori"></div><div class="form-group"><label>Deskripsi</label><textarea name="description" style="min-height:50px;"></textarea></div><button type="submit">Simpan</button></form></div></div><div class="col-8"><div class="card"><h2>Daftar Kategori</h2><div class="table-wrap"><table><thead><tr><th>Nama</th><th>Deskripsi</th><th>Barang Terkoneksi</th><th>Status</th><th>Aksi</th></tr></thead><tbody>{% for c in cats %}<tr><td>{{ c.name }}</td><td>{{ c.description or '-' }}</td><td><a href="{{ url_for('products', q=c.name) }}" class="badge badge-info">{{ c.product_count }} barang</a></td><td><span class="badge {{ 'badge-success' if c.is_active else 'badge-gray' }}">{{ 'Aktif' if c.is_active else 'Nonaktif' }}</span></td><td><form method="post" style="margin:0;display:inline;"><input type="hidden" name="action" value="toggle"><input type="hidden" name="cat_id" value="{{ c.id }}"><button class="btn-sm btn-ghost">{{ 'Nonaktifkan' if c.is_active else 'Aktifkan' }}</button></form></td></tr>{% else %}<tr><td colspan="5" class="muted text-center">Belum ada kategori.</td></tr>{% endfor %}</tbody></table></div></div></div></div>''', cats=cats)
    return render_page('Kategori', body)

