# Fitur 1: Retur Penjualan
# =========================
@app.route('/sales-returns', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'kasir', 'branch_admin')
def sales_returns():
    if request.method == 'POST':
        sales_id = int(request.form.get('sales_id') or 0)
        reason = request.form.get('reason', '').strip()
        items_json = request.form.get('return_items', '[]')
        items = json.loads(items_json)
        sale = q_one('SELECT * FROM sales WHERE id=? AND status="Posted"', [sales_id])
        role=current_user()['role']; current_bid=get_branch_id()
        if sale and role not in ('admin','bendahara','supervisor') and ((sale['branch_id'] or None)!=(current_bid or None)): sale=None
        if not sale:
            flash('Transaksi tidak ditemukan atau sudah diproses.', 'error')
            return redirect(url_for('sales_returns'))
        if not items:
            flash('Pilih minimal 1 item untuk diretur.', 'error')
            return redirect(url_for('sales_returns'))
        total_return = 0
        ret_items = []
        for item in items:
            prod = q_one('SELECT id FROM products WHERE id=?', [item['product_id']])
            if prod:
                subtotal = float(item['qty']) * float(item['price'])
                total_return += subtotal
                ret_items.append((prod['id'], float(item['qty']), float(item['price']), subtotal))
        if total_return <= 0:
            flash('Total retur harus lebih dari 0.', 'error')
            return redirect(url_for('sales_returns'))
        ret_no = gen_code('RET')
        ret_id = exec_sql('INSERT INTO sales_returns(return_no, sales_id, member_id, return_date, total, reason, created_by) VALUES (?, ?, ?, ?, ?, ?, ?)', [ret_no, sales_id, sale['member_id'], today_str(), total_return, reason, session.get('user_id')])
        for pid, qty, price, sub in ret_items:
            exec_sql('INSERT INTO sales_return_items(return_id, product_id, qty, price, subtotal) VALUES (?, ?, ?, ?, ?)', [ret_id, pid, qty, price, sub])
            update_branch_stock(pid,qty,sale['branch_id'],'add')
            log_stock_history(pid,qty,'Retur',origin=str(sale['branch_id'] or 'PUSAT'),reference_type='sales_returns',reference_id=ret_id,note=f'Retur {ret_no}')
        if sale['member_id'] and sale['payment_method'] == 'wallet':
            saldo_sebelum = q_one('SELECT COALESCE(SUM(CASE WHEN tipe="MASUK" THEN nominal ELSE -nominal END), 0) as saldo FROM saldo_history WHERE member_id=?', [sale['member_id']])['saldo']
            saldo_setelah = saldo_sebelum + total_return
            exec_sql('INSERT INTO saldo_history(member_id, tipe, nominal, saldo_sebelum, saldo_setelah, keterangan, reference_id, created_by) VALUES (?, "MASUK", ?, ?, ?, "Retur penjualan "+?, ?, ?)', [sale['member_id'], total_return, saldo_sebelum, saldo_setelah, ret_no, ret_id, session.get('user_id')])
        log_action('CREATE', 'sales_returns', ret_id, f'Retur {ret_no} dari {sale["invoice_no"]} total {total_return}')
        flash(f'Retur berhasil. {ret_no} — Stok dikembalikan.', 'success')
        return redirect(url_for('sales_returns_list'))
    return_sql='SELECT s.*,COALESCE(m.name,s.customer_name,"Umum") pelanggan,COALESCE(b.name,"PUSAT") branch_name FROM sales s LEFT JOIN members m ON m.id=s.member_id LEFT JOIN koperasi_branches b ON b.id=s.branch_id WHERE s.status="Posted"'
    return_params=[]; scope_sql,scope_params=branch_sales_scope('s'); return_sql+=scope_sql+' ORDER BY s.id DESC LIMIT 50'; return_params+=scope_params
    sales=q_all(return_sql,return_params)
    body = render_template_string('''<div class="sales-suite returns-suite"><header class="sales-hero"><div><span>RETURN MANAGEMENT</span><h2>Retur Penjualan</h2><p>Pilih transaksi yang valid, periksa detail barang, lalu proses pengembalian stok secara terkontrol.</p></div><div class="sales-hero-chip"><small>Transaksi tersedia</small><b>{{sales|length}} transaksi</b></div></header><div class="card sales-panel"><div class="sales-panel-head"><div><span class="sales-kicker">TRANSAKSI POSTED</span><h3>Pilih Transaksi untuk Diretur</h3><p>Hanya transaksi berstatus Posted yang dapat diproses.</p></div><a href="{{url_for('sales_returns_list')}}" class="btn btn-ghost">Riwayat Retur</a></div><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Tanggal</th><th>Pelanggan</th><th>Lokasi</th><th>Total</th><th>Aksi</th></tr></thead><tbody>{% for s in sales %}<tr><td>{{ s.invoice_no }}</td><td>{{ s.trx_date }}</td><td>{{ s.pelanggan }}</td><td>{{s.branch_name}}</td><td>{{ rupiah(s.total) }}</td><td><a href="{{ url_for('sales_returns_process', sales_id=s.id) }}" class="btn btn-sm btn-warn">🔄 Retur</a></td></tr>{% else %}<tr><td colspan="6" class="muted text-center">Belum ada transaksi.</td></tr>{% endfor %}</tbody></table></div></div></div>''', sales=sales, rupiah=rupiah)
    return render_page('Retur Penjualan', body)

@app.route('/sales-returns/process/<int:sales_id>', methods=['GET', 'POST'])
@login_required
@role_required('admin','kasir','branch_admin','branch_cashier')
def sales_returns_process(sales_id):
    sale = q_one('SELECT s.*, COALESCE(m.name, s.customer_name, "Umum") as pelanggan FROM sales s LEFT JOIN members m ON m.id=s.member_id WHERE s.id=?', [sales_id])
    role=current_user()['role']; current_bid=get_branch_id()
    if not sale or (role not in ('admin','bendahara','supervisor') and ((sale['branch_id'] or None)!=(current_bid or None))):
        flash('Transaksi retur tidak ditemukan di cabang akun ini.','error'); return redirect(url_for('sales_returns'))
    if current_bid:
        items=q_all('''SELECT si.*,COALESCE(pbs.stock,0) stock FROM sales_items si LEFT JOIN product_branch_stock pbs ON pbs.product_id=si.product_id AND pbs.branch_id=? WHERE si.sales_id=?''',[current_bid,sales_id])
    else:
        items=q_all('SELECT si.*,COALESCE(p.stock,0) stock FROM sales_items si LEFT JOIN products p ON p.id=si.product_id WHERE si.sales_id=?',[sales_id])
    body = render_template_string('''<div class="sales-suite return-process-suite"><header class="sales-hero"><div><span>RETURN PROCESS</span><h2>Proses Retur</h2><p>{{sale.invoice_no}} · {{sale.pelanggan}} · {{sale.trx_date}}</p></div><a href="{{url_for('sales_returns')}}" class="btn btn-ghost">Kembali</a></header><div class="card sales-panel"><div class="sales-panel-head"><div><span class="sales-kicker">PILIH ITEM</span><h3>Barang yang Dikembalikan</h3></div></div><form method="post" action="{{url_for('sales_returns')}}" id="retForm"><input type="hidden" name="sales_id" value="{{ sale.id }}"><input type="hidden" name="return_items" id="return_items" value="[]"><div class="form-group"><label>Alasan Retur</label><textarea name="reason" style="min-height:50px;"></textarea></div><div class="table-wrap"><table><thead><tr><th><input type="checkbox" id="checkAll" onchange="toggleAll(this)"></th><th>Barang</th><th>Qty Beli</th><th>Harga</th><th>Stok Skrg</th><th>Qty Retur</th></tr></thead><tbody>{% for i in items %}<tr><td><input type="checkbox" class="ret-check" data-pid="{{ i.product_id }}" data-price="{{ i.price }}" data-max="{{ i.qty }}" data-name="{{ i.product_name }}"></td><td>{{ i.product_name }}</td><td>{{ i.qty }}</td><td>{{ rupiah(i.price) }}</td><td>{{ i.stock }}</td><td><input type="number" class="ret-qty" min="1" max="{{ i.qty }}" value="{{ i.qty }}" disabled style="width:80px;"></td></tr>{% endfor %}</tbody></table></div><button type="submit" class="btn-warn">📤 Proses Retur</button></form></div></div><script>document.getElementById('checkAll')&&document.getElementById('checkAll').addEventListener('change',function(){document.querySelectorAll('.ret-check').forEach(c=>{c.checked=this.checked;c.closest('tr').querySelector('.ret-qty').disabled=!this.checked})});function toggleAll(s){document.querySelectorAll('.ret-check').forEach(c=>{c.checked=s.checked;c.closest('tr').querySelector('.ret-qty').disabled=!s.checked})}document.getElementById('retForm').addEventListener('submit',function(e){var items=[];document.querySelectorAll('.ret-check:checked').forEach(c=>{var q=parseInt(c.closest('tr').querySelector('.ret-qty').value)||0;if(q>0)items.push({product_id:parseInt(c.dataset.pid),qty:q,price:parseFloat(c.dataset.price)})});document.getElementById('return_items').value=JSON.stringify(items)})</script>''', sale=sale, items=items, rupiah=rupiah)
    return render_page(f'Retur {sale["invoice_no"]}', body)

@app.route('/sales-returns/list')
@login_required
@role_required('admin','kasir','branch_admin','branch_cashier')
def sales_returns_list():
    user=current_user()
    bid,branch_warning=resolve_operational_branch(user)
    sql='''SELECT r.*,s.invoice_no,COALESCE(b.name,'PUSAT') branch_name FROM sales_returns r JOIN sales s ON s.id=r.sales_id LEFT JOIN koperasi_branches b ON b.id=s.branch_id WHERE 1=1'''; params=[]
    if user['role'] in ('branch_admin','branch_cashier','kasir'):
        if bid: sql+=' AND s.branch_id=?'; params.append(bid)
        else: sql+=' AND 1=0'
    rows=q_all(sql+' ORDER BY r.id DESC LIMIT 200',params)
    body = render_template_string('''<div class="sales-suite return-history-suite"><header class="sales-hero"><div><span>RETURN HISTORY</span><h2>Riwayat Retur</h2><p>Audit seluruh pengembalian barang dan nilai transaksi retur.</p></div><a href="{{url_for('sales_returns')}}" class="btn btn-ghost">Buat Retur</a></header><div class="card sales-panel"><div class="sales-panel-head"><div><span class="sales-kicker">AUDIT RETUR</span><h3>Daftar Retur</h3></div></div><div class="table-wrap"><table><thead><tr><th>No Retur</th><th>Invoice Asal</th><th>Tanggal</th><th>Lokasi</th><th>Total</th><th>Alasan</th><th>Status</th></tr></thead><tbody>{% for r in rows %}<tr><td>{{ r.return_no }}</td><td>{{ r.invoice_no }}</td><td>{{ r.return_date }}</td><td><span class="badge badge-info">{{r.branch_name}}</span></td><td>{{ rupiah(r.total) }}</td><td>{{ r.reason or '-' }}</td><td><span class="badge badge-warn">{{ r.status }}</span></td></tr>{% else %}<tr><td colspan="7" class="muted text-center">Belum ada retur.</td></tr>{% endfor %}</tbody></table></div></div></div>''', rows=rows, rupiah=rupiah)
    return render_page('Riwayat Retur', body)

# =========================
# Fitur 2: Diskon di Kasir
# =========================
@app.route('/cashier-with-discount', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'kasir', 'branch_admin', 'branch_cashier')
def cashier_discount():
    user=current_user()
    bid,branch_warning=resolve_operational_branch(user)
    branch_key=str(bid) if bid else 'UNASSIGNED-DISCOUNT'
    if session.get('discount_cart_branch')!=branch_key: save_cart([]); session['discount_cart_branch']=branch_key
    cart = get_cart()
    if request.method == 'POST':
        if user['role'] in ('branch_admin','branch_cashier','kasir') and not bid:
            flash('Transaksi diblokir karena cabang akun belum dikonfigurasi.','error'); return redirect(url_for('cashier_discount'))
        action = request.form.get('action')
        if action == 'add_item':
            barcode = request.form.get('barcode', '').strip()
            qty = parse_float(request.form.get('qty', 1) or 1)
            prod=q_one('''SELECT p.id,p.barcode,p.product_name,p.sell_price,COALESCE(bs.stock,0) stock FROM products p LEFT JOIN product_branch_stock bs ON bs.product_id=p.id AND bs.branch_id=? WHERE p.barcode=? AND p.active=1''',[bid,barcode]) if bid else q_one('SELECT id,barcode,product_name,sell_price,COALESCE(stock,0) stock FROM products WHERE barcode=? AND active=1',[barcode])
            if not barcode:
                flash('Barcode wajib diisi / discan.', 'warning')
            elif not prod:
                flash('Barang tidak ditemukan.', 'error')
            elif float(prod['stock']) < qty:
                flash('Stok tidak mencukupi.', 'error')
            else:
                found = False
                for item in cart:
                    if item['product_id'] == int(prod['id']):
                        item['qty'] += qty; item['subtotal'] = item['qty'] * item['price']
                        found = True; break
                if not found:
                    cart.append({'product_id': int(prod['id']), 'barcode': prod['barcode'], 'product_name': prod['product_name'], 'qty': qty, 'price': float(prod['sell_price']), 'subtotal': qty * float(prod['sell_price']), 'discount': 0, 'discount_type': '%'})
                save_cart(cart)
                flash(f"{prod['product_name']} masuk keranjang.", 'success')
            return redirect(url_for('cashier_discount'))
        elif action == 'set_discount':
            idx = int(request.form.get('item_idx', 0))
            disc_val = parse_float(request.form.get('discount_value', 0) or 0)
            disc_type = request.form.get('discount_type', '%')
            if 0 <= idx < len(cart):
                cart[idx]['discount'] = disc_val
                cart[idx]['discount_type'] = disc_type
                item = cart[idx]
                base = item['qty'] * item['price']
                if disc_type == '%':
                    item['discount_amount'] = base * disc_val / 100
                else:
                    item['discount_amount'] = disc_val
                item['subtotal'] = max(0, base - item['discount_amount'])
                save_cart(cart)
                flash('Diskon diterapkan.', 'success')
            return redirect(url_for('cashier_discount'))
        elif action == 'clear':
            save_cart([]); flash('Keranjang dikosongkan.', 'warning')
            return redirect(url_for('cashier_discount'))
        elif action == 'save_sale':
            if not cart:
                flash('Keranjang kosong.', 'error')
                return redirect(url_for('cashier_discount'))
            total = sum(float(i.get('subtotal', i['qty'] * i['price'])) for i in cart)
            global_disc = parse_float(request.form.get('global_discount', 0) or 0)
            global_disc_type = request.form.get('global_disc_type', '%')
            if global_disc_type == '%':
                global_disc_amount = total * global_disc / 100
            else:
                global_disc_amount = global_disc
            final_total = max(0, total - global_disc_amount)
            member_id = request.form.get('member_id') or None
            customer_name = request.form.get('customer_name', '').strip()
            paid = parse_float(request.form.get('paid', 0) or 0)
            note = request.form.get('note', '').strip()
            payment_method = request.form.get('payment_method', 'tunai')
            invoice = gen_code('INV')
            change_amount = 0
            if payment_method == 'tunai':
                if paid < final_total:
                    flash('Nominal bayar kurang dari total.', 'error')
                    return redirect(url_for('cashier_discount'))
                change_amount = paid - final_total
            elif payment_method == 'wallet':
                if not member_id:
                    flash('Bayar wallet wajib pilih member.', 'error')
                    return redirect(url_for('cashier_discount'))
                member_saldo = q_one('SELECT COALESCE(SUM(CASE WHEN tipe="MASUK" THEN nominal ELSE -nominal END), 0) as saldo FROM saldo_history WHERE member_id=?', [member_id])['saldo']
                if member_saldo < final_total:
                    flash(f'Saldo wallet tidak cukup. Saldo {rupiah(member_saldo)}', 'error')
                    return redirect(url_for('cashier_discount'))
                saldo_sebelum = member_saldo
                saldo_setelah = saldo_sebelum - final_total
                exec_sql('INSERT INTO saldo_history(member_id, tipe, nominal, saldo_sebelum, saldo_setelah, keterangan, reference_id, created_by) VALUES (?, "KELUAR", ?, ?, ?, "Bayar kasir diskon", ?, ?)', [member_id, final_total, saldo_sebelum, saldo_setelah, 0, session.get('user_id')])
                paid = final_total
            else:
                paid = final_total
            disc_note = ''
            if global_disc_amount > 0:
                disc_note = f'Diskon {global_disc}{"" if global_disc_type==chr(37) else "Rp"}={rupiah(global_disc_amount)}'
            for item in cart:
                if get_product_stock(item['product_id'],bid)<float(item['qty']):
                    flash(f"Stok {item['product_name']} di {get_branch_name(bid)} tidak cukup.",'error'); return redirect(url_for('cashier_discount'))
            sid=exec_sql('INSERT INTO sales(invoice_no,trx_date,member_id,cashier_id,customer_name,total,paid,change_amount,note,status,payment_method,branch_id) VALUES(?,?,?,?,?,?,?,?,?,"Posted",?,?)',[invoice,today_str(),member_id,cashier_operator_id(),customer_name,final_total,paid,change_amount,note+' '+disc_note,payment_method,bid])
            exec_sql('UPDATE sales SET cashier_session_id=? WHERE id=?',[cashier_operator_session_id(),sid])
            for item in cart:
                exec_sql('INSERT INTO sales_items(sales_id, product_id, barcode, product_name, qty, price, subtotal) VALUES (?, ?, ?, ?, ?, ?, ?)', [sid, item['product_id'], item['barcode'], item['product_name'], item['qty'], item['price'], item.get('subtotal', item['qty'] * item['price'])])
                update_branch_stock(item['product_id'],item['qty'],bid,'subtract')
                log_stock_history(item['product_id'], item['qty'], 'Penjualan', reference_type='sales', reference_id=sid, origin=str(bid or 'PUSAT'),note=f'Invoice {invoice}; {get_branch_name(bid)}')
            log_action('CREATE', 'sales', sid, f'Transaksi diskon {invoice} total {final_total}')
            save_cart([])
            flash(f'Transaksi tersimpan. Invoice {invoice}. Total {rupiah(final_total)}. Kembalian {rupiah(change_amount)}', 'success')
            return redirect(url_for('cashier_discount'))
    for i, item in enumerate(cart):
        if 'discount' not in item:
            item['discount'] = 0
            item['discount_type'] = '%'
            item['discount_amount'] = 0
        if 'discount_amount' not in item:
            item['discount_amount'] = 0
    members_rows = q_all("SELECT id, member_code, name FROM members WHERE status='Aktif' ORDER BY name ASC")
    total = sum(float(i.get('subtotal', i['qty'] * i['price'])) for i in cart)
    body = render_template_string('''<div class="grid"><div class="col-4"><div class="card"><h2>🧾 Kasir + Diskon</h2><hr><form method="post"><input type="hidden" name="action" value="add_item"><div class="form-group"><label>Barcode</label><input name="barcode" placeholder="Scan barcode..." autofocus></div><div class="form-group"><label>Qty</label><input type="number" name="qty" value="1"></div><button type="submit">Tambah Produk Kredit</button></form><hr><h3>Total: <strong>{{ rupiah(total) }}</strong></h3><form method="post"><input type="hidden" name="action" value="save_sale"><div class="form-group"><label>Member</label><select name="member_id"><option value="">Umum</option>{% for m in members_rows %}<option value="{{ m['id'] }}">{{ m['member_code'] }} — {{ m['name'] }}</option>{% endfor %}</select></div><div class="form-group"><label>Nama Pelanggan</label><input name="customer_name" placeholder="(opsional)"></div><div class="form-group"><label>🛒 Diskon Global</label><div style="display:flex;gap:8px;"><input type="number" name="global_discount" value="0" style="width:100px;"><select name="global_disc_type" style="width:60px;"><option value="%">% </option><option value="rp">Rp</option></select></div></div><div class="form-group"><label>Pilih Metode Pembayaran</label><select name="payment_method"><option value="tunai">💰 Tunai</option><option value="wallet">💳 Wallet</option></select></div><div class="form-group"><label>Bayar</label><input type="number" name="paid" value="{{ total }}"></div><div class="form-group"><label>Catatan</label><textarea name="note" style="min-height:40px;"></textarea></div><button type="submit" class="btn-success">💾 Simpan Transaksi</button></form><form method="post" style="margin-top:8px;"><input type="hidden" name="action" value="clear"><button class="btn-ghost btn-danger" type="submit">🗑️ Kosongkan</button></form></div></div><div class="col-8"><div class="card"><h2>Keranjang</h2><div class="table-wrap"><table><thead><tr><th>Barang</th><th>Qty</th><th>Harga</th><th>Diskon</th><th>Subtotal</th><th>Aksi</th></tr></thead><tbody>{% for i in cart %}<tr><td>{{ i['product_name'] }}</td><td>{{ i['qty'] }}</td><td>{{ rupiah(i['price']) }}</td><td>{% if i.get('discount_amount',0) > 0 %}<span style="color:#ef4444;">-{{ rupiah(i['discount_amount']) }}</span>{% else %}-{% endif %}</td><td>{{ rupiah(i.get('subtotal', i['qty']*i['price'])) }}</td><td><form method="post" style="display:flex;gap:4px;"><input type="hidden" name="action" value="set_discount"><input type="hidden" name="item_idx" value="{{ loop.index0 }}"><input type="number" name="discount_value" placeholder="Diskon" style="width:70px;"><select name="discount_type" style="width:50px;"><option value="%">%</option><option value="rp">Rp</option></select><button class="btn-sm btn-warn" type="submit">💾</button></form></td></tr>{% else %}<tr><td colspan="6" class="muted text-center">Keranjang kosong.</td></tr>{% endfor %}</tbody></table></div></div></div></div>''', cart=cart, total=total, members_rows=members_rows, rupiah=rupiah)
    return render_page('Kasir + Diskon', cashier_operator_banner()+body)

# =========================
# Fitur 4: Import Member dari Excel
# =========================
@app.route('/members/import', methods=['GET', 'POST'])
@login_required
@role_required('admin')
def import_members():
    if request.method == 'POST':
        file = request.files.get('file')
        if not file or not file.filename.endswith(('.xlsx', '.xls')):
            flash('Upload file Excel (.xlsx/.xls).', 'error')
            return redirect(url_for('import_members'))
        df = pd.read_excel(file)
        count = 0
        errors = []
        for _, row in df.iterrows():
            code = str(row.get('member_code', '')).strip() or gen_code('MBR')
            name = str(row.get('name', '')).strip()
            phone = str(row.get('phone', '')).strip()
            address = str(row.get('address', '')).strip()
            if not name:
                errors.append(f'Baris {count+2}: nama kosong')
                continue
            try:
                exec_sql('INSERT INTO members(member_code, name, phone, address, join_date, status) VALUES (?, ?, ?, ?, ?, ?)', [code, name, phone, address, today_str(), 'Aktif'])
                count += 1
            except sqlite3.IntegrityError:
                errors.append(f'Baris {count+2}: kode {code} sudah ada')
        flash(f'{count} member berhasil diimpor. {len(errors)} error.', 'success' if count > 0 else 'error')
        if errors:
            for e in errors[:5]:
                flash(e, 'warning')
        return redirect(url_for('members'))
    template_path = 'imports/member_template.xlsx'
    return render_page('Import Member', render_template_string('''<div class="grid"><div class="col-6"><div class="card"><h2>📥 Import Member dari Excel</h2><p class="muted small">Format kolom: member_code, name, phone, address</p><form method="post" enctype="multipart/form-data"><div class="form-group"><label>File Excel</label><input type="file" name="file" accept=".xlsx,.xls" required></div><button type="submit">📤 Upload & Import</button></form></div></div><div class="col-6"><div class="card"><h2>📄 Template</h2><p class="muted small">Download template kosong lalu isi data member</p><a href="data:text/csv;base64,bWVtYmVyX2NvZGUsbmFtZSxwaG9uZSxhZGRyZXNzCk1CUi0wMDIsTmFtYSBEaXNpbmksMDgxMjM0NTY3ODkwLkFsbGFtYXQgRGVtbw==" download="member_template.csv" class="btn">📥 Download Template CSV</a></div></div></div>'''))


@app.route('/supplier-portal', methods=['GET', 'POST'])
@login_required
@role_required('supplier')
def supplier_portal():
    user = current_user()
    supplier_id = user['supplier_id'] if 'supplier_id' in user.keys() else None
    if not supplier_id:
        flash('Akun supplier belum terhubung ke data supplier. Hubungi admin.', 'error')
        return render_page('Portal Supplier', '<div class="card"><h2>Akun belum terhubung</h2></div>')
    if request.method == 'POST':
        action = request.form.get('action')
        po_id = int(request.form.get('po_id') or 0)
        po = q_one('SELECT * FROM purchase_orders WHERE id=? AND supplier_id=? AND status IN ("DRAFT","SENT","CONFIRMED","PARTIAL")', [po_id, supplier_id])
        if not po:
            flash('PO tidak ditemukan atau sudah tidak bisa diberi feedback.', 'error')
            return redirect(url_for('supplier_portal'))
        if action == 'respond_po':
            item_ids = request.form.getlist('item_id[]')
            statuses = request.form.getlist('supplier_status[]')
            qtys = request.form.getlist('confirmed_qty[]')
            supplier_prices = request.form.getlist('supplier_price[]')
            notes = request.form.getlist('supplier_note[]')
            supplier_eta = request.form.get('supplier_eta', '').strip()
            supplier_reference = request.form.get('supplier_reference', '').strip()
            supplier_delivery_note = request.form.get('supplier_delivery_note', '').strip()
            price_changes = []
            for idx, iid_raw in enumerate(item_ids):
                iid = int(iid_raw or 0)
                st = (statuses[idx] if idx < len(statuses) else 'PENDING').upper()
                qty_ok = parse_float(qtys[idx] if idx < len(qtys) else 0)
                note = notes[idx] if idx < len(notes) else ''
                supplier_price = parse_float(supplier_prices[idx] if idx < len(supplier_prices) else 0)
                item = q_one('SELECT * FROM purchase_items WHERE id=? AND po_id=?', [iid, po_id])
                if not item:
                    continue
                base_price = float(item['price'] or 0)
                if supplier_price <= 0:
                    supplier_price = base_price
                if st == 'ACCEPTED':
                    qty_ok = float(item['qty'] or 0)
                elif st == 'PARTIAL':
                    qty_ok = max(0, min(qty_ok, float(item['qty'] or 0)))
                elif st == 'REJECTED':
                    qty_ok = 0
                else:
                    st = 'PENDING'
                price_diff = supplier_price - float(item['price'] or 0)
                supplier_subtotal = qty_ok * supplier_price if st != 'REJECTED' else 0
                if abs(price_diff) >= 0.01 and st != 'REJECTED':
                    prod_name = q_one('SELECT product_name, barcode FROM products WHERE id=?', [item['product_id']])
                    label = (prod_name['barcode'] + ' - ' + prod_name['product_name']) if prod_name else f'Produk #{item["product_id"]}'
                    price_changes.append(f'{label}: {rupiah(item["price"])} -> {rupiah(supplier_price)} (selisih {rupiah(price_diff)})')
                exec_sql('UPDATE purchase_items SET supplier_status=?, confirmed_qty=?, supplier_note=?, supplier_price=?, supplier_price_diff=?, supplier_subtotal=? WHERE id=?', [st, qty_ok, note, supplier_price, price_diff, supplier_subtotal, iid])
            total_items = q_one('SELECT COUNT(*) n FROM purchase_items WHERE po_id=?', [po_id])['n'] or 0
            rejected_items = q_one('SELECT COUNT(*) n FROM purchase_items WHERE po_id=? AND supplier_status="REJECTED"', [po_id])['n'] or 0
            pending_items = q_one('SELECT COUNT(*) n FROM purchase_items WHERE po_id=? AND COALESCE(supplier_status,"PENDING")="PENDING"', [po_id])['n'] or 0
            partial_items = q_one('SELECT COUNT(*) n FROM purchase_items WHERE po_id=? AND supplier_status="PARTIAL"', [po_id])['n'] or 0
            if rejected_items == total_items:
                new_status = 'REJECTED'
            elif pending_items == 0 and partial_items == 0 and rejected_items == 0:
                new_status = 'CONFIRMED'
            else:
                new_status = 'PARTIAL'
            msg = request.form.get('message','').strip()
            if msg:
                exec_sql('INSERT INTO supplier_po_feedback(po_id, supplier_id, message, created_by) VALUES (?, ?, ?, ?)', [po_id, supplier_id, msg, user['id']])
            supplier_total = q_one('SELECT COALESCE(SUM(supplier_subtotal),0) n FROM purchase_items WHERE po_id=? AND supplier_status != "REJECTED"', [po_id])['n'] or 0
            has_price_change = 1 if price_changes else 0
            exec_sql('UPDATE purchase_orders SET status=?, supplier_feedback_at=?, supplier_total=?, supplier_eta=?, supplier_reference=?, supplier_delivery_note=?, has_price_change=? WHERE id=?', [new_status, now_str(), supplier_total, supplier_eta, supplier_reference, supplier_delivery_note, has_price_change, po_id])
            # Notifikasi ke pengorder dan admin saat ada perubahan harga / feedback supplier.
            po_info = q_one('SELECT po_no, created_by FROM purchase_orders WHERE id=?', [po_id])
            notif_users = set()
            if po_info and po_info['created_by']:
                notif_users.add(po_info['created_by'])
            for admin_user in q_all("SELECT id FROM users WHERE active=1 AND role IN ('admin','branch_admin')"):
                notif_users.add(admin_user['id'])
            if price_changes:
                detail = '; '.join(price_changes[:5])
                if len(price_changes) > 5:
                    detail += f'; +{len(price_changes)-5} item lain'
                for uid in notif_users:
                    add_notification(uid, 'Perubahan Harga Supplier', f'{po_info["po_no"] if po_info else "PO"}: {detail}')
            else:
                for uid in notif_users:
                    add_notification(uid, 'Feedback Supplier Masuk', f'{po_info["po_no"] if po_info else "PO"}: supplier mengirim feedback status {new_status}.')
            log_action('SUPPLIER_FEEDBACK', 'purchase_orders', po_id, f'Supplier feedback status {new_status}; price_change={has_price_change}')
            flash('Feedback PO berhasil dikirim ke admin.', 'success')
            return redirect(url_for('supplier_portal', po_id=po_id))
    po_id = request.args.get('po_id','')
    rows = q_all('SELECT * FROM purchase_orders WHERE supplier_id=? AND status IN ("DRAFT","SENT","CONFIRMED","PARTIAL","REJECTED","RECEIVED") ORDER BY id DESC LIMIT 100', [supplier_id])
    po_edit = q_one('SELECT * FROM purchase_orders WHERE id=? AND supplier_id=?', [po_id, supplier_id]) if po_id else (rows[0] if rows else None)
    items = q_all('SELECT pi.*, p.barcode, p.product_name FROM purchase_items pi LEFT JOIN products p ON p.id=pi.product_id WHERE pi.po_id=? ORDER BY pi.id ASC', [po_edit['id']]) if po_edit else []
    feedbacks = q_all('SELECT * FROM supplier_po_feedback WHERE po_id=? ORDER BY id DESC', [po_edit['id']]) if po_edit else []
    pending_count = q_one('SELECT COUNT(*) n FROM purchase_orders WHERE supplier_id=? AND status IN ("DRAFT","SENT")', [supplier_id])['n'] or 0
    confirmed_count = q_one('SELECT COUNT(*) n FROM purchase_orders WHERE supplier_id=? AND status IN ("CONFIRMED","RECEIVED")', [supplier_id])['n'] or 0
    price_change_count = q_one('SELECT COUNT(*) n FROM purchase_orders WHERE supplier_id=? AND has_price_change=1 AND status != "RECEIVED"', [supplier_id])['n'] or 0
    total_open_value = q_one('SELECT COALESCE(SUM(CASE WHEN supplier_total>0 THEN supplier_total ELSE total END),0) n FROM purchase_orders WHERE supplier_id=? AND status IN ("DRAFT","SENT","PARTIAL","CONFIRMED")', [supplier_id])['n'] or 0
    body = render_template_string("""
    <div class="metrics">
      <div class="metric"><div class="label">PO Menunggu</div><div class="value">{{ pending_count }}</div><div class="sub">DRAFT / SENT</div></div>
      <div class="metric"><div class="label">Siap / Selesai</div><div class="value">{{ confirmed_count }}</div><div class="sub">CONFIRMED / RECEIVED</div></div>
      <div class="metric"><div class="label">Perubahan Harga</div><div class="value" style="color:#ef4444;">{{ price_change_count }}</div><div class="sub">Belum diterima admin</div></div>
      <div class="metric"><div class="label">Nilai PO Aktif</div><div class="value">{{ rupiah(total_open_value) }}</div><div class="sub">harga supplier jika ada</div></div>
    </div>
    <div class="grid">
      <div class="col-4"><div class="card"><h2>PO Masuk</h2><div class="table-wrap"><table><thead><tr><th>PO</th><th>Tanggal</th><th>Status</th><th>Total Supplier</th></tr></thead><tbody>{% for r in rows %}<tr><td><a href="{{ url_for('supplier_portal', po_id=r.id) }}"><b>{{ r.po_no }}</b></a></td><td>{{ r.po_date }}</td><td><span class="badge badge-info">{{ r.status }}</span>{% if r.has_price_change %}<br><span class="badge badge-danger">Harga berubah</span>{% endif %}</td><td>{{ rupiah(r.supplier_total or r.total) }}</td></tr>{% else %}<tr><td colspan="4" class="muted text-center">Belum ada PO dikirim.</td></tr>{% endfor %}</tbody></table></div></div></div>
      <div class="col-8"><div class="card">{% if po_edit %}<div class="kartu"><div><h2>{{ po_edit.po_no }}</h2><div class="muted small">Status: <b>{{ po_edit.status }}</b> | Tanggal: {{ po_edit.po_date }} | Total Supplier: <b>{{ rupiah(po_edit.supplier_total or po_edit.total) }}</b>{% if po_edit.has_price_change %} <span class="badge badge-danger">Ada perubahan harga</span>{% endif %}</div></div></div>
      {% if po_edit.status in ['DRAFT','SENT','CONFIRMED','PARTIAL'] %}<form method="post"><input type="hidden" name="action" value="respond_po"><input type="hidden" name="po_id" value="{{ po_edit.id }}"><div class="table-wrap"><table><thead><tr><th>Barang</th><th>Qty Pesan</th><th>Status</th><th>Qty OK</th><th>Harga Supplier</th><th>Selisih</th><th>Catatan</th></tr></thead><tbody>{% for i in items %}<tr><td>{{ i.barcode }} - {{ i.product_name }}</td><td>{{ i.qty }}</td><td><input type="hidden" name="item_id[]" value="{{ i.id }}"><select name="supplier_status[]"><option value="ACCEPTED" {% if i.supplier_status=='ACCEPTED' %}selected{% endif %}>Tersedia / Terima</option><option value="PARTIAL" {% if i.supplier_status=='PARTIAL' %}selected{% endif %}>Sebagian</option><option value="REJECTED" {% if i.supplier_status=='REJECTED' %}selected{% endif %}>Tidak tersedia / Tolak</option></select></td><td><input type="number" name="confirmed_qty[]" step="0.001" min="0" max="{{ i.qty }}" value="{{ i.confirmed_qty or i.qty }}"></td><td><input type="number" name="supplier_price[]" step="0.01" min="0" value="{{ i.supplier_price or i.price }}"></td><td><span class="badge {{ 'badge-danger' if (i.supplier_price_diff or 0) > 0 else 'badge-success' if (i.supplier_price_diff or 0) < 0 else 'badge-gray' }}">{{ rupiah(i.supplier_price_diff or 0) }}</span></td><td><input name="supplier_note[]" value="{{ i.supplier_note or '' }}" placeholder="Contoh: stok kosong, harga naik, bisa kirim 5"></td></tr>{% endfor %}</tbody></table></div><div class="grid" style="margin-top:12px;"><div class="col-4"><div class="form-group"><label>Estimasi Kirim</label><input type="date" name="supplier_eta" value="{{ po_edit.supplier_eta or '' }}"></div></div><div class="col-4"><div class="form-group"><label>No. Referensi / Invoice</label><input name="supplier_reference" value="{{ po_edit.supplier_reference or '' }}" placeholder="INV/DO supplier"></div></div><div class="col-4"><div class="form-group"><label>Catatan Kirim</label><input name="supplier_delivery_note" value="{{ po_edit.supplier_delivery_note or '' }}" placeholder="contoh: kirim bertahap"></div></div></div><div class="form-group"><label>Feedback umum</label><textarea name="message" placeholder="Tulis catatan untuk admin..." style="min-height:70px;"></textarea></div><button class="btn-success" type="submit">Kirim Feedback ke Admin</button></form>{% else %}<div class="alert alert-info">PO ini sudah final / diterima admin.</div>{% endif %}
      <hr><h3>Riwayat Feedback</h3>{% for f in feedbacks %}<div class="card" style="padding:10px;margin:8px 0;"><div class="small muted">{{ f.created_at }}</div>{{ f.message }}</div>{% else %}<div class="muted">Belum ada feedback umum.</div>{% endfor %}{% else %}<div class="muted text-center">Pilih PO untuk melihat detail.</div>{% endif %}</div></div>
    </div>
    """, rows=rows, po_edit=po_edit, items=items, feedbacks=feedbacks, rupiah=rupiah, pending_count=pending_count, confirmed_count=confirmed_count, price_change_count=price_change_count, total_open_value=total_open_value)
    return render_page('Portal Supplier', body)

