# =========================
# Pusat Tata Kelola - 5 Enterprise Features
# 1) Pengumuman Internal, 2) Dokumen Terkendali, 3) Rapat & Keputusan,
# 4) Register Kepatuhan, 5) Serah Terima Shift
# =========================
def ensure_operations_plus_tables():
    conn=get_conn(); c=conn.cursor()
    statements=[
      "CREATE TABLE IF NOT EXISTS internal_announcements(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,message TEXT NOT NULL,audience_role TEXT DEFAULT 'ALL',priority TEXT DEFAULT 'NORMAL',publish_from TEXT,publish_until TEXT,status TEXT DEFAULT 'DRAFT',created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT)",
      "CREATE TABLE IF NOT EXISTS controlled_documents(id INTEGER PRIMARY KEY AUTOINCREMENT,document_no TEXT UNIQUE,title TEXT NOT NULL,category TEXT,version TEXT DEFAULT '1.0',owner_role TEXT,effective_date TEXT,review_date TEXT,status TEXT DEFAULT 'DRAFT',file_reference TEXT,change_note TEXT,created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT)",
      "CREATE TABLE IF NOT EXISTS meeting_decisions(id INTEGER PRIMARY KEY AUTOINCREMENT,meeting_date TEXT,subject TEXT NOT NULL,participants TEXT,decision TEXT NOT NULL,action_owner TEXT,due_date TEXT,priority TEXT DEFAULT 'NORMAL',status TEXT DEFAULT 'OPEN',evidence TEXT,created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,completed_at TEXT)",
      "CREATE TABLE IF NOT EXISTS compliance_register(id INTEGER PRIMARY KEY AUTOINCREMENT,control_code TEXT UNIQUE,area TEXT,requirement TEXT NOT NULL,owner_role TEXT,frequency TEXT,next_review TEXT,risk_level TEXT DEFAULT 'MEDIUM',status TEXT DEFAULT 'COMPLIANT',evidence TEXT,last_reviewed TEXT,created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP)",
      "CREATE TABLE IF NOT EXISTS shift_handovers(id INTEGER PRIMARY KEY AUTOINCREMENT,shift_date TEXT,shift_name TEXT,branch_id INTEGER,outgoing_person TEXT,incoming_person TEXT,summary TEXT,open_issues TEXT,critical_items TEXT,follow_up_owner TEXT,status TEXT DEFAULT 'OPEN',created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,acknowledged_by INTEGER,acknowledged_at TEXT)"
    ]
    for x in statements: c.execute(x)
    conn.commit(); conn.close()

def op_date(v):
    return (v or today_str()).strip()[:10]

def op_allowed_transition(feature, status):
    maps={'announcement':{'DRAFT','PUBLISHED','ARCHIVED'},'document':{'DRAFT','ACTIVE','REVIEW','OBSOLETE'},'meeting':{'OPEN','IN_PROGRESS','DONE','CANCELLED'},'compliance':{'COMPLIANT','ACTION_REQUIRED','OVERDUE','WAIVED'},'handover':{'OPEN','ACKNOWLEDGED','CLOSED'}}
    return status in maps.get(feature,set())

@app.route('/operations-plus', methods=['GET','POST'])
@login_required
@role_required('admin','bendahara','supervisor','branch_admin')
def operations_plus():
    ensure_operations_plus_tables(); user=current_user(); tab=request.args.get('tab','announcements'); q=request.args.get('q','').strip()
    tabs={'announcements':'Pengumuman','documents':'Dokumen','meetings':'Rapat & Keputusan','compliance':'Kepatuhan','handovers':'Serah Terima'}
    if tab not in tabs: tab='announcements'
    if request.method=='POST':
        feature=request.form.get('feature',''); action=request.form.get('action','create'); rid=int(request.form.get('record_id') or 0)
        try:
            if action=='status':
                status=request.form.get('status','').upper(); table={'announcement':'internal_announcements','document':'controlled_documents','meeting':'meeting_decisions','compliance':'compliance_register','handover':'shift_handovers'}.get(feature)
                if not table or not op_allowed_transition(feature,status): raise ValueError('Status tidak valid.')
                extra=', updated_at=?' if feature in ('announcement','document') else ''
                params=[status];
                if extra: params.append(now_str())
                params.append(rid); exec_sql(f'UPDATE {table} SET status=?{extra} WHERE id=?',params)
                if feature=='meeting' and status=='DONE': exec_sql('UPDATE meeting_decisions SET completed_at=? WHERE id=?',[now_str(),rid])
                if feature=='handover' and status=='ACKNOWLEDGED': exec_sql('UPDATE shift_handovers SET acknowledged_by=?, acknowledged_at=? WHERE id=?',[user['id'],now_str(),rid])
                log_action('GOVERNANCE_STATUS',table,rid,status); flash('Status berhasil diperbarui.','success')
            elif feature=='announcement':
                title=request.form.get('title','').strip(); message=request.form.get('message','').strip()
                if len(title)<3 or len(message)<10: raise ValueError('Judul minimal 3 karakter dan isi minimal 10 karakter.')
                exec_sql('INSERT INTO internal_announcements(title,message,audience_role,priority,publish_from,publish_until,status,created_by) VALUES(?,?,?,?,?,?,?,?)',[title,message,request.form.get('audience_role','ALL'),request.form.get('priority','NORMAL'),op_date(request.form.get('publish_from')),request.form.get('publish_until') or None,'PUBLISHED' if request.form.get('publish_now')=='1' else 'DRAFT',user['id']])
                log_action('ANNOUNCEMENT_CREATE','internal_announcements','',title); flash('Pengumuman berhasil dibuat.','success')
            elif feature=='document':
                title=request.form.get('title','').strip(); doc_no=request.form.get('document_no','').strip() or gen_code('DOC')
                if len(title)<3: raise ValueError('Judul dokumen wajib diisi.')
                exec_sql('INSERT INTO controlled_documents(document_no,title,category,version,owner_role,effective_date,review_date,status,file_reference,change_note,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[doc_no,title,request.form.get('category'),request.form.get('version','1.0'),request.form.get('owner_role'),op_date(request.form.get('effective_date')),request.form.get('review_date') or None,'ACTIVE' if request.form.get('activate')=='1' else 'DRAFT',request.form.get('file_reference'),request.form.get('change_note'),user['id']])
                log_action('DOCUMENT_CREATE','controlled_documents','',doc_no); flash('Dokumen terkendali berhasil diregistrasikan.','success')
            elif feature=='meeting':
                subject=request.form.get('subject','').strip(); decision=request.form.get('decision','').strip()
                if len(subject)<3 or len(decision)<5: raise ValueError('Subjek dan keputusan wajib diisi.')
                exec_sql('INSERT INTO meeting_decisions(meeting_date,subject,participants,decision,action_owner,due_date,priority,status,evidence,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)',[op_date(request.form.get('meeting_date')),subject,request.form.get('participants'),decision,request.form.get('action_owner'),request.form.get('due_date') or None,request.form.get('priority','NORMAL'),'OPEN',request.form.get('evidence'),user['id']])
                log_action('DECISION_CREATE','meeting_decisions','',subject); flash('Keputusan rapat dan tindak lanjut tersimpan.','success')
            elif feature=='compliance':
                req=request.form.get('requirement','').strip(); code=request.form.get('control_code','').strip() or gen_code('CTL')
                if len(req)<5: raise ValueError('Persyaratan kepatuhan wajib dijelaskan.')
                exec_sql('INSERT INTO compliance_register(control_code,area,requirement,owner_role,frequency,next_review,risk_level,status,evidence,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)',[code,request.form.get('area'),req,request.form.get('owner_role'),request.form.get('frequency'),request.form.get('next_review') or None,request.form.get('risk_level','MEDIUM'),'COMPLIANT',request.form.get('evidence'),user['id']])
                log_action('COMPLIANCE_CREATE','compliance_register','',code); flash('Kontrol kepatuhan berhasil ditambahkan.','success')
            elif feature=='handover':
                summary=request.form.get('summary','').strip()
                if len(summary)<5: raise ValueError('Ringkasan serah terima wajib diisi.')
                exec_sql('INSERT INTO shift_handovers(shift_date,shift_name,branch_id,outgoing_person,incoming_person,summary,open_issues,critical_items,follow_up_owner,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[op_date(request.form.get('shift_date')),request.form.get('shift_name'),session.get('branch_id'),request.form.get('outgoing_person'),request.form.get('incoming_person'),summary,request.form.get('open_issues'),request.form.get('critical_items'),request.form.get('follow_up_owner'),'OPEN',user['id']])
                log_action('HANDOVER_CREATE','shift_handovers','',summary[:80]); flash('Serah terima shift berhasil dicatat.','success')
            else: raise ValueError('Fitur tidak dikenali.')
        except (ValueError,sqlite3.IntegrityError) as e: flash(str(e) if isinstance(e,ValueError) else 'Kode unik sudah digunakan.','error')
        return redirect(url_for('operations_plus',tab=tab))
    like=f'%{q}%'
    data={
      'announcements':q_all('SELECT a.*,u.full_name creator FROM internal_announcements a LEFT JOIN users u ON u.id=a.created_by WHERE a.title LIKE ? OR a.message LIKE ? ORDER BY a.id DESC LIMIT 100',[like,like]),
      'documents':q_all('SELECT * FROM controlled_documents WHERE document_no LIKE ? OR title LIKE ? ORDER BY id DESC LIMIT 100',[like,like]),
      'meetings':q_all('SELECT * FROM meeting_decisions WHERE subject LIKE ? OR decision LIKE ? ORDER BY id DESC LIMIT 100',[like,like]),
      'compliance':q_all('SELECT * FROM compliance_register WHERE control_code LIKE ? OR requirement LIKE ? ORDER BY id DESC LIMIT 100',[like,like]),
      'handovers':q_all('SELECT * FROM shift_handovers WHERE summary LIKE ? OR open_issues LIKE ? ORDER BY id DESC LIMIT 100',[like,like])
    }
    counts={k:len(v) for k,v in data.items()}; overdue=q_one("SELECT COUNT(*) n FROM compliance_register WHERE next_review<? AND status NOT IN ('WAIVED','COMPLIANT')",[today_str()])['n']; open_actions=q_one("SELECT COUNT(*) n FROM meeting_decisions WHERE status IN ('OPEN','IN_PROGRESS')")['n']
    body=render_template_string(r'''
    <section class="gov-hero"><div><span>TATA KELOLA TERPADU</span><h2>Pusat Tata Kelola</h2><p>Lima kontrol baru untuk komunikasi, dokumen, keputusan, kepatuhan, dan kesinambungan operasional.</p></div><div class="gov-health"><b>{{open_actions}}</b><span>Tindak lanjut terbuka</span><b>{{overdue}}</b><span>Kepatuhan terlambat</span></div></section>
    <div class="gov-tabs">{% for key,label in tabs.items() %}<a class="{{'active' if tab==key}}" href="{{url_for('operations_plus',tab=key)}}"><span>{{counts[key]}}</span>{{label}}</a>{% endfor %}</div>
    <div class="gov-layout"><aside class="gov-create"><h3>Tambah {{tabs[tab]}}</h3>
    {% if tab=='announcements' %}<form method="post"><input type="hidden" name="feature" value="announcement"><div class="form-group"><label>Judul</label><input name="title" required></div><div class="form-group"><label>Isi Pengumuman</label><textarea name="message" required></textarea></div><div class="grid"><div class="col-6 form-group"><label>Target</label><select name="audience_role"><option>ALL</option><option>admin</option><option>kasir</option><option>bendahara</option><option>user</option></select></div><div class="col-6 form-group"><label>Prioritas</label><select name="priority"><option>NORMAL</option><option>HIGH</option><option>CRITICAL</option></select></div></div><div class="form-group"><label>Mulai Tayang</label><input type="date" name="publish_from" value="{{today}}"></div><label class="gov-check"><input type="checkbox" name="publish_now" value="1" checked> Publikasikan sekarang</label><button>Simpan Pengumuman</button></form>
    {% elif tab=='documents' %}<form method="post"><input type="hidden" name="feature" value="document"><div class="form-group"><label>Nomor Dokumen</label><input name="document_no" placeholder="Otomatis bila kosong"></div><div class="form-group"><label>Judul</label><input name="title" required></div><div class="grid"><div class="col-6 form-group"><label>Kategori</label><input name="category"></div><div class="col-6 form-group"><label>Versi</label><input name="version" value="1.0"></div></div><div class="form-group"><label>Pemilik</label><select name="owner_role"><option>admin</option><option>bendahara</option><option>supervisor</option><option>branch_admin</option></select></div><div class="grid"><div class="col-6 form-group"><label>Berlaku</label><input type="date" name="effective_date" value="{{today}}"></div><div class="col-6 form-group"><label>Review</label><input type="date" name="review_date"></div></div><div class="form-group"><label>Referensi File</label><input name="file_reference" placeholder="Path / URL internal"></div><div class="form-group"><label>Catatan Perubahan</label><textarea name="change_note"></textarea></div><label class="gov-check"><input type="checkbox" name="activate" value="1"> Aktifkan dokumen</label><button>Registrasikan Dokumen</button></form>
    {% elif tab=='meetings' %}<form method="post"><input type="hidden" name="feature" value="meeting"><div class="form-group"><label>Tanggal Rapat</label><input type="date" name="meeting_date" value="{{today}}"></div><div class="form-group"><label>Subjek</label><input name="subject" required></div><div class="form-group"><label>Peserta</label><input name="participants"></div><div class="form-group"><label>Keputusan</label><textarea name="decision" required></textarea></div><div class="form-group"><label>Pemilik Aksi</label><input name="action_owner"></div><div class="grid"><div class="col-6 form-group"><label>Jatuh Tempo</label><input type="date" name="due_date"></div><div class="col-6 form-group"><label>Prioritas</label><select name="priority"><option>NORMAL</option><option>HIGH</option><option>CRITICAL</option></select></div></div><button>Simpan Keputusan</button></form>
    {% elif tab=='compliance' %}<form method="post"><input type="hidden" name="feature" value="compliance"><div class="form-group"><label>Kode Kontrol</label><input name="control_code" placeholder="Otomatis bila kosong"></div><div class="form-group"><label>Area</label><input name="area"></div><div class="form-group"><label>Persyaratan</label><textarea name="requirement" required></textarea></div><div class="grid"><div class="col-6 form-group"><label>Pemilik</label><select name="owner_role"><option>admin</option><option>bendahara</option><option>supervisor</option><option>branch_admin</option></select></div><div class="col-6 form-group"><label>Risiko</label><select name="risk_level"><option>LOW</option><option selected>MEDIUM</option><option>HIGH</option><option>CRITICAL</option></select></div></div><div class="grid"><div class="col-6 form-group"><label>Frekuensi</label><input name="frequency" placeholder="Bulanan/Tahunan"></div><div class="col-6 form-group"><label>Review Berikutnya</label><input type="date" name="next_review"></div></div><button>Tambah Kontrol</button></form>
    {% else %}<form method="post"><input type="hidden" name="feature" value="handover"><div class="grid"><div class="col-6 form-group"><label>Tanggal</label><input type="date" name="shift_date" value="{{today}}"></div><div class="col-6 form-group"><label>Shift</label><input name="shift_name" placeholder="Pagi/Malam"></div></div><div class="grid"><div class="col-6 form-group"><label>Penyerah</label><input name="outgoing_person"></div><div class="col-6 form-group"><label>Penerima</label><input name="incoming_person"></div></div><div class="form-group"><label>Ringkasan</label><textarea name="summary" required></textarea></div><div class="form-group"><label>Masalah Terbuka</label><textarea name="open_issues"></textarea></div><div class="form-group"><label>Item Kritis</label><textarea name="critical_items"></textarea></div><div class="form-group"><label>Pemilik Tindak Lanjut</label><input name="follow_up_owner"></div><button>Simpan Serah Terima</button></form>{% endif %}</aside>
    <main class="gov-data"><div class="gov-data-head"><div><h3>{{tabs[tab]}}</h3><p>Data terbaru, status, dan tindak lanjut.</p></div><form method="get"><input type="hidden" name="tab" value="{{tab}}"><input name="q" value="{{q}}" placeholder="Cari data..."><button class="btn btn-ghost">Cari</button></form></div>
    <div class="gov-cards">{% for r in data[tab] %}<article class="gov-record"><div class="gov-record-main"><span class="gov-record-code">{% if tab=='documents' %}{{r.document_no}}{% elif tab=='compliance' %}{{r.control_code}}{% elif tab=='handovers' %}{{r.shift_date}} · {{r.shift_name}}{% else %}{{r.created_at[:10]}}{% endif %}</span><h4>{% if tab=='announcements' %}{{r.title}}{% elif tab=='documents' %}{{r.title}}{% elif tab=='meetings' %}{{r.subject}}{% elif tab=='compliance' %}{{r.requirement}}{% else %}{{r.summary}}{% endif %}</h4><p>{% if tab=='announcements' %}{{r.message}}{% elif tab=='documents' %}Versi {{r.version}} · {{r.category or '-'}} · review {{r.review_date or '-'}}{% elif tab=='meetings' %}{{r.decision}} · owner {{r.action_owner or '-'}}{% elif tab=='compliance' %}{{r.area or '-'}} · risiko {{r.risk_level}} · review {{r.next_review or '-'}}{% else %}{{r.open_issues or 'Tidak ada masalah terbuka'}}{% endif %}</p></div><div class="gov-record-side"><span class="badge {{'badge-success' if r.status in ('PUBLISHED','ACTIVE','DONE','COMPLIANT','ACKNOWLEDGED','CLOSED') else 'badge-warn'}}">{{r.status}}</span><form method="post"><input type="hidden" name="feature" value="{{'announcement' if tab=='announcements' else 'document' if tab=='documents' else 'meeting' if tab=='meetings' else 'compliance' if tab=='compliance' else 'handover'}}"><input type="hidden" name="action" value="status"><input type="hidden" name="record_id" value="{{r.id}}"><select name="status">{% if tab=='announcements' %}<option>DRAFT</option><option>PUBLISHED</option><option>ARCHIVED</option>{% elif tab=='documents' %}<option>DRAFT</option><option>ACTIVE</option><option>REVIEW</option><option>OBSOLETE</option>{% elif tab=='meetings' %}<option>OPEN</option><option>IN_PROGRESS</option><option>DONE</option><option>CANCELLED</option>{% elif tab=='compliance' %}<option>COMPLIANT</option><option>ACTION_REQUIRED</option><option>OVERDUE</option><option>WAIVED</option>{% else %}<option>OPEN</option><option>ACKNOWLEDGED</option><option>CLOSED</option>{% endif %}</select><button class="btn btn-sm">Update</button></form></div></article>{% else %}<div class="gov-empty"><b>Belum ada data</b><span>Gunakan form di sisi kiri untuk membuat data pertama.</span></div>{% endfor %}</div></main></div>
    ''',tab=tab,tabs=tabs,data=data,counts=counts,q=q,today=today_str(),open_actions=open_actions,overdue=overdue)
    return render_page('Pusat Tata Kelola',body)

# =========================
# Credit Control Suite - 5 cooperative features
# KYC, Guarantor, Collateral, Restructuring, Collection Promise
# =========================
def ensure_credit_control_tables():
    conn=get_conn(); c=conn.cursor()
    statements=[
      "CREATE TABLE IF NOT EXISTS member_kyc(id INTEGER PRIMARY KEY AUTOINCREMENT,member_id INTEGER UNIQUE,id_type TEXT,id_number TEXT,address_verified INTEGER DEFAULT 0,employment_verified INTEGER DEFAULT 0,income_verified REAL DEFAULT 0,risk_note TEXT,status TEXT DEFAULT 'PENDING',verified_by INTEGER,verified_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP)",
      "CREATE TABLE IF NOT EXISTS loan_guarantors(id INTEGER PRIMARY KEY AUTOINCREMENT,loan_id INTEGER,member_id INTEGER,guarantor_name TEXT,identity_number TEXT,phone TEXT,relationship TEXT,income REAL,consent INTEGER DEFAULT 0,status TEXT DEFAULT 'PENDING',created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP)",
      "CREATE TABLE IF NOT EXISTS loan_collaterals(id INTEGER PRIMARY KEY AUTOINCREMENT,loan_id INTEGER,collateral_code TEXT UNIQUE,collateral_type TEXT,description TEXT,owner_name TEXT,document_number TEXT,estimated_value REAL,valuation_date TEXT,storage_location TEXT,status TEXT DEFAULT 'HELD',released_at TEXT,created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP)",
      "CREATE TABLE IF NOT EXISTS loan_restructures(id INTEGER PRIMARY KEY AUTOINCREMENT,loan_id INTEGER,request_date TEXT,old_tenor INTEGER,new_tenor INTEGER,old_installment REAL,new_installment REAL,reason TEXT,impact_note TEXT,status TEXT DEFAULT 'PENDING',approved_by INTEGER,approved_at TEXT,created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP)",
      "CREATE TABLE IF NOT EXISTS collection_promises(id INTEGER PRIMARY KEY AUTOINCREMENT,loan_id INTEGER,member_id INTEGER,contact_date TEXT,contact_method TEXT,promise_date TEXT,promise_amount REAL,collector_note TEXT,status TEXT DEFAULT 'PROMISED',created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,fulfilled_at TEXT)"
    ]
    for sql in statements: c.execute(sql)
    conn.commit(); conn.close()

def credit_control_status_ok(feature,status):
    allowed={'kyc':{'PENDING','VERIFIED','REJECTED','EXPIRED'},'guarantor':{'PENDING','VERIFIED','REJECTED','RELEASED'},'collateral':{'HELD','REVIEW','RELEASED'},'restructure':{'PENDING','APPROVED','REJECTED','APPLIED'},'promise':{'PROMISED','FULFILLED','BROKEN','RESCHEDULED'}}
    return status in allowed.get(feature,set())

@app.route('/credit-control',methods=['GET','POST'])
@login_required
@role_required('admin','bendahara','supervisor','branch_admin')
def credit_control():
    ensure_credit_control_tables(); user=current_user(); tab=request.args.get('tab','kyc'); search=request.args.get('q','').strip()
    tabs={'kyc':'KYC Anggota','guarantors':'Penjamin','collaterals':'Agunan','restructures':'Restrukturisasi','collections':'Janji Bayar'}
    if tab not in tabs: tab='kyc'
    if request.method=='POST':
        feature=request.form.get('feature',''); action=request.form.get('action','create'); rid=int(request.form.get('record_id') or 0)
        try:
            if action=='status':
                status=request.form.get('status','').upper()
                fmap={'kyc':('member_kyc','kyc'),'guarantor':('loan_guarantors','guarantor'),'collateral':('loan_collaterals','collateral'),'restructure':('loan_restructures','restructure'),'promise':('collection_promises','promise')}
                table,key=fmap.get(feature,(None,None))
                if not table or not credit_control_status_ok(key,status): raise ValueError('Status tidak diizinkan.')
                exec_sql(f'UPDATE {table} SET status=? WHERE id=?',[status,rid])
                if feature=='kyc' and status=='VERIFIED': exec_sql('UPDATE member_kyc SET verified_by=?,verified_at=? WHERE id=?',[user['id'],now_str(),rid])
                if feature=='collateral' and status=='RELEASED': exec_sql('UPDATE loan_collaterals SET released_at=? WHERE id=?',[now_str(),rid])
                if feature=='restructure' and status=='APPROVED': exec_sql('UPDATE loan_restructures SET approved_by=?,approved_at=? WHERE id=?',[user['id'],now_str(),rid])
                if feature=='promise' and status=='FULFILLED': exec_sql('UPDATE collection_promises SET fulfilled_at=? WHERE id=?',[now_str(),rid])
                log_action('CREDIT_CONTROL_STATUS',table,rid,status); flash('Status berhasil diperbarui.','success')
            elif feature=='kyc':
                mid=int(request.form.get('member_id') or 0); id_no=request.form.get('id_number','').strip()
                if not mid or len(id_no)<4: raise ValueError('Anggota dan nomor identitas wajib diisi.')
                exec_sql('INSERT INTO member_kyc(member_id,id_type,id_number,address_verified,employment_verified,income_verified,risk_note,status) VALUES(?,?,?,?,?,?,?,"PENDING") ON CONFLICT(member_id) DO UPDATE SET id_type=excluded.id_type,id_number=excluded.id_number,address_verified=excluded.address_verified,employment_verified=excluded.employment_verified,income_verified=excluded.income_verified,risk_note=excluded.risk_note,status="PENDING"',[mid,request.form.get('id_type'),id_no,1 if request.form.get('address_verified') else 0,1 if request.form.get('employment_verified') else 0,parse_float(request.form.get('income_verified',0)),request.form.get('risk_note')])
                log_action('KYC_UPSERT','member_kyc',mid,id_no); flash('KYC anggota berhasil disimpan untuk verifikasi.','success')
            elif feature=='guarantor':
                lid=int(request.form.get('loan_id') or 0); name=request.form.get('guarantor_name','').strip()
                if not lid or len(name)<3: raise ValueError('Pinjaman dan nama penjamin wajib diisi.')
                exec_sql('INSERT INTO loan_guarantors(loan_id,member_id,guarantor_name,identity_number,phone,relationship,income,consent,status,created_by) VALUES(?,?,?,?,?,?,?,?,"PENDING",?)',[lid,request.form.get('member_id') or None,name,request.form.get('identity_number'),request.form.get('phone'),request.form.get('relationship'),parse_float(request.form.get('income',0)),1 if request.form.get('consent') else 0,user['id']])
                log_action('GUARANTOR_CREATE','loan_guarantors',lid,name); flash('Penjamin berhasil diregistrasikan.','success')
            elif feature=='collateral':
                lid=int(request.form.get('loan_id') or 0); desc=request.form.get('description','').strip(); code=request.form.get('collateral_code','').strip() or gen_code('COL')
                if not lid or len(desc)<5: raise ValueError('Pinjaman dan deskripsi agunan wajib diisi.')
                exec_sql('INSERT INTO loan_collaterals(loan_id,collateral_code,collateral_type,description,owner_name,document_number,estimated_value,valuation_date,storage_location,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,"HELD",?)',[lid,code,request.form.get('collateral_type'),desc,request.form.get('owner_name'),request.form.get('document_number'),parse_float(request.form.get('estimated_value',0)),request.form.get('valuation_date') or today_str(),request.form.get('storage_location'),user['id']])
                log_action('COLLATERAL_CREATE','loan_collaterals',lid,code); flash('Agunan berhasil diregistrasikan.','success')
            elif feature=='restructure':
                lid=int(request.form.get('loan_id') or 0); reason=request.form.get('reason','').strip(); loan=q_one('SELECT * FROM loans WHERE id=?',[lid])
                if not loan or len(reason)<10: raise ValueError('Pinjaman valid dan alasan minimal 10 karakter diperlukan.')
                new_tenor=max(1,int(request.form.get('new_tenor') or loan['tenor_month'])); new_inst=max(0,parse_float(request.form.get('new_installment',loan['monthly_installment'])))
                exec_sql('INSERT INTO loan_restructures(loan_id,request_date,old_tenor,new_tenor,old_installment,new_installment,reason,impact_note,status,created_by) VALUES(?,?,?,?,?,?,?,?,"PENDING",?)',[lid,today_str(),loan['tenor_month'],new_tenor,loan['monthly_installment'],new_inst,reason,request.form.get('impact_note'),user['id']])
                log_action('RESTRUCTURE_REQUEST','loan_restructures',lid,reason); flash('Permohonan restrukturisasi berhasil dibuat.','success')
            elif feature=='promise':
                lid=int(request.form.get('loan_id') or 0); loan=q_one('SELECT * FROM loans WHERE id=?',[lid]); amount=parse_float(request.form.get('promise_amount',0))
                if not loan or amount<=0 or not request.form.get('promise_date'): raise ValueError('Pinjaman, tanggal janji, dan nominal wajib valid.')
                exec_sql('INSERT INTO collection_promises(loan_id,member_id,contact_date,contact_method,promise_date,promise_amount,collector_note,status,created_by) VALUES(?,?,?,?,?,?,?,"PROMISED",?)',[lid,loan['member_id'],today_str(),request.form.get('contact_method'),request.form.get('promise_date'),amount,request.form.get('collector_note'),user['id']])
                log_action('PAYMENT_PROMISE_CREATE','collection_promises',lid,str(amount)); flash('Janji bayar berhasil dicatat.','success')
            else: raise ValueError('Fitur tidak dikenali.')
        except (ValueError,sqlite3.IntegrityError) as e: flash(str(e) if isinstance(e,ValueError) else 'Data unik sudah digunakan.','error')
        return redirect(url_for('credit_control',tab=tab))
    like=f'%{search}%'; members=q_all("SELECT id,member_code,name FROM members WHERE status='Aktif' ORDER BY name"); loans_active=q_all("SELECT l.id,l.loan_no,l.member_id,m.name,l.tenor_month,l.monthly_installment FROM loans l JOIN members m ON m.id=l.member_id WHERE l.status IN ('Berjalan','CALCULATED') ORDER BY l.id DESC")
    data={
      'kyc':q_all('SELECT k.*,m.member_code,m.name FROM member_kyc k JOIN members m ON m.id=k.member_id WHERE m.name LIKE ? OR k.id_number LIKE ? ORDER BY k.id DESC',[like,like]),
      'guarantors':q_all('SELECT g.*,l.loan_no,m.name member_name FROM loan_guarantors g JOIN loans l ON l.id=g.loan_id LEFT JOIN members m ON m.id=l.member_id WHERE g.guarantor_name LIKE ? OR l.loan_no LIKE ? ORDER BY g.id DESC',[like,like]),
      'collaterals':q_all('SELECT c.*,l.loan_no,m.name member_name FROM loan_collaterals c JOIN loans l ON l.id=c.loan_id LEFT JOIN members m ON m.id=l.member_id WHERE c.description LIKE ? OR c.collateral_code LIKE ? ORDER BY c.id DESC',[like,like]),
      'restructures':q_all('SELECT r.*,l.loan_no,m.name member_name FROM loan_restructures r JOIN loans l ON l.id=r.loan_id LEFT JOIN members m ON m.id=l.member_id WHERE l.loan_no LIKE ? OR r.reason LIKE ? ORDER BY r.id DESC',[like,like]),
      'collections':q_all('SELECT p.*,l.loan_no,m.name member_name FROM collection_promises p JOIN loans l ON l.id=p.loan_id LEFT JOIN members m ON m.id=p.member_id WHERE l.loan_no LIKE ? OR m.name LIKE ? ORDER BY p.id DESC',[like,like])
    }
    counts={k:len(v) for k,v in data.items()}
    body=render_template_string(r'''
    <section class="ccs-hero"><div><span>CREDIT CONTROL SUITE</span><h2>Kontrol Risiko Kredit</h2><p>KYC, penjamin, agunan, restrukturisasi, dan penagihan dalam satu alur terkontrol.</p></div><div class="ccs-score"><strong>{{counts.kyc+counts.guarantors+counts.collaterals+counts.restructures+counts.collections}}</strong><span>Total catatan kontrol</span></div></section>
    <nav class="ccs-tabs">{% for key,label in tabs.items() %}<a class="{{'active' if tab==key}}" href="{{url_for('credit_control',tab=key)}}"><b>{{counts[key]}}</b>{{label}}</a>{% endfor %}</nav>
    <div class="ccs-layout"><aside class="ccs-form"><h3>Tambah {{tabs[tab]}}</h3>
    {% if tab=='kyc' %}<form method="post"><input type="hidden" name="feature" value="kyc"><div class="form-group"><label>Anggota</label><select name="member_id" required><option value="">Pilih anggota</option>{% for m in members %}<option value="{{m.id}}">{{m.member_code}} · {{m.name}}</option>{% endfor %}</select></div><div class="grid"><div class="col-5 form-group"><label>Identitas</label><select name="id_type"><option>KTP</option><option>SIM</option><option>Passport</option></select></div><div class="col-7 form-group"><label>Nomor</label><input name="id_number" required></div></div><div class="form-group"><label>Penghasilan Terverifikasi</label><input type="number" name="income_verified" min="0"></div><label class="ccs-check"><input type="checkbox" name="address_verified"> Alamat terverifikasi</label><label class="ccs-check"><input type="checkbox" name="employment_verified"> Pekerjaan terverifikasi</label><div class="form-group"><label>Catatan Risiko</label><textarea name="risk_note"></textarea></div><button>Simpan KYC</button></form>
    {% elif tab=='guarantors' %}<form method="post"><input type="hidden" name="feature" value="guarantor"><div class="form-group"><label>Pinjaman</label><select name="loan_id" required><option value="">Pilih pinjaman</option>{% for l in loans %}<option value="{{l.id}}">{{l.loan_no}} · {{l.name}}</option>{% endfor %}</select></div><div class="form-group"><label>Nama Penjamin</label><input name="guarantor_name" required></div><div class="form-group"><label>Nomor Identitas</label><input name="identity_number"></div><div class="grid"><div class="col-6 form-group"><label>Telepon</label><input name="phone"></div><div class="col-6 form-group"><label>Hubungan</label><input name="relationship"></div></div><div class="form-group"><label>Penghasilan</label><input type="number" name="income" min="0"></div><label class="ccs-check"><input type="checkbox" name="consent" required> Persetujuan penjamin diterima</label><button>Simpan Penjamin</button></form>
    {% elif tab=='collaterals' %}<form method="post"><input type="hidden" name="feature" value="collateral"><div class="form-group"><label>Pinjaman</label><select name="loan_id" required><option value="">Pilih pinjaman</option>{% for l in loans %}<option value="{{l.id}}">{{l.loan_no}} · {{l.name}}</option>{% endfor %}</select></div><div class="grid"><div class="col-6 form-group"><label>Kode</label><input name="collateral_code" placeholder="Otomatis"></div><div class="col-6 form-group"><label>Jenis</label><input name="collateral_type"></div></div><div class="form-group"><label>Deskripsi</label><textarea name="description" required></textarea></div><div class="grid"><div class="col-6 form-group"><label>Pemilik</label><input name="owner_name"></div><div class="col-6 form-group"><label>Dokumen</label><input name="document_number"></div></div><div class="form-group"><label>Nilai Taksiran</label><input type="number" name="estimated_value" min="0"></div><div class="form-group"><label>Lokasi Penyimpanan</label><input name="storage_location"></div><button>Simpan Agunan</button></form>
    {% elif tab=='restructures' %}<form method="post"><input type="hidden" name="feature" value="restructure"><div class="form-group"><label>Pinjaman</label><select name="loan_id" required><option value="">Pilih pinjaman</option>{% for l in loans %}<option value="{{l.id}}">{{l.loan_no}} · {{l.name}}</option>{% endfor %}</select></div><div class="grid"><div class="col-6 form-group"><label>Tenor Baru</label><input type="number" name="new_tenor" min="1"></div><div class="col-6 form-group"><label>Angsuran Baru</label><input type="number" name="new_installment" min="0"></div></div><div class="form-group"><label>Alasan</label><textarea name="reason" minlength="10" required></textarea></div><div class="form-group"><label>Analisis Dampak</label><textarea name="impact_note"></textarea></div><button>Ajukan Restrukturisasi</button></form>
    {% else %}<form method="post"><input type="hidden" name="feature" value="promise"><div class="form-group"><label>Pinjaman</label><select name="loan_id" required><option value="">Pilih pinjaman</option>{% for l in loans %}<option value="{{l.id}}">{{l.loan_no}} · {{l.name}}</option>{% endfor %}</select></div><div class="grid"><div class="col-6 form-group"><label>Metode Kontak</label><select name="contact_method"><option>Telepon</option><option>WhatsApp</option><option>Kunjungan</option><option>Email</option></select></div><div class="col-6 form-group"><label>Tanggal Janji</label><input type="date" name="promise_date" required></div></div><div class="form-group"><label>Nominal Janji</label><input type="number" name="promise_amount" min="1" required></div><div class="form-group"><label>Catatan Kolektor</label><textarea name="collector_note"></textarea></div><button>Catat Janji Bayar</button></form>{% endif %}</aside>
    <main class="ccs-data"><header><div><h3>{{tabs[tab]}}</h3><p>Validasi, status, dan jejak kontrol.</p></div><form method="get"><input type="hidden" name="tab" value="{{tab}}"><input name="q" value="{{search}}" placeholder="Cari data"><button class="btn btn-ghost">Cari</button></form></header><div class="ccs-list">{% for r in data[tab] %}<article><div><span>{% if tab=='kyc' %}{{r.member_code}}{% elif tab=='collaterals' %}{{r.collateral_code}}{% else %}{{r.loan_no}}{% endif %}</span><h4>{% if tab=='kyc' %}{{r.name}}{% elif tab=='guarantors' %}{{r.guarantor_name}} · {{r.member_name}}{% elif tab=='collaterals' %}{{r.description}}{% elif tab=='restructures' %}{{r.member_name}} · {{r.old_tenor}}→{{r.new_tenor}} bulan{% else %}{{r.member_name}} · {{r.promise_date}}{% endif %}</h4><p>{% if tab=='kyc' %}{{r.id_type}} {{r.id_number}} · penghasilan {{rupiah(r.income_verified)}}{% elif tab=='guarantors' %}{{r.relationship or '-'}} · {{r.phone or '-'}}{% elif tab=='collaterals' %}Nilai {{rupiah(r.estimated_value)}} · {{r.storage_location or '-'}}{% elif tab=='restructures' %}{{r.reason}} · {{rupiah(r.old_installment)}}→{{rupiah(r.new_installment)}}{% else %}Janji {{rupiah(r.promise_amount)}} via {{r.contact_method}}{% endif %}</p></div><aside><span class="badge {{'badge-success' if r.status in ('VERIFIED','RELEASED','APPROVED','APPLIED','FULFILLED') else 'badge-warn'}}">{{r.status}}</span><form method="post"><input type="hidden" name="feature" value="{{'kyc' if tab=='kyc' else 'guarantor' if tab=='guarantors' else 'collateral' if tab=='collaterals' else 'restructure' if tab=='restructures' else 'promise'}}"><input type="hidden" name="action" value="status"><input type="hidden" name="record_id" value="{{r.id}}"><select name="status">{% if tab=='kyc' %}<option>PENDING</option><option>VERIFIED</option><option>REJECTED</option><option>EXPIRED</option>{% elif tab=='guarantors' %}<option>PENDING</option><option>VERIFIED</option><option>REJECTED</option><option>RELEASED</option>{% elif tab=='collaterals' %}<option>HELD</option><option>REVIEW</option><option>RELEASED</option>{% elif tab=='restructures' %}<option>PENDING</option><option>APPROVED</option><option>REJECTED</option><option>APPLIED</option>{% else %}<option>PROMISED</option><option>FULFILLED</option><option>BROKEN</option><option>RESCHEDULED</option>{% endif %}</select><button class="btn btn-sm">Update</button></form></aside></article>{% else %}<div class="ccs-empty">Belum ada data pada fitur ini.</div>{% endfor %}</div></main></div>
    ''',tab=tab,tabs=tabs,data=data,counts=counts,members=members,loans=loans_active,search=search,rupiah=rupiah)
    return render_page('Kontrol Risiko Kredit',body)


# ==========================================================
# PROFESSIONAL INNOVATION SUITE
# ==========================================================
def init_innovation_db():
    conn=get_conn(); c=conn.cursor()
    for sql in [
      "CREATE TABLE IF NOT EXISTS workflow_tasks(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT,description TEXT,priority TEXT DEFAULT 'NORMAL',assigned_role TEXT,status TEXT DEFAULT 'OPEN',due_date TEXT,created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,completed_at TEXT)",
      "CREATE TABLE IF NOT EXISTS reminder_queue(id INTEGER PRIMARY KEY AUTOINCREMENT,member_id INTEGER,loan_id INTEGER,reminder_type TEXT,due_date TEXT,message TEXT,status TEXT DEFAULT 'PENDING',created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(loan_id,reminder_type,due_date))",
      "CREATE TABLE IF NOT EXISTS cash_reconciliations(id INTEGER PRIMARY KEY AUTOINCREMENT,reconcile_date TEXT,expected_cash REAL,physical_cash REAL,difference REAL,explanation TEXT,status TEXT DEFAULT 'SUBMITTED',prepared_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP)",
      "CREATE TABLE IF NOT EXISTS member_risk_profiles(id INTEGER PRIMARY KEY AUTOINCREMENT,member_id INTEGER UNIQUE,income REAL,installment_ratio REAL,late_count INTEGER,savings_balance REAL,score REAL,risk_level TEXT,reasons TEXT,reviewed_at TEXT)",
      "CREATE TABLE IF NOT EXISTS savings_obligations(id INTEGER PRIMARY KEY AUTOINCREMENT,member_id INTEGER,period_month TEXT,amount_due REAL,amount_paid REAL DEFAULT 0,due_date TEXT,status TEXT DEFAULT 'UNPAID',UNIQUE(member_id,period_month))",
      "CREATE TABLE IF NOT EXISTS monthly_closing(id INTEGER PRIMARY KEY AUTOINCREMENT,period_month TEXT,step_key TEXT,step_label TEXT,is_done INTEGER DEFAULT 0,note TEXT,UNIQUE(period_month,step_key))",
      "CREATE TABLE IF NOT EXISTS fixed_assets(id INTEGER PRIMARY KEY AUTOINCREMENT,asset_code TEXT UNIQUE,asset_name TEXT,category TEXT,acquisition_date TEXT,acquisition_cost REAL,useful_life_months INTEGER,residual_value REAL,location TEXT,responsible_person TEXT,next_maintenance TEXT,status TEXT DEFAULT 'ACTIVE')",
      "CREATE TABLE IF NOT EXISTS budgets(id INTEGER PRIMARY KEY AUTOINCREMENT,fiscal_year INTEGER,account_code TEXT,department TEXT,annual_budget REAL,warning_percent REAL DEFAULT 90,created_by INTEGER,UNIQUE(fiscal_year,account_code,department))",
      "CREATE TABLE IF NOT EXISTS helpdesk_tickets(id INTEGER PRIMARY KEY AUTOINCREMENT,ticket_no TEXT UNIQUE,member_id INTEGER,category TEXT,subject TEXT,description TEXT,priority TEXT,status TEXT DEFAULT 'OPEN',sla_due TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP)",
      "CREATE TABLE IF NOT EXISTS privacy_consents(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,policy_version TEXT,purpose TEXT,consent_status TEXT,consent_at TEXT,revoked_at TEXT)",
      "CREATE TABLE IF NOT EXISTS backup_runs(id INTEGER PRIMARY KEY AUTOINCREMENT,backup_time TEXT,file_name TEXT,file_size INTEGER,status TEXT,checksum TEXT,created_by INTEGER,note TEXT)",
      "CREATE TABLE IF NOT EXISTS early_warnings(id INTEGER PRIMARY KEY AUTOINCREMENT,warning_type TEXT,severity TEXT,title TEXT,detail TEXT,ref_type TEXT,ref_id INTEGER,status TEXT DEFAULT 'OPEN',due_date TEXT,UNIQUE(warning_type,ref_type,ref_id,status))"
    ]: c.execute(sql)
    conn.commit(); conn.close()

def innovation_refresh():
    month=datetime.now().strftime('%Y-%m')
    steps=['Tutup kasir','Rekonsiliasi kas','Rekonsiliasi bank','Stok opname','Review PO','Penyusutan aset','Akrual biaya','Hitung denda','Periksa jurnal','Review supervisor','Kunci periode']
    for i,x in enumerate(steps): exec_sql('INSERT OR IGNORE INTO monthly_closing(period_month,step_key,step_label) VALUES(?,?,?)',[month,f'S{i+1:02}',x])
    for m in q_all("SELECT id FROM members WHERE status='Aktif'"): exec_sql('INSERT OR IGNORE INTO savings_obligations(member_id,period_month,amount_due,due_date) VALUES(?,?,50000,?)',[m['id'],month,f'{month}-25'])
    for x in q_all("SELECT ls.loan_id,ls.due_date,ls.amount,l.member_id,m.name FROM loan_schedules ls JOIN loans l ON l.id=ls.loan_id JOIN members m ON m.id=l.member_id WHERE ls.status='BELUM_BAYAR'"):
        try:
            d=(datetime.strptime(x['due_date'],'%Y-%m-%d').date()-date.today()).days
            typ='H-7' if d==7 else 'H-3' if d==3 else 'JATUH TEMPO' if d==0 else 'TERLAMBAT' if d<0 else None
            if typ: exec_sql('INSERT OR IGNORE INTO reminder_queue(member_id,loan_id,reminder_type,due_date,message) VALUES(?,?,?,?,?)',[x['member_id'],x['loan_id'],typ,x['due_date'],f"Angsuran {x['name']} {rupiah(x['amount'])}"])
        except: pass
    for p in q_all('SELECT id,product_name,stock,min_stock FROM products WHERE active=1 AND stock<=min_stock'):
        exec_sql("INSERT OR IGNORE INTO early_warnings(warning_type,severity,title,detail,ref_type,ref_id,due_date) VALUES('LOW_STOCK','HIGH',?,?,?,?,?)",[f"Stok kritis: {p['product_name']}",f"Stok {p['stock']} / minimum {p['min_stock']}",'product',p['id'],today_str()])

def innovation_backup(note=''):
    import shutil
    d=Path('backups'); d.mkdir(exist_ok=True); name=f"backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}.db"; target=d/name
    shutil.copy2(Path(DB_NAME),target); checksum=hashlib.sha256(target.read_bytes()).hexdigest()
    exec_sql('INSERT INTO backup_runs(backup_time,file_name,file_size,status,checksum,created_by,note) VALUES(?,?,?,?,?,?,?)',[now_str(),name,target.stat().st_size,'SUCCESS',checksum,session.get('user_id'),note])

def build_smart_health_report():
    """Audit read-only untuk kesehatan data, konfigurasi, dan operasi."""
    checks=[]
    def add(title, value, severity, recommendation):
        checks.append({'title':title,'value':int(value or 0),'severity':severity,'recommendation':recommendation})
    add('Stok pusat negatif',q_one('SELECT COUNT(*) n FROM products WHERE COALESCE(stock,0)<0')['n'],'CRITICAL','Audit transaksi dan koreksi stok.')
    add('Stok cabang negatif',q_one('SELECT COUNT(*) n FROM product_branch_stock WHERE COALESCE(stock,0)<0')['n'],'CRITICAL','Audit transfer stok cabang.')
    add('Produk di bawah minimum',q_one('SELECT COUNT(*) n FROM products WHERE active=1 AND COALESCE(stock,0)<=COALESCE(min_stock,0)')['n'],'HIGH','Buat PO atau transfer antar cabang.')
    add('Jurnal tidak seimbang',q_one("SELECT COUNT(*) n FROM (SELECT entry_no FROM journal_entries GROUP BY entry_no HAVING ABS(SUM(COALESCE(debit,0))-SUM(COALESCE(credit,0)))>0.01)")['n'],'CRITICAL','Tahan closing dan koreksi jurnal.')
    add('Angsuran lewat jatuh tempo',q_one("SELECT COUNT(*) n FROM loan_schedules WHERE due_date<? AND status!='LUNAS'",[today_str()])['n'],'HIGH','Jalankan reminder penagihan.')
    add('Topup menunggu verifikasi',q_one("SELECT COUNT(*) n FROM topup_requests WHERE status='PENDING'")['n'],'MEDIUM','Verifikasi sesuai SLA.')
    add('Akun menunggu approval',q_one("SELECT COUNT(*) n FROM users WHERE status='PENDING_APPROVAL'")['n'],'MEDIUM','Tinjau identitas pegawai.')
    add('Tiket belum selesai',q_one("SELECT COUNT(*) n FROM helpdesk_tickets WHERE status!='CLOSED'")['n'],'MEDIUM','Urutkan menurut prioritas dan SLA.')
    weights={'CRITICAL':12,'HIGH':6,'MEDIUM':3}
    deduction=sum(min(30,x['value']*weights.get(x['severity'],1)) for x in checks)
    flags=[]
    if SECRET_KEY=='dev-only-change-me': flags.append('Secret key masih default')
    if app.debug: flags.append('Mode debug aktif')
    score=max(0,100-deduction-len(flags)*15)
    routes=[{'rule':r.rule,'endpoint':r.endpoint,'methods':','.join(sorted(r.methods-{'HEAD','OPTIONS'}))} for r in sorted(app.url_map.iter_rules(),key=lambda x:x.rule) if r.endpoint!='static']
    grade='SEHAT' if score>=85 else ('PERLU PERHATIAN' if score>=65 else 'BERISIKO')
    return {'score':score,'grade':grade,'checks':checks,'security_flags':flags,'route_count':len(routes),'routes':routes}

@app.route('/innovation-center',methods=['GET','POST'])
@login_required
@role_required('admin','bendahara','supervisor','branch_admin')
def innovation_center():
    innovation_refresh(); tab=request.args.get('tab','overview'); month=datetime.now().strftime('%Y-%m')
    if request.method=='POST':
        a=request.form.get('action')
        try:
            if a=='task': exec_sql('INSERT INTO workflow_tasks(title,description,priority,assigned_role,due_date,created_by) VALUES(?,?,?,?,?,?)',[request.form.get('title'),request.form.get('description'),request.form.get('priority'),request.form.get('assigned_role'),request.form.get('due_date'),session['user_id']])
            elif a=='reconcile':
                e=parse_float(request.form.get('expected')); p=parse_float(request.form.get('physical')); exec_sql('INSERT INTO cash_reconciliations(reconcile_date,expected_cash,physical_cash,difference,explanation,prepared_by) VALUES(?,?,?,?,?,?)',[request.form.get('date') or today_str(),e,p,p-e,request.form.get('explanation'),session['user_id']])
            elif a=='asset': exec_sql('INSERT INTO fixed_assets(asset_code,asset_name,category,acquisition_cost,useful_life_months,location,responsible_person,next_maintenance) VALUES(?,?,?,?,?,?,?,?)',[request.form.get('code') or gen_code('AST'),request.form.get('name'),request.form.get('category'),parse_float(request.form.get('cost')),int(request.form.get('life') or 0),request.form.get('location'),request.form.get('responsible'),request.form.get('maintenance')])
            elif a=='budget': exec_sql('INSERT OR REPLACE INTO budgets(fiscal_year,account_code,department,annual_budget,warning_percent,created_by) VALUES(?,?,?,?,?,?)',[int(request.form.get('year')),request.form.get('account'),request.form.get('department'),parse_float(request.form.get('amount')),parse_float(request.form.get('warning') or 90),session['user_id']])
            elif a=='ticket': exec_sql('INSERT INTO helpdesk_tickets(ticket_no,member_id,category,subject,description,priority,sla_due) VALUES(?,?,?,?,?,?,?)',[gen_code('TKT'),request.form.get('member_id') or None,request.form.get('category'),request.form.get('subject'),request.form.get('description'),request.form.get('priority'),request.form.get('sla')])
            elif a=='closing': exec_sql('UPDATE monthly_closing SET is_done=?,note=? WHERE id=?',[1 if request.form.get('done') else 0,request.form.get('note'),request.form.get('id')])
            elif a=='backup': innovation_backup(request.form.get('note',''))
            elif a=='resolve': exec_sql("UPDATE early_warnings SET status='RESOLVED' WHERE id=?",[request.form.get('id')])
            flash('Data berhasil diproses.','success')
        except Exception as e: flash(f'Gagal: {e}','error')
        return redirect(url_for('innovation_center',tab=request.form.get('tab',tab)))
    data={'tasks':q_all("SELECT * FROM workflow_tasks WHERE status='OPEN' ORDER BY id DESC"),'reminders':q_all('SELECT r.*,m.name FROM reminder_queue r LEFT JOIN members m ON m.id=r.member_id ORDER BY r.id DESC'),'recons':q_all('SELECT * FROM cash_reconciliations ORDER BY id DESC'),'closing':q_all('SELECT * FROM monthly_closing WHERE period_month=? ORDER BY step_key',[month]),'assets':q_all('SELECT * FROM fixed_assets ORDER BY id DESC'),'budgets':q_all('SELECT * FROM budgets ORDER BY fiscal_year DESC'),'tickets':q_all("SELECT t.*,m.name FROM helpdesk_tickets t LEFT JOIN members m ON m.id=t.member_id WHERE t.status!='CLOSED' ORDER BY t.id DESC"),'warnings':q_all("SELECT * FROM early_warnings WHERE status='OPEN' ORDER BY id DESC"),'backups':q_all('SELECT * FROM backup_runs ORDER BY id DESC'),'members':q_all("SELECT id,name FROM members WHERE status='Aktif'"),'accounts':q_all('SELECT account_code,account_name FROM accounts ORDER BY account_code'),'health':build_smart_health_report()}
    body=render_template_string(INNOVATION_HTML,tab=tab,data=data,month=month,year=datetime.now().year,rupiah=rupiah)
    return render_page('Pusat Inovasi',body)

INNOVATION_HTML="""
<div class='card'><h2>◆ Pusat Inovasi Koperasi</h2><div class='muted small'>Otomatisasi, risiko, rekonsiliasi, aset, anggaran, layanan anggota, keamanan dan early warning.</div></div>
<div class='quick-actions'>{% for k,l in [('overview','Ringkasan'),('tasks','Tugas'),('collection','Penagihan'),('reconcile','Rekonsiliasi'),('closing','Closing'),('assets','Aset'),('budget','Anggaran'),('helpdesk','Helpdesk'),('health','Smart Health'),('security','Keamanan'),('warnings','Peringatan')] %}<a href='?tab={{k}}' style="{{'border-color:var(--primary);color:var(--primary)' if tab==k else ''}}">{{l}}</a>{% endfor %}</div>
{% if tab=='overview' %}<div class='metrics'><div class='metric'><div class='label'>Tugas</div><div class='value'>{{data.tasks|length}}</div></div><div class='metric'><div class='label'>Reminder</div><div class='value'>{{data.reminders|length}}</div></div><div class='metric'><div class='label'>Tiket</div><div class='value'>{{data.tickets|length}}</div></div><div class='metric'><div class='label'>Peringatan</div><div class='value'>{{data.warnings|length}}</div></div></div><div class='card'><h3>Backup & Disaster Recovery</h3><form method='post'><input type='hidden' name='action' value='backup'><input name='note' placeholder='Catatan'><button>Buat Backup</button></form><div class='table-wrap'><table><tr><th>Waktu</th><th>File</th><th>Status</th></tr>{% for x in data.backups %}<tr><td>{{x.backup_time}}</td><td>{{x.file_name}}</td><td>{{x.status}}</td></tr>{% endfor %}</table></div></div>
{% elif tab=='tasks' %}<div class='card'><form method='post' class='grid'><input type='hidden' name='action' value='task'><input name='title' placeholder='Judul tugas' required><input name='description' placeholder='Deskripsi'><select name='priority'><option>NORMAL</option><option>HIGH</option><option>URGENT</option></select><select name='assigned_role'><option>admin</option><option>bendahara</option><option>supervisor</option></select><input type='date' name='due_date'><button>Buat Tugas</button></form></div><div class='card'><div class='table-wrap'><table><tr><th>Tugas</th><th>Prioritas</th><th>PIC</th><th>Due</th></tr>{% for x in data.tasks %}<tr><td>{{x.title}}</td><td>{{x.priority}}</td><td>{{x.assigned_role}}</td><td>{{x.due_date}}</td></tr>{% endfor %}</table></div></div>
{% elif tab=='collection' %}<div class='card'><h3>Reminder Angsuran Otomatis</h3><div class='table-wrap'><table><tr><th>Anggota</th><th>Jenis</th><th>Jatuh Tempo</th><th>Pesan</th></tr>{% for x in data.reminders %}<tr><td>{{x.name}}</td><td>{{x.reminder_type}}</td><td>{{x.due_date}}</td><td>{{x.message}}</td></tr>{% endfor %}</table></div></div>
{% elif tab=='reconcile' %}<div class='card'><form method='post'><input type='hidden' name='action' value='reconcile'><input type='date' name='date'><input type='number' name='expected' placeholder='Kas sistem' required><input type='number' name='physical' placeholder='Kas fisik' required><input name='explanation' placeholder='Penjelasan'><button>Simpan</button></form></div><div class='card'><div class='table-wrap'><table><tr><th>Tanggal</th><th>Sistem</th><th>Fisik</th><th>Selisih</th></tr>{% for x in data.recons %}<tr><td>{{x.reconcile_date}}</td><td>{{rupiah(x.expected_cash)}}</td><td>{{rupiah(x.physical_cash)}}</td><td>{{rupiah(x.difference)}}</td></tr>{% endfor %}</table></div></div>
{% elif tab=='closing' %}<div class='card'><h3>Closing {{month}}</h3>{% for x in data.closing %}<form method='post' style='display:flex;gap:8px;padding:8px;border-bottom:1px solid var(--border)'><input type='hidden' name='action' value='closing'><input type='hidden' name='id' value='{{x.id}}'><input type='checkbox' name='done' {{'checked' if x.is_done else ''}} style='width:18px;min-height:0'><span style='flex:1'>{{x.step_label}}</span><input name='note' value='{{x.note or ""}}'><button class='btn-sm'>Simpan</button></form>{% endfor %}</div>
{% elif tab=='assets' %}<div class='card'><form method='post'><input type='hidden' name='action' value='asset'><input name='name' placeholder='Nama aset' required><input name='category' placeholder='Kategori'><input type='number' name='cost' placeholder='Harga'><input type='number' name='life' placeholder='Umur bulan'><input name='location' placeholder='Lokasi'><input name='responsible' placeholder='PIC'><input type='date' name='maintenance'><button>Tambah Aset</button></form></div><div class='card'><div class='table-wrap'><table><tr><th>Kode</th><th>Aset</th><th>Nilai</th><th>Lokasi</th></tr>{% for x in data.assets %}<tr><td>{{x.asset_code}}</td><td>{{x.asset_name}}</td><td>{{rupiah(x.acquisition_cost)}}</td><td>{{x.location}}</td></tr>{% endfor %}</table></div></div>
{% elif tab=='budget' %}<div class='card'><form method='post'><input type='hidden' name='action' value='budget'><input type='hidden' name='year' value='{{year}}'><select name='account'>{% for a in data.accounts %}<option value='{{a.account_code}}'>{{a.account_code}} - {{a.account_name}}</option>{% endfor %}</select><input name='department' placeholder='Departemen'><input type='number' name='amount' placeholder='Anggaran'><input type='number' name='warning' value='90'><button>Simpan</button></form></div><div class='card'><div class='table-wrap'><table><tr><th>Tahun</th><th>Akun</th><th>Departemen</th><th>Anggaran</th></tr>{% for x in data.budgets %}<tr><td>{{x.fiscal_year}}</td><td>{{x.account_code}}</td><td>{{x.department}}</td><td>{{rupiah(x.annual_budget)}}</td></tr>{% endfor %}</table></div></div>
{% elif tab=='helpdesk' %}<div class='card'><form method='post'><input type='hidden' name='action' value='ticket'><select name='member_id'><option value=''>Umum</option>{% for m in data.members %}<option value='{{m.id}}'>{{m.name}}</option>{% endfor %}</select><input name='category' placeholder='Kategori'><input name='subject' placeholder='Subjek' required><textarea name='description' placeholder='Keluhan'></textarea><select name='priority'><option>NORMAL</option><option>HIGH</option><option>URGENT</option></select><input type='datetime-local' name='sla'><button>Buat Tiket</button></form></div><div class='card'><div class='table-wrap'><table><tr><th>No</th><th>Anggota</th><th>Subjek</th><th>Status</th></tr>{% for x in data.tickets %}<tr><td>{{x.ticket_no}}</td><td>{{x.name or '-'}}</td><td>{{x.subject}}</td><td>{{x.status}}</td></tr>{% endfor %}</table></div></div>
{% elif tab=='health' %}<div class='metrics'><div class='metric'><div class='label'>Health Score</div><div class='value'>{{data.health.score}}/100</div><div class='sub'>{{data.health.grade}}</div></div><div class='metric'><div class='label'>Route</div><div class='value'>{{data.health.route_count}}</div></div><div class='metric'><div class='label'>Temuan Keamanan</div><div class='value'>{{data.health.security_flags|length}}</div></div></div>{% if data.health.security_flags %}<div class='card'><h3>Konfigurasi</h3>{% for x in data.health.security_flags %}<div class='flash flash-warning'>{{x}}</div>{% endfor %}</div>{% endif %}<div class='card'><h3>Audit Konsistensi Data</h3><div class='table-wrap'><table><tr><th>Pemeriksaan</th><th>Jumlah</th><th>Level</th><th>Rekomendasi</th></tr>{% for x in data.health.checks %}<tr><td>{{x.title}}</td><td><strong>{{x.value}}</strong></td><td>{{x.severity}}</td><td>{{x.recommendation}}</td></tr>{% endfor %}</table></div></div><div class='card'><h3>Route Registry</h3><div class='table-wrap' style='max-height:420px;overflow:auto'><table><tr><th>Route</th><th>Endpoint</th><th>Metode</th></tr>{% for x in data.health.routes %}<tr><td><code>{{x.rule}}</code></td><td>{{x.endpoint}}</td><td>{{x.methods}}</td></tr>{% endfor %}</table></div></div>
{% elif tab=='security' %}<div class='grid'><div class='col-6'><div class='card'><h3>Keamanan</h3><ul><li>PBKDF2 hash dan migrasi hash lama</li><li>Secret key environment</li><li>Audit log</li><li>Hak akses role</li></ul></div></div><div class='col-6'><div class='card'><h3>Privasi</h3><ul><li>Persetujuan pemrosesan data</li><li>Versi kebijakan</li><li>Permintaan koreksi/salinan</li><li>Retensi data</li></ul></div></div></div>
{% elif tab=='warnings' %}<div class='card'><h3>Early Warning Center</h3>{% for x in data.warnings %}<div class='card'><div class='kartu'><div><b>{{x.title}}</b><div class='muted small'>{{x.detail}}</div></div><form method='post'><input type='hidden' name='action' value='resolve'><input type='hidden' name='id' value='{{x.id}}'><button class='btn-sm btn-success'>Selesai</button></form></div></div>{% else %}<div class='muted'>Tidak ada peringatan.</div>{% endfor %}</div>{% endif %}
"""


